export default "TOM_COMPONENTS=false\\\" in warning\\n    assert \\\"Ask the flow owner\\\" in warning\\n    assert \\\"flow editor\\\" not in warning\\n\\n\\ndef test_warning_includes_nested_substitutions_once(saved_agent):\\n    saved_agent[\\\"nodes\\\"][0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] += \\\"\\\\n# customization\\\\n\\\"\\n    wrapper = {\\\"nodes\\\": [{\\\"data\\\": {\\\"type\\\": \\\"GroupNode\\\", \\\"node\\\": {\\\"flow\\\": {\\\"data\\\": saved_agent}}}}]}\\n    warning = describe_component_code_substitution(wrapper)\\n    assert warning.count(\\\"Agent (Agent-qa)\\\") == 1\\n\\n\\ndef test_unknown_component_is_not_reported_as_a_substitution(saved_agent):\\n    saved_agent[\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] = \\\"UnknownCustomComponent\\\"\\n    assert describe_component_code_substitution(saved_agent) is None\\n\\n\\n@pytest.mark.parametrize(\\\"allow_custom\\\", [False, True], ids=[\\\"substituted\\\", \\\"saved-code\\\"])\\n@pytest.mark.usefixtures(\\\"saved_agent\\\")\\nasync def test_code_only_edit_warns_when_server_component_succeeds(monkeypatch, allow_custom):\\n    \\\"\\\"\\\"Exercise a real component without an external model, including the permissive control.\\\"\\\"\\\"\\n    from lfx.graph import Graph\\n\\n    monkeypatch.setattr(get_settings_service().settings, \\\"allow_custom_components\\\", allow_custom)\\n    saved = deepcopy(components.component_cache.all_types_dict[\\\"input_output\\\"][\\\"ChatInput\\\"])\\n    code = saved[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n    signature = \\\"async def message_response(self) -> Message:\\\\n\\\"\\n    assert signature in code\\n    saved[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] = code.replace(\\n        signature, signature + '        raise RuntimeError(\\\"CUSTOM_CODE_RAN\\\")\\\\n', 1\\n    )\\n    payload = {\\n        \\\"nodes\\\": [{\\\"id\\\": \\\"ChatInput-qa\\\", \\\"data\\\": {\\\"id\\\": \\\"ChatInput-qa\\\", \\\"type\\\": \\\"ChatInput\\\", \\\"node\\\": saved}}],\\n        \\\"edges\\\": [],\\n    }\\n    warning = describe_component_code_substitution(payload)\\n    graph = Graph.from_payload(deepcopy(payload), emit_extension_events=False)\\n    graph.persist_messages = False\\n    component = graph.get_vertex(\\\"ChatInput-qa\\\").custom_component\\n    component.set(input_value=\\\"Server component completed\\\", should_store_message=False)\\n\\n    if allow_custom:\\n        assert warning is None\\n        with pytest.raises(RuntimeError, match=\\\"CUSTOM_CODE_RAN\\\"):\\n            await component.message_response()\\n    else:\\n        assert \\\"Chat Input (ChatInput-qa)\\\" in warning\\n        result = await component.message_response()\\n        assert result.text == \\\"Server component completed\\\"\\n        assert \\\"CUSTOM_CODE_RAN\\\" in saved[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_connection_string_parser.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1494f435a43ceab68777e472d2a14d2953f7a2a1b2d8b6845fb0a52290f4e45b\",\"content\":\"import pytest\\nfrom lfx.utils.connection_string_parser import transform_connection_string\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"connection_string\\\", \\\"expected\\\"),\\n    [\\n        (\\\"protocol:user:password@host\\\", \\\"protocol:user:password@host\\\"),\\n        (\\\"protocol:user@host\\\", \\\"protocol:user@host\\\"),\\n        (\\\"protocol:user:pass@word@host\\\", \\\"protocol:user:pass%40word@host\\\"),\\n        (\\\"protocol:user:pa:ss:word@host\\\", \\\"protocol:user:pa:ss:word@host\\\"),\\n        (\\\"user:password@host\\\", \\\"user:password@host\\\"),\\n        (\\\"protocol::password@host\\\", \\\"protocol::password@host\\\"),\\n        (\\\"protocol:user:password@\\\", \\\"protocol:user:password@\\\"),\\n        (\\\"protocol:user:pa@ss@word@host\\\", \\\"protocol:user:pa%40ss%40word@host\\\"),\\n        # '/' is left alone by quote()'s default safe='/' and must be encoded explicitly\\n        (\\\"protocol:user:p/ss@host\\\", \\\"protocol:user:p%2Fss@host\\\"),\\n        (\\\"protocol:user:a/b/c@host\\\", \\\"protocol:user:a%2Fb%2Fc@host\\\"),\\n        (\\n            \\\"postgresql://user:p@ss/w0rd@host:5432/db\\\",  # pragma: allowlist secret\\n            \\\"postgresql://user:p%40ss%2Fw0rd@host:5432/db\\\",  # pragma: allowlist secret\\n        ),\\n        # no password: the last ':' is the scheme separator, so there is nothing to encode\\n        (\\\"postgresql://user@host:5432/db\\\", \\\"postgresql://user@host:5432/db\\\"),\\n        (\\\"postgresql+psycopg://user@host:5432/db\\\", \\\"postgresql+psycopg://user@host:5432/db\\\"),\\n        (\\\"postgresql://@host:5432/db\\\", \\\"postgresql://@host:5432/db\\\"),\\n        # a password that starts with '//' is still encoded\\n        (\\n            \\\"postgresql://user://pw@host:5432/db\\\",  # pragma: allowlist secret\\n            \\\"postgresql://user:%2F%2Fpw@host:5432/db\\\",  # pragma: allowlist secret\\n        ),\\n    ],\\n)\\ndef test_transform_connection_string(connection_string, expected):\\n    assert transform_connection_string(connection_string) == expected\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_connector_loopback_ssrf.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e127c4ad8bd19e1a4e9417a9d43a78854bb64bf6df7ace6a9de7dff78b691f6d\",\"content\":\"\\\"\\\"\\\"Tests for the connector loopback carve-out in SSRF validation.\\n\\nConnector / model-provider components routinely target a *local* service (Ollama and LM Studio\\ndefault to ``http://localhost:11434`` / ``http://localhost:1234``; local vector stores bind to\\nloopback). ``validate_connector_url_for_ssrf`` therefore allows a *literal* loopback host by\\ndefault, while still blocking cloud-metadata, RFC1918, and hostnames that merely resolve to\\nloopback. A multi-tenant deployer can set ``connector_ssrf_allow_loopback=false`` to block\\nloopback too. The API Request component / database / git validators are unaffected.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError, validate_connector_url_for_ssrf\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _ssrf_enabled(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\", \\\"true\\\")\\n    monkeypatch.delenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", raising=False)\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"url\\\",\\n    [\\n        \\\"http://localhost:11434/api/tags\\\",\\n        \\\"http://127.0.0.1:11434/api/tags\\\",\\n        \\\"http://127.0.0.5:1234/v1\\\",\\n        \\\"http://[::1]:11434/api/tags\\\",\\n    ],\\n)\\ndef test_connector_allows_literal_loopback_by_default(monkeypatch, url):\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\", \\\"true\\\")\\n    # Must not raise \u2014 local model servers / vector stores are reachable.\\n    validate_connector_url_for_ssrf(url)\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"url\\\",\\n    [\\n        \\\"http://169.254.169.254/latest/meta-data/\\\",  # cloud metadata\\n        \\\"http://10.0.0.5:8000\\\",  # RFC1918\\n        \\\"http://192.168.1.10:11434\\\",  # RFC1918\\n        \\\"http://172.16.0.4:9000\\\",  # RFC1918\\n    ],\\n)\\ndef test_connector_still_blocks_metadata_and_private(monkeypatch, url):\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\", \\\"true\\\")\\n    with pytest.raises(SSRFProtectionError):\\n        validate_connector_url_for_ssrf(url)\\n\\n\\n@pytest.mark.parametrize(\\\"url\\\", [\\\"http://localhost:11434\\\", \\\"http://127.0.0.1:11434\\\", \\\"http://[::1]:11434\\\"])\\ndef test_connector_blocks_loopback_when_opted_out(monkeypatch, url):\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\", \\\"false\\\")\\n    with pytest.raises(SSRFProtectionError):\\n        validate_connector_url_for_ssrf(url)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_container_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"14c7a303369db55140e4b09b74fd505faf45a16c4bc83941b0ecaea95857e622\",\"content\":\"\\\"\\\"\\\"Test container detection and URL transformation utilities.\\\"\\\"\\\"\\n\\nimport socket\\nfrom pathlib import Path\\nfrom unittest.mock import mock_open, patch\\n\\nfrom lfx.utils.util import detect_container_environment, get_container_host, transform_localhost_url\\n\\n\\nclass TestDetectContainerEnvironment:\\n    \\\"\\\"\\\"Test the detect_container_environment function.\\\"\\\"\\\"\\n\\n    def test_detects_docker_via_dockerenv(self):\\n        \\\"\\\"\\\"Test detection of Docker via .dockerenv file.\\\"\\\"\\\"\\n        with patch.object(Path, \\\"exists\\\", return_value=True):\\n            result = detect_container_environment()\\n            assert result == \\\"docker\\\"\\n\\n    def test_detects_docker_via_cgroup(self):\\n        \\\"\\\"\\\"Test detection of Docker via /proc/self/cgroup.\\\"\\\"\\\"\\n        mock_cgroup_content = \\\"\\\"\\\"12:cpuset:/docker/abc123\\n11:memory:/docker/abc123\\n10:devices:/docker/abc123\\\"\\\"\\\"\\n\\n        mock_file = mock_open(read_data=mock_cgroup_content)\\n        with (\\n            patch.object(Path, \\\"exists\\\", return_value=False),\\n            patch.object(Path, \\\"open\\\", mock_file),\\n        ):\\n            result = detect_container_environment()\\n            assert result == \\\"docker\\\"\\n\\n    def test_detects_podman_via_cgroup(self):\\n        \\\"\\\"\\\"Test detection of Podman via /proc/self/cgroup.\\\"\\\"\\\"\\n        mock_cgroup_content = \\\"\\\"\\\"12:cpuset:/podman/xyz789\\n11:memory:/podman/xyz789\\\"\\\"\\\"\\n\\n        mock_file = mock_open(read_data=mock_cgroup_content)\\n        with (\\n            patch.object(Path, \\\"exists\\\", return_value=False),\\n            patch.object(Path, \\\"open\\\", mock_file),\\n        ):\\n            result = detect_container_environment()\\n            assert result == \\\"podman\\\"\\n\\n    def test_detects_podman_via_env_var(self):\\n        \\\"\\\"\\\"Test detection of Podman via container environment variable.\\\"\\\"\\\"\\n        with (\\n            patch.object(Path, \\\"exists\\\", return_value=False),\\n            patch(\\\"builtins.open\\\", side_effect=FileNotFoundError),\\n            patch(\\\"os.getenv\\\", return_value=\\\"podman\\\"),\\n        ):\\n            result = detect_container_environment()\\n            assert result == \\\"podman\\\"\\n\\n    def test_returns_none_when_not_in_container(self):\\n        \\\"\\\"\\\"Test returns None when not running in a container.\\\"\\\"\\\"\\n        mock_cgroup_content = \\\"\\\"\\\"12:cpuset:/\\n11:memory:/\\\"\\\"\\\"\\n\\n        mock_file = mock_open(read_data=mock_cgroup_content)\\n        with (\\n            patch.object(Path, \\\"exists\\\", return_value=False),\\n            patch.object(Path, \\\"open\\\", mock_file),\\n            patch(\\\"os.getenv\\\", return_value=None),\\n        ):\\n            result = detect_container_environment()\\n            assert result is None\\n\\n    def test_handles_missing_cgroup_file(self):\\n        \\\"\\\"\\\"Test gracefully handles missing /proc/self/cgroup file.\\\"\\\"\\\"\\n        with (\\n            patch.object(Path, \\\"exists\\\", return_value=False),\\n            patch.object(Path, \\\"open\\\", side_effect=FileNotFoundError),\\n            patch(\\\"os.getenv\\\", return_value=None),\\n        ):\\n            result = detect_container_environment()\\n            assert result is None\\n\\n    def test_handles_permission_error_on_cgroup(self):\\n        \\\"\\\"\\\"Test gracefully handles permission error on /proc/self/cgroup.\\\"\\\"\\\"\\n        with (\\n            patch.object(Path, \\\"exists\\\", return_value=False),\\n            patch.object(Path, \\\"open\\\", side_effect=PermissionError),\\n            patch(\\\"os.getenv\\\", return_value=None),\\n        ):\\n            result = detect_container_environment()\\n            assert result is None\\n\\n\\nclass TestGetContainerHost:\\n    \\\"\\\"\\\"Test the get_container_host function.\\\"\\\"\\\"\\n\\n    def test_returns_none_when_not_in_container(self):\\n        \\\"\\\"\\\"Test returns None when not in a container.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.detect_container_environment\\\", return_value=None):\\n            result = get_container_host()\\n            assert result is None\\n\\n    def test_returns_docker_internal_when_resolvable(self):\\n        \\\"\\\"\\\"Test returns host.docker.internal when it resolves (Docker Desktop).\\\"\\\"\\\"\\n        with (\\n            patch(\\\"lfx.utils.util.detect_container_environment\\\", return_value=\\\"docker\\\"),\\n            patch(\\\"socket.getaddrinfo\\\") as mock_getaddrinfo,\\n        ):\\n            # First call succeeds (host.docker.internal resolves)\\n            mock_getaddrinfo.return_value = [(\\\"dummy\\\", \\\"data\\\")]\\n\\n            result = get_container_host()\\n            assert result == \\\"host.docker.internal\\\"\\n            mock_getaddrinfo.assert_called_once_with(\\\"host.docker.internal\\\", None)\\n\\n    def test_returns_containers_internal_when_docker_internal_fails(self):\\n        \\\"\\\"\\\"Test returns host.containers.internal when host.docker.internal doesn't resolve.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"lfx.utils.util.detect_container_environment\\\", return_value=\\\"podman\\\"),\\n            patch(\\\"socket.getaddrinfo\\\") as mock_getaddrinfo,\\n        ):\\n            # First call fails (host.docker.internal doesn't resolve)\\n            # Second call succeeds (host.containers.internal resolves)\\n            def side_effect(hostname, _port):\\n                msg = \\\"Name or service not known\\\"\\n                if hostname == \\\"host.docker.internal\\\":\\n                    raise socket.gaierror(msg)\\n                return [(\\\"dummy\\\", \\\"data\\\")]\\n\\n            mock_getaddrinfo.side_effect = side_effect\\n\\n            result = get_container_host()\\n            assert result == \\\"host.containers.internal\\\"\\n\\n    def test_returns_gateway_ip_when_no_special_hosts_resolve(self):\\n        \\\"\\\"\\\"Test returns gateway IP from routing table when special hostnames don't resolve (Linux).\\\"\\\"\\\"\\n        # Mock routing table with gateway 172.17.0.1\\n        # Gateway hex 0111A8C0 = 01 11 A8 C0 in little-endian = C0.A8.11.01 = 192.168.17.1\\n        # Format: Iface Destination Gateway Flags RefCnt Use Metric Mask MTU Window IRTT\\n        mock_route_content = \\\"\\\"\\\"Iface\\tDestination\\tGateway \\tFlags\\tRefCnt\\tUse\\tMetric\\tMask\\t\\tMTU\\tWindow\\tIRTT\\neth0\\t00000000\\t0111A8C0\\t0003\\t0\\t0\\t0\\t00000000\\t0\\t0\\t0\\neth0\\t0011A8C0\\t00000000\\t0001\\t0\\t0\\t0\\t00FFFFFF\\t0\\t0\\t0\\\"\\\"\\\"\\n\\n        mock_file = mock_open(read_data=mock_route_content)\\n        with (\\n            patch(\\\"lfx.utils.util.detect_container_environment\\\", return_value=\\\"docker\\\"),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=socket.gaierror),\\n            patch.object(Path, \\\"open\\\", mock_file),\\n        ):\\n            result = get_container_host()\\n            # 0111A8C0 reversed in pairs: C0.A8.11.01 = 192.168.17.1\\n            assert result == \\\"192.168.17.1\\\"\\n\\n    def test_returns_none_when_all_methods_fail(self):\\n        \\\"\\\"\\\"Test returns None when all detection methods fail.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"lfx.utils.util.detect_container_environment\\\", return_value=\\\"docker\\\"),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=socket.gaierror),\\n            patch.object(Path, \\\"open\\\", side_effect=FileNotFoundError),\\n        ):\\n            result = get_container_host()\\n            assert result is None\\n\\n    def test_handles_malformed_routing_table(self):\\n        \\\"\\\"\\\"Test gracefully handles malformed routing table.\\\"\\\"\\\"\\n        mock_route_content = \\\"\\\"\\\"invalid data here\\\"\\\"\\\"\\n\\n        mock_file = mock_open(read_data=mock_route_content)\\n        with (\\n            patch(\\\"lfx.utils.util.detect_container_environment\\\", return_value=\\\"docker\\\"),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=socket.gaierror),\\n            patch.object(Path, \\\"open\\\", mock_file),\\n        ):\\n            result = get_container_host()\\n            assert result is None\\n\\n\\nclass TestTransformLocalhostUrl:\\n    \\\"\\\"\\\"Test the transform_localhost_url function.\\\"\\\"\\\"\\n\\n    def test_returns_original_url_when_not_in_container(self):\\n        \\\"\\\"\\\"Test returns original URL when not in a container.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=None):\\n            url = \\\"http://localhost:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == url\\n\\n    def test_transforms_localhost_to_docker_internal(self):\\n        \\\"\\\"\\\"Test transforms localhost to host.docker.internal in Docker.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            url = \\\"http://localhost:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://host.docker.internal:5001/api\\\"\\n\\n    def test_transforms_127001_to_docker_internal(self):\\n        \\\"\\\"\\\"Test transforms 127.0.0.1 to host.docker.internal in Docker.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            url = \\\"http://127.0.0.1:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://host.docker.internal:5001/api\\\"\\n\\n    def test_transforms_localhost_to_containers_internal(self):\\n        \\\"\\\"\\\"Test transforms localhost to host.containers.internal in Podman.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.containers.internal\\\"):\\n            url = \\\"http://localhost:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://host.containers.internal:5001/api\\\"\\n\\n    def test_transforms_127001_to_containers_internal(self):\\n        \\\"\\\"\\\"Test transforms 127.0.0.1 to host.containers.internal in Podman.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.containers.internal\\\"):\\n            url = \\\"http://127.0.0.1:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://host.containers.internal:5001/api\\\"\\n\\n    def test_transforms_localhost_to_gateway_ip_on_linux(self):\\n        \\\"\\\"\\\"Test transforms localhost to gateway IP on Linux containers.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"172.17.0.1\\\"):\\n            url = \\\"http://localhost:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://172.17.0.1:5001/api\\\"\\n\\n    def test_transforms_127001_to_gateway_ip_on_linux(self):\\n        \\\"\\\"\\\"Test transforms 127.0.0.1 to gateway IP on Linux containers.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"172.17.0.1\\\"):\\n            url = \\\"http://127.0.0.1:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://172.17.0.1:5001/api\\\"\\n\\n    def test_does_not_transform_non_localhost_urls(self):\\n        \\\"\\\"\\\"Test does not transform URLs that don't contain localhost or 127.0.0.1.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            url = \\\"http://example.com:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == url\\n\\n    def test_transforms_url_without_path(self):\\n        \\\"\\\"\\\"Test transforms URL without path.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            url = \\\"http://localhost:5001\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://host.docker.internal:5001\\\"\\n\\n    def test_transforms_url_with_complex_path(self):\\n        \\\"\\\"\\\"Test transforms URL with complex path and query parameters.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            url = \\\"http://localhost:5001/api/v1/convert?format=json&timeout=30\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://host.docker.internal:5001/api/v1/convert?format=json&timeout=30\\\"\\n\\n    def test_transforms_https_url(self):\\n        \\\"\\\"\\\"Test transforms HTTPS URLs.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            url = \\\"https://localhost:5001/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"https://host.docker.internal:5001/api\\\"\\n\\n    def test_transforms_url_without_port(self):\\n        \\\"\\\"\\\"Test transforms URL without explicit port.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            url = \\\"http://localhost/api\\\"\\n            result = transform_localhost_url(url)\\n            assert result == \\\"http://host.docker.internal/api\\\"\\n\\n    def test_handles_none_url_gracefully(self):\\n        \\\"\\\"\\\"Test returns None when URL is None without raising TypeError.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            result = transform_localhost_url(None)\\n            assert result is None\\n\\n    def test_handles_empty_string_url_gracefully(self):\\n        \\\"\\\"\\\"Test returns empty string when URL is empty string.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=\\\"host.docker.internal\\\"):\\n            result = transform_localhost_url(\\\"\\\")\\n            assert result == \\\"\\\"\\n\\n    def test_handles_none_url_when_not_in_container(self):\\n        \\\"\\\"\\\"Test returns None when URL is None and not in a container.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=None):\\n            result = transform_localhost_url(None)\\n            assert result is None\\n\\n    def test_handles_empty_string_url_when_not_in_container(self):\\n        \\\"\\\"\\\"Test returns empty string when URL is empty and not in a container.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.util.get_container_host\\\", return_value=None):\\n            result = transform_localhost_url(\\\"\\\")\\n            assert result == \\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_database_url_sanitization.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bbc0159e0fee6adfa5b45ea0c7cc2c302a4fe13acc9a6c27b3818919ee2377e4\",\"content\":\"\\\"\\\"\\\"Unit tests for database URL sanitization to prevent credential exposure.\\n\\nSecurity Issue: When DATABASE_URL is misconfigured, sensitive information\\n(username, password, database name, host) may be exposed in application logs.\\n\\nThis test suite validates that credentials are properly sanitized in error messages.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.utils.util_strings import is_valid_database_url, sanitize_database_url\\nfrom pydantic import ValidationError\\n\\n\\nclass TestDatabaseUrlCredentialExposure:\\n    \\\"\\\"\\\"Test that database credentials are NOT exposed in error messages.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"invalid_url\\\", \\\"credentials_that_must_not_appear\\\"),\\n        [\\n            # PostgreSQL with INVALID port syntax (double colon - the actual bug from screenshot)\\n            (\\n                \\\"postgresql+psycopg://myuser:mysecretpassword@127.0.0.1::5432/mydb?sslmode=disable\\\",\\n                [\\\"myuser\\\", \\\"mysecretpassword\\\"],\\n            ),\\n            # Invalid dialect/driver combination\\n            (\\n                \\\"invaliddriver://adminuser:secretpass123@localhost:5432/production\\\",\\n                [\\\"adminuser\\\", \\\"secretpass123\\\"],\\n            ),\\n            # Malformed URL with credentials\\n            (\\n                \\\"notavaliddb://rootuser:rootpassword@host/badformat\\\",\\n                [\\\"rootuser\\\", \\\"rootpassword\\\"],\\n            ),\\n        ],\\n    )\\n    def test_should_not_expose_credentials_when_database_url_is_invalid(\\n        self,\\n        invalid_url: str,\\n        credentials_that_must_not_appear: list[str],\\n        monkeypatch,\\n    ):\\n        \\\"\\\"\\\"Test that invalid database URL errors do not expose credentials.\\n\\n        SECURITY: This test validates that when a database URL validation fails,\\n        our custom error message does NOT contain the username or password.\\n\\n        Note: Pydantic's ValidationError includes input_value in its metadata,\\n        which we cannot control. We focus on sanitizing our error message text.\\n        \\\"\\\"\\\"\\n        # Arrange - Settings class reads from environment variables\\n        monkeypatch.setenv(\\\"LANGFLOW_DATABASE_URL\\\", invalid_url)\\n        monkeypatch.setenv(\\\"LANGFLOW_CONFIG_DIR\\\", \\\"/tmp/test_config\\\")\\n\\n        from lfx.services.settings.base import Settings\\n\\n        # Act & Assert\\n        with pytest.raises(ValidationError) as exc_info:\\n            Settings()\\n\\n        # Get only the first error's message (our controlled text)\\n        errors = exc_info.value.errors()\\n        assert len(errors) > 0\\n\\n        # Extract our custom error message - it's in the 'msg' field\\n        error_msg = errors[0].get(\\\"msg\\\", \\\"\\\")\\n\\n        # Assert: Credentials MUST NOT appear in OUR error message\\n        for credential in credentials_that_must_not_appear:\\n            assert credential not in error_msg, (\\n                f\\\"SECURITY VULNERABILITY: Credential '{credential}' was exposed!\\\\nError message: {error_msg}\\\"\\n            )\\n\\n        # Assert: Masked credentials MUST appear in our message\\n        assert \\\"***\\\" in error_msg, (\\n            f\\\"Sanitized credentials (***) not found in error message!\\\\nError message: {error_msg}\\\"\\n        )\\n\\n\\nclass TestSanitizeDatabaseUrl:\\n    \\\"\\\"\\\"Test the sanitize_database_url function.\\\"\\\"\\\"\\n\\n    def test_should_mask_username_and_password_in_postgresql_url(self):\\n        \\\"\\\"\\\"Test that PostgreSQL URL credentials are masked.\\\"\\\"\\\"\\n        # Arrange\\n        url = \\\"postgresql+psycopg://myuser:mypassword@localhost:5432/mydb\\\"\\n\\n        # Act\\n        sanitized = sanitize_database_url(url)\\n\\n        # Assert\\n        assert \\\"myuser\\\" not in sanitized\\n        assert \\\"mypassword\\\" not in sanitized\\n        assert \\\"***\\\" in sanitized\\n        assert \\\"localhost:5432\\\" in sanitized\\n        assert \\\"mydb\\\" in sanitized\\n\\n    def test_should_mask_credentials_in_mysql_url(self):\\n        \\\"\\\"\\\"Test that MySQL URL credentials are masked.\\\"\\\"\\\"\\n        # Arrange\\n        url = \\\"mysql+pymysql://admin:supersecret@db.example.com:3306/app\\\"\\n\\n        # Act\\n        sanitized = sanitize_database_url(url)\\n\\n        # Assert\\n        assert \\\"admin\\\" not in sanitized\\n        assert \\\"supersecret\\\" not in sanitized\\n        assert \\\"***\\\" in sanitized\\n\\n    def test_should_handle_url_without_credentials(self):\\n        \\\"\\\"\\\"Test that URL without credentials is returned unchanged.\\\"\\\"\\\"\\n        # Arrange\\n        url = \\\"sqlite:///./test.db\\\"\\n\\n        # Act\\n        sanitized = sanitize_database_url(url)\\n\\n        # Assert\\n        assert \\\"sqlite\\\" in sanitized\\n        assert \\\"test.db\\\" in sanitized\\n\\n    def test_should_handle_malformed_url_with_regex_fallback(self):\\n        \\\"\\\"\\\"Test that malformed URLs are sanitized via regex fallback.\\\"\\\"\\\"\\n        # Arrange - malformed URL that SQLAlchemy can't parse, with distinctive credentials\\n        url = \\\"notvalid://s3cr3tuser:s3cr3tpass@host/db\\\"\\n\\n        # Act\\n        sanitized = sanitize_database_url(url)\\n\\n        # Assert - credentials should be masked\\n        assert \\\"s3cr3tuser\\\" not in sanitized, f\\\"Credential 's3cr3tuser' was not masked in: {sanitized}\\\"\\n        assert \\\"s3cr3tpass\\\" not in sanitized, f\\\"Credential 's3cr3tpass' was not masked in: {sanitized}\\\"\\n        assert \\\"***\\\" in sanitized\\n\\n    def test_should_mask_password_only_url(self):\\n        \\\"\\\"\\\"Test that URL with password but no username is still masked.\\\"\\\"\\\"\\n        # Arrange - password-only auth (no username)\\n        url = \\\"postgresql://:password123@localhost:5432/db\\\"\\n\\n        # Act\\n        sanitized = sanitize_database_url(url)\\n\\n        # Assert\\n        assert \\\"password123\\\" not in sanitized, f\\\"Password was not masked in: {sanitized}\\\"\\n        assert \\\"***\\\" in sanitized\\n\\n    def test_should_handle_empty_url(self):\\n        \\\"\\\"\\\"Test that empty URL returns empty string.\\\"\\\"\\\"\\n        # Arrange\\n        url = \\\"\\\"\\n\\n        # Act\\n        sanitized = sanitize_database_url(url)\\n\\n        # Assert\\n        assert sanitized == \\\"\\\"\\n\\n    def test_should_handle_none_url(self):\\n        \\\"\\\"\\\"Test that None URL returns None.\\\"\\\"\\\"\\n        # Arrange\\n        url = None\\n\\n        # Act\\n        sanitized = sanitize_database_url(url)\\n\\n        # Assert\\n        assert sanitized is None\\n\\n\\nclass TestDatabaseUrlValidation:\\n    \\\"\\\"\\\"Test database URL validation functionality.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"url\\\", \\\"expected\\\"),\\n        [\\n            # Valid URLs\\n            (\\\"sqlite:///./test.db\\\", True),\\n            (\\\"sqlite+aiosqlite:///./test.db\\\", True),\\n            (\\\"postgresql://user:pass@localhost:5432/db\\\", True),\\n            (\\\"postgresql+psycopg://user:pass@localhost:5432/db\\\", True),\\n            (\\\"mysql+pymysql://user:pass@localhost:3306/db\\\", True),\\n            # Invalid URLs\\n            (\\\"not-a-url\\\", False),\\n            (\\\"http://example.com\\\", False),\\n            (\\\"ftp://files.example.com\\\", False),\\n            (\\\"\\\", False),\\n            # Invalid port syntax (the actual bug)\\n            (\\\"postgresql+psycopg://user:pass@localhost::5432/db\\\", False),\\n        ],\\n    )\\n    def test_should_validate_database_url_format(self, url: str, *, expected: bool):\\n        \\\"\\\"\\\"Test that is_valid_database_url correctly validates URL formats.\\\"\\\"\\\"\\n        # Act\\n        result = is_valid_database_url(url)\\n\\n        # Assert\\n        assert result == expected\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_env_var_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a87f1f884b09627a2b6b9501ed3c7d482dee458869e6e66355a9f49d8bff9504\",\"content\":\"\\\"\\\"\\\"Unit tests for the env-var fallback denylist (cross-environment leak guard).\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.utils.env_var_security import is_protected_env_var, safe_getenv\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"name\\\",\\n    [\\n        \\\"LANGFLOW_SECRET_KEY\\\",\\n        \\\"LANGFLOW_DATABASE_URL\\\",\\n        \\\"LANGFLOW_SUPERUSER_PASSWORD\\\",\\n        \\\"langflow_secret_key\\\",  # case-insensitive\\n        \\\"LFX_ANYTHING\\\",\\n        \\\"DATABASE_URL\\\",\\n        \\\"SECRET_KEY\\\",\\n        \\\"POSTGRES_PASSWORD\\\",\\n        \\\"PGVECTOR_CONNECTION_STRING\\\",\\n        \\\"AWS_SECRET_ACCESS_KEY\\\",\\n        \\\"AWS_ACCESS_KEY_ID\\\",\\n        \\\"PGPASSWORD\\\",\\n        \\\"REDIS_URL\\\",\\n        \\\"GITHUB_TOKEN\\\",\\n        \\\"GITLAB_TOKEN\\\",\\n        \\\"GOOGLE_APPLICATION_CREDENTIALS\\\",\\n        \\\"GCP_SA_KEY\\\",\\n        \\\"AZURE_CLIENT_SECRET\\\",\\n        # Auth / token-signing secrets\\n        \\\"JWT_SECRET\\\",\\n        \\\"SIGNING_KEY\\\",\\n        \\\"session_secret\\\",  # case-insensitive\\n        \\\"ENCRYPTION_KEY\\\",\\n        # OAuth / SSO client secrets\\n        \\\"CLIENT_SECRET\\\",\\n        \\\"GOOGLE_CLIENT_SECRET\\\",\\n        \\\"MICROSOFT_CLIENT_SECRET\\\",\\n        # Mail relay credentials\\n        \\\"SMTP_PASSWORD\\\",\\n        \\\"EMAIL_HOST_PASSWORD\\\",\\n        \\\"mongodb_uri\\\",  # case-insensitive\\n        \\\"\\\",  # empty fails closed\\n    ],\\n)\\ndef test_protected_names_are_blocked(name):\\n    assert is_protected_env_var(name) is True\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"name\\\",\\n    [\\n        \\\"OPENAI_API_KEY\\\",\\n        \\\"MY_CUSTOM_VALUE\\\",\\n        \\\"GREETING\\\",\\n        \\\"HTTP_PROXY\\\",\\n    ],\\n)\\ndef test_unprotected_names_are_allowed(name):\\n    assert is_protected_env_var(name) is False\\n\\n\\ndef test_safe_getenv_returns_none_for_protected(monkeypatch):\\n    \\\"\\\"\\\"A protected name must look unset even when it is actually set in the environment.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_SECRET_KEY\\\", \\\"super-secret-master-key\\\")\\n    monkeypatch.setenv(\\\"DATABASE_URL\\\", \\\"postgresql://user:pw@host/db\\\")\\n\\n    assert safe_getenv(\\\"LANGFLOW_SECRET_KEY\\\") is None\\n    assert safe_getenv(\\\"DATABASE_URL\\\") is None\\n\\n\\ndef test_safe_getenv_returns_value_for_allowed(monkeypatch):\\n    monkeypatch.setenv(\\\"MY_CUSTOM_VALUE\\\", \\\"ok\\\")\\n    assert safe_getenv(\\\"MY_CUSTOM_VALUE\\\") == \\\"ok\\\"\\n    assert safe_getenv(\\\"UNSET_VARIABLE_NAME\\\") is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_exceptions.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"89b7fb32fa3379f8bfc90b749c1e46dad3e8460665dd9e342b03b5f0cdce6b65\",\"content\":\"\\\"\\\"\\\"Tests for lfx.utils.exceptions formatting helpers.\\n\\nFocus: a flow loaded on an engine-only ``lfx`` (no bundles) fails deep in the\\nvertex build with a bare ``No module named '...'``. ``format_exception_message``\\nmust turn that into actionable ``pip install`` guidance on the server run path,\\nwhile letting the bundle-shim \\\"components moved to ...\\\" messages win verbatim.\\n\\\"\\\"\\\"\\n\\nfrom lfx.utils.exceptions import (\\n    format_exception_message,\\n    get_causing_exception,\\n    module_not_found_hint,\\n)\\n\\n\\ndef _wrap_like_create_class(exc: Exception) -> ValueError:\\n    \\\"\\\"\\\"Reproduce how ``custom.validate.create_class`` wraps a build failure.\\n\\n    It catches the original exception and re-raises a ValueError whose\\n    ``__cause__`` is the original, e.g. a ModuleNotFoundError raised when a\\n    component imports a provider SDK that is not installed.\\n    \\\"\\\"\\\"\\n    msg = f\\\"Error creating class. {type(exc).__name__}({exc!s}).\\\"\\n    try:\\n        raise ValueError(msg) from exc\\n    except ValueError as wrapped:\\n        return wrapped\\n\\n\\ndef _raise_like_shim(raw: ModuleNotFoundError) -> ModuleNotFoundError:\\n    \\\"\\\"\\\"Reproduce how a graduated bundle shim re-raises its curated message.\\n\\n    A shim catches the raw ``No module named 'lfx_<provider>'`` import error and\\n    re-raises a curated \\\"components moved to ...\\\" ModuleNotFoundError ``from`` it,\\n    so the chain bottoms out at the raw error two levels down.\\n    \\\"\\\"\\\"\\n    msg = (\\n        \\\"The 'datastax' components moved to the 'lfx-datastax' distribution. \\\"\\n        \\\"Install it with:  pip install lfx-datastax   \\\"\\n        \\\"(or 'pip install langflow', which bundles it).\\\"\\n    )\\n    try:\\n        raise ModuleNotFoundError(msg, name=\\\"lfx_datastax\\\") from raw\\n    except ModuleNotFoundError as curated:\\n        return curated\\n\\n\\nclass TestModuleNotFoundHint:\\n    def test_plain_module_not_found_gets_guidance(self):\\n        exc = ModuleNotFoundError(\\\"No module named 'langchain_chroma'\\\", name=\\\"langchain_chroma\\\")\\n        hint = module_not_found_hint(exc)\\n        assert hint is not None\\n        assert \\\"pip install langchain-chroma\\\" in hint\\n\\n    def test_shim_message_is_surfaced_verbatim(self):\\n        # Bundle shims raise a ModuleNotFoundError whose message is already the\\n        # curated \\\"components moved to ...\\\" guidance. It is more actionable than\\n        # anything we could regenerate, so surface it as-is instead of clobbering\\n        # it with the bare-module mapping.\\n        shim = ModuleNotFoundError(\\n            \\\"The 'datastax' components moved to the 'lfx-datastax' distribution. \\\"\\n            \\\"Install it with:  pip install lfx-datastax   \\\"\\n            \\\"(or 'pip install langflow', which bundles it).\\\",\\n            name=\\\"lfx_datastax\\\",\\n        )\\n        hint = module_not_found_hint(shim)\\n        assert hint == str(shim)\\n        assert \\\"pip install langflow\\\" in hint\\n\\n    def test_non_module_error_returns_none(self):\\n        assert module_not_found_hint(ValueError(\\\"boom\\\")) is None\\n\\n    def test_module_error_without_name_returns_none(self):\\n        # A plain ModuleNotFoundError lacking ``.name`` carries no module to map.\\n        assert module_not_found_hint(ModuleNotFoundError(\\\"No module named 'x'\\\")) is None\\n\\n\\nclass TestGetCausingException:\\n    def test_stops_at_curated_shim_error(self):\\n        # The real 3-level chain: a curated shim ModuleNotFoundError is itself\\n        # raised ``from`` the raw \\\"No module named\\\" cause. The walk must stop at\\n        # the curated error, not unwrap past it to the bare cause.\\n        raw = ModuleNotFoundError(\\\"No module named 'lfx_datastax'\\\", name=\\\"lfx_datastax\\\")\\n        curated = _raise_like_shim(raw)\\n        wrapped = _wrap_like_create_class(curated)\\n        assert get_causing_exception(wrapped) is curated\\n\\n    def test_unwraps_plain_module_not_found_to_root(self):\\n        # No curated message in the chain: still walk to the deepest cause.\\n        cause = ModuleNotFoundError(\\\"No module named 'langchain_chroma'\\\", name=\\\"langchain_chroma\\\")\\n        wrapped = _wrap_like_create_class(cause)\\n        assert get_causing_exception(wrapped) is cause\\n\\n\\nclass TestFormatExceptionMessage:\\n    def test_wrapped_module_not_found_surfaces_guidance(self):\\n        # The exact shape Gabriel hit: create_class wraps the SDK import failure.\\n        cause = ModuleNotFoundError(\\\"No module named 'langchain_chroma'\\\", name=\\\"langchain_chroma\\\")\\n        wrapped = _wrap_like_create_class(cause)\\n        msg = format_exception_message(wrapped)\\n        assert \\\"pip install langchain-chroma\\\" in msg\\n\\n    def test_graduated_shim_message_wins_over_raw_cause(self):\\n        # The graduated case Gabriel flagged: the chain bottoms out at the raw\\n        # \\\"No module named 'lfx_datastax'\\\", so the old deepest-cause walk dropped\\n        # the curated text and regenerated a bare \\\"pip install lfx-datastax\\\".\\n        # The curated shim message must win verbatim instead.\\n        raw = ModuleNotFoundError(\\\"No module named 'lfx_datastax'\\\", name=\\\"lfx_datastax\\\")\\n        curated = _raise_like_shim(raw)\\n        wrapped = _wrap_like_create_class(curated)\\n        msg = format_exception_message(wrapped)\\n        assert \\\"moved to the 'lfx-datastax' distribution\\\" in msg\\n        # The \\\"or pip install langflow, which bundles it\\\" clause is the part that\\n        # the regenerated bare-module guidance cannot reproduce.\\n        assert \\\"pip install langflow\\\" in msg\\n        # Not the create_class wrapper, and not the regenerated bare-module text.\\n        assert not msg.startswith(\\\"Error creating class\\\")\\n        assert \\\"moved out of the lfx engine\\\" not in msg\\n\\n    def test_syntax_error_still_handled(self):\\n        try:\\n            compile(\\\"def (:\\\", \\\"<flow>\\\", \\\"exec\\\")\\n        except SyntaxError as syn:\\n            wrapped = _wrap_like_create_class(syn)\\n            msg = format_exception_message(wrapped)\\n            assert \\\"Syntax error in code\\\" in msg\\n\\n    def test_unrelated_error_is_unchanged(self):\\n        msg = format_exception_message(ValueError(\\\"something else\\\"))\\n        assert msg == \\\"something else\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_file_path_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0383dcf4aafd4573b4b5e6e1eb3c72efb2565fe3608ca20c3d02d932fbf69ce9\",\"content\":\"\\\"\\\"\\\"Tests for local file-path containment (LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS).\\\"\\\"\\\"\\n\\nfrom contextlib import contextmanager\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx.utils.file_path_security import (\\n    LocalFileAccessError,\\n    StorageNamespaceError,\\n    component_file_access_scopes,\\n    enforce_local_file_access,\\n    is_local_file_access_restricted,\\n    validate_storage_key,\\n)\\n\\n\\n@contextmanager\\ndef mock_settings(*, restricted: bool, config_dir: str, database_url: str = \\\"\\\"):\\n    with patch(\\\"lfx.utils.file_path_security.get_settings_service\\\") as mock_get:\\n        settings = MagicMock()\\n        settings.settings.restrict_local_file_access = restricted\\n        settings.settings.config_dir = config_dir\\n        # Explicit string so the reserved-DB derivation in _reserved_secret_paths is deterministic.\\n        settings.settings.database_url = database_url\\n        mock_get.return_value = settings\\n        yield\\n\\n\\ndef test_disabled_is_noop(tmp_path):\\n    \\\"\\\"\\\"When restriction is off, any path is allowed (single-tenant default).\\\"\\\"\\\"\\n    with mock_settings(restricted=False, config_dir=str(tmp_path)):\\n        assert is_local_file_access_restricted() is False\\n        # An obviously-outside path is returned unchanged.\\n        assert enforce_local_file_access(\\\"/etc/passwd\\\") == Path(\\\"/etc/passwd\\\")\\n\\n\\ndef test_component_scopes_include_trusted_public_source_flow():\\n    \\\"\\\"\\\"Bundle consumers can re-check public attachments after flow_id becomes visitor-virtual.\\\"\\\"\\\"\\n    component = MagicMock()\\n    component._user_id = None\\n    component._vertex.graph.user_id = \\\"public-owner-id\\\"\\n    component._vertex.graph.flow_id = \\\"visitor-virtual-flow-id\\\"\\n    component._vertex.graph.source_flow_id = \\\"public-source-flow-id\\\"\\n\\n    assert component_file_access_scopes(component) == (\\n        \\\"public-owner-id\\\",\\n        \\\"visitor-virtual-flow-id\\\",\\n        \\\"public-source-flow-id\\\",\\n    )\\n\\n\\ndef test_path_inside_storage_allowed(tmp_path):\\n    \\\"\\\"\\\"A path inside the storage data dir is allowed when restricted.\\\"\\\"\\\"\\n    inside = tmp_path / \\\"flow-id\\\" / \\\"upload.txt\\\"\\n    inside.parent.mkdir(parents=True)\\n    inside.write_text(\\\"hi\\\")\\n    with mock_settings(restricted=True, config_dir=str(tmp_path)):\\n        assert enforce_local_file_access(str(inside), scope_ids=[\\\"flow-id\\\"]) == Path(str(inside))\\n\\n\\ndef test_single_string_scope_is_not_split_into_characters(tmp_path):\\n    inside = tmp_path / \\\"flow-id\\\" / \\\"file.txt\\\"\\n    inside.parent.mkdir(parents=True)\\n    inside.write_text(\\\"hi\\\")\\n\\n    with mock_settings(restricted=True, config_dir=str(tmp_path)):\\n        assert enforce_local_file_access(inside, scope_ids=\\\"flow-id\\\") == inside\\n\\n\\ndef test_absolute_path_outside_blocked(tmp_path):\\n    \\\"\\\"\\\"An absolute server path outside the storage dir is blocked when restricted.\\\"\\\"\\\"\\n    with mock_settings(restricted=True, config_dir=str(tmp_path)), pytest.raises(LocalFileAccessError):\\n        enforce_local_file_access(\\\"/etc/passwd\\\", scope_ids=[\\\"flow-id\\\"])\\n\\n\\ndef test_traversal_escape_blocked(tmp_path):\\n    \\\"\\\"\\\"A traversal string escaping the storage dir is blocked when restricted.\\\"\\\"\\\"\\n    escape = str(tmp_path / \\\"..\\\" / \\\"..\\\" / \\\"etc\\\" / \\\"passwd\\\")\\n    with mock_settings(restricted=True, config_dir=str(tmp_path)), pytest.raises(LocalFileAccessError):\\n        enforce_local_file_access(escape, scope_ids=[\\\"flow-id\\\"])\\n\\n\\ndef test_storage_dir_itself_blocked(tmp_path):\\n    \\\"\\\"\\\"The shared storage root cannot be enumerated by an individual tenant.\\\"\\\"\\\"\\n    with mock_settings(restricted=True, config_dir=str(tmp_path)), pytest.raises(LocalFileAccessError):\\n        enforce_local_file_access(str(tmp_path), scope_ids=[\\\"flow-id\\\"])\\n\\n\\ndef test_other_tenant_storage_scope_blocked(tmp_path):\\n    \\\"\\\"\\\"An authenticated tenant cannot read another tenant's upload directory.\\\"\\\"\\\"\\n    victim_file = tmp_path / \\\"victim-user\\\" / \\\"secret.txt\\\"\\n    victim_file.parent.mkdir()\\n    victim_file.write_text(\\\"tenant secret\\\")\\n\\n    with mock_settings(restricted=True, config_dir=str(tmp_path)), pytest.raises(LocalFileAccessError):\\n        enforce_local_file_access(victim_file, scope_ids=[\\\"attacker-user\\\", \\\"attacker-flow\\\"])\\n\\n\\ndef test_missing_tenant_scope_fails_closed(tmp_path):\\n    upload = tmp_path / \\\"flow-id\\\" / \\\"upload.txt\\\"\\n    upload.parent.mkdir()\\n    upload.write_text(\\\"hi\\\")\\n\\n    with (\\n        mock_settings(restricted=True, config_dir=str(tmp_path)),\\n        pytest.raises(LocalFileAccessError, match=\\\"requires an authenticated user or flow scope\\\"),\\n    ):\\n        enforce_local_file_access(upload)\\n\\n\\ndef test_symlink_inside_storage_pointing_outside_blocked(tmp_path):\\n    \\\"\\\"\\\"A symlink that lives inside the storage dir but resolves outside it is blocked.\\n\\n    This guards the docstring promise that symlinks are resolved before the containment\\n    check. Without ``Path.resolve()`` (e.g. if it were replaced by ``Path.absolute()``,\\n    which does not follow symlinks) the link would appear to live inside storage and the\\n    escape would go undetected \u2014 so this test fails closed on that regression.\\n    \\\"\\\"\\\"\\n    storage = tmp_path / \\\"storage\\\"\\n    storage.mkdir()\\n    tenant_dir = storage / \\\"flow-id\\\"\\n    tenant_dir.mkdir()\\n    outside_secret = tmp_path / \\\"outside\\\" / \\\"secret.txt\\\"\\n    outside_secret.parent.mkdir()\\n    outside_secret.write_text(\\\"top secret\\\")\\n    link = tenant_dir / \\\"escape.txt\\\"\\n    link.symlink_to(outside_secret)\\n    with mock_settings(restricted=True, config_dir=str(storage)), pytest.raises(LocalFileAccessError):\\n        enforce_local_file_access(str(link), scope_ids=[\\\"flow-id\\\"])\\n\\n\\ndef test_symlink_inside_storage_pointing_inside_allowed(tmp_path):\\n    \\\"\\\"\\\"A symlink inside storage that resolves to another in-storage file is allowed.\\n\\n    Positive control proving the symlink test above blocks because of the escape, not\\n    merely because a symlink is present.\\n    \\\"\\\"\\\"\\n    storage = tmp_path / \\\"storage\\\"\\n    storage.mkdir()\\n    tenant_dir = storage / \\\"flow-id\\\"\\n    tenant_dir.mkdir()\\n    real = tenant_dir / \\\"real.txt\\\"\\n    real.write_text(\\\"hi\\\")\\n    link = tenant_dir / \\\"link.txt\\\"\\n    link.symlink_to(real)\\n    with mock_settings(restricted=True, config_dir=str(storage)):\\n        assert enforce_local_file_access(str(link), scope_ids=[\\\"flow-id\\\"]) == real.resolve()\\n\\n\\n@pytest.mark.parametrize(\\\"name\\\", [\\\"secret_key\\\", \\\"private_key.pem\\\", \\\"public_key.pem\\\"])\\ndef test_reserved_secret_file_blocked(tmp_path, name):\\n    \\\"\\\"\\\"The exact reserved-file check still denies secrets if scope containment widens.\\\"\\\"\\\"\\n    (tmp_path / name).write_text(\\\"SENSITIVE\\\")\\n    with (\\n        mock_settings(restricted=True, config_dir=str(tmp_path)),\\n        patch(\\\"lfx.utils.file_path_security._scope_roots\\\", return_value=(tmp_path.resolve(),)),\\n        pytest.raises(LocalFileAccessError, match=\\\"server-managed file\\\"),\\n    ):\\n        enforce_local_file_access(str(tmp_path / name), scope_ids=[\\\"flow-id\\\"])\\n\\n\\ndef test_reserved_secret_file_via_traversal_blocked(tmp_path):\\n    \\\"\\\"\\\"A traversal that resolves back to a reserved secret file is denied.\\n\\n    This is the actual exploit shape: a storage-path input like \\\"<flow>/../secret_key\\\" routes\\n    through build_full_path (no '..' check) to <config_dir>/<flow>/../secret_key, which resolves\\n    back inside the boundary.\\n    \\\"\\\"\\\"\\n    (tmp_path / \\\"secret_key\\\").write_text(\\\"MASTER KEY\\\")\\n    traversal = str(tmp_path / \\\"some-flow\\\" / \\\"..\\\" / \\\"secret_key\\\")\\n    with (\\n        mock_settings(restricted=True, config_dir=str(tmp_path)),\\n        patch(\\\"lfx.utils.file_path_security._scope_roots\\\", return_value=(tmp_path.resolve(),)),\\n        pytest.raises(LocalFileAccessError, match=\\\"server-managed file\\\"),\\n    ):\\n        enforce_local_file_access(traversal, scope_ids=[\\\"some-flow\\\"])\\n\\n\\ndef test_reserved_db_file_blocked(tmp_path):\\n    \\\"\\\"\\\"The SQLite DB under config_dir (save_db_in_config_dir) is denied.\\\"\\\"\\\"\\n    db = tmp_path / \\\"flow-id\\\" / \\\"langflow.db\\\"\\n    db.parent.mkdir()\\n    db.write_text(\\\"db\\\")\\n    with (\\n        mock_settings(restricted=True, config_dir=str(tmp_path), database_url=f\\\"sqlite:///{db}\\\"),\\n        pytest.raises(LocalFileAccessError, match=\\\"server-managed file\\\"),\\n    ):\\n        enforce_local_file_access(str(db), scope_ids=[\\\"flow-id\\\"])\\n\\n\\n@pytest.mark.parametrize(\\\"suffix\\\", [\\\"-wal\\\", \\\"-shm\\\", \\\"-journal\\\"])\\ndef test_reserved_db_sidecar_blocked(tmp_path, suffix):\\n    \\\"\\\"\\\"SQLite WAL/SHM/journal sidecars hold un-checkpointed DB pages and are denied too.\\\"\\\"\\\"\\n    db = tmp_path / \\\"flow-id\\\" / \\\"langflow.db\\\"\\n    db.parent.mkdir()\\n    sidecar = tmp_path / \\\"flow-id\\\" / f\\\"langflow.db{suffix}\\\"\\n    sidecar.write_text(\\\"pages\\\")\\n    with (\\n        mock_settings(restricted=True, config_dir=str(tmp_path), database_url=f\\\"sqlite:///{db}\\\"),\\n        pytest.raises(LocalFileAccessError, match=\\\"server-managed file\\\"),\\n    ):\\n        enforce_local_file_access(str(sidecar), scope_ids=[\\\"flow-id\\\"])\\n\\n\\ndef test_reserved_db_with_async_driver_and_query_blocked(tmp_path):\\n    \\\"\\\"\\\"An async sqlite URL with a query string still resolves to the protected DB file.\\\"\\\"\\\"\\n    db = tmp_path / \\\"flow-id\\\" / \\\"langflow.db\\\"\\n    db.parent.mkdir()\\n    db.write_text(\\\"db\\\")\\n    url = f\\\"sqlite+aiosqlite:///{db}?check_same_thread=false\\\"\\n    with (\\n        mock_settings(restricted=True, config_dir=str(tmp_path), database_url=url),\\n        pytest.raises(LocalFileAccessError, match=\\\"server-managed file\\\"),\\n    ):\\n        enforce_local_file_access(str(db), scope_ids=[\\\"flow-id\\\"])\\n\\n\\ndef test_upload_named_like_secret_in_flow_subdir_allowed(tmp_path):\\n    \\\"\\\"\\\"A tenant upload that merely shares a reserved name but lives in a flow subdir stays readable.\\n\\n    Proves the denial matches the exact config_dir location, not the basename anywhere.\\n    \\\"\\\"\\\"\\n    upload = tmp_path / \\\"flow-id\\\" / \\\"secret_key\\\"\\n    upload.parent.mkdir(parents=True)\\n    upload.write_text(\\\"just a user file named secret_key\\\")\\n    with mock_settings(restricted=True, config_dir=str(tmp_path)):\\n        assert enforce_local_file_access(str(upload), scope_ids=[\\\"flow-id\\\"]) == Path(str(upload))\\n\\n\\ndef _component(user_id=None, flow_id=None, source_flow_id=None):\\n    \\\"\\\"\\\"Build a component stub whose graph carries the given storage scopes.\\\"\\\"\\\"\\n    component = MagicMock()\\n    component._user_id = user_id\\n    component._vertex.graph.user_id = None\\n    component._vertex.graph.flow_id = flow_id\\n    component._vertex.graph.source_flow_id = source_flow_id\\n    return component\\n\\n\\nclass TestValidateStorageKey:\\n    \\\"\\\"\\\"Ownership enforcement for ``<namespace>/<file_name>`` storage keys.\\n\\n    Storage keys are the internal addressing scheme for uploads. The namespace segment comes\\n    from a tenant-controlled component input, so it must be checked against the executing\\n    graph's own scopes rather than trusted for its shape.\\n    \\\"\\\"\\\"\\n\\n    def test_own_user_namespace_allowed(self):\\n        component = _component(user_id=\\\"owner-id\\\")\\n        assert validate_storage_key(component, \\\"owner-id/report.csv\\\") == (\\\"owner-id\\\", \\\"report.csv\\\")\\n\\n    def test_executing_flow_namespace_allowed(self):\\n        \\\"\\\"\\\"Legacy per-flow uploads live under the flow id rather than the user id.\\\"\\\"\\\"\\n        component = _component(user_id=\\\"owner-id\\\", flow_id=\\\"flow-id\\\")\\n        assert validate_storage_key(component, \\\"flow-id/report.csv\\\") == (\\\"flow-id\\\", \\\"report.csv\\\")\\n\\n    def test_public_source_flow_namespace_allowed(self):\\n        component = _component(user_id=\\\"owner-id\\\", flow_id=\\\"virtual-id\\\", source_flow_id=\\\"public-flow-id\\\")\\n        assert validate_storage_key(component, \\\"public-flow-id/report.csv\\\") == (\\\"public-flow-id\\\", \\\"report.csv\\\")\\n\\n    def test_other_user_namespace_denied(self):\\n        \\\"\\\"\\\"The reported issue: addressing another user's upload namespace by storage key.\\\"\\\"\\\"\\n        component = _component(user_id=\\\"attacker-id\\\", flow_id=\\\"attacker-flow-id\\\")\\n        with pytest.raises(StorageNamespaceError, match=\\\"outside the authenticated user's\\\"):\\n            validate_storage_key(component, \\\"victim-id/secret.txt\\\")\\n\\n    def test_denial_is_not_gated_on_restrict_local_file_access(self):\\n        \\\"\\\"\\\"Namespace ownership holds regardless of the local-file containment flag.\\n\\n        The flag exists to turn off reading local *server* files by absolute path, which is a\\n        legitimate single-tenant feature. Addressing another principal's namespace never is.\\n        \\\"\\\"\\\"\\n        component = _component(user_id=\\\"attacker-id\\\")\\n        with (\\n            mock_settings(restricted=False, config_dir=\\\"/tmp/whatever\\\"),\\n            pytest.raises(StorageNamespaceError),\\n        ):\\n            validate_storage_key(component, \\\"victim-id/secret.txt\\\")\\n\\n    @pytest.mark.parametrize(\\n        \\\"file_name\\\",\\n        [\\\"../victim-id/secret.txt\\\", \\\"../secret_key\\\", \\\"sub/dir.txt\\\", \\\"a\\\\\\\\b.txt\\\", \\\"a\\\\x00b.txt\\\", \\\"..\\\"],\\n    )\\n    def test_traversal_in_file_name_denied(self, file_name):\\n        \\\"\\\"\\\"A traversal in the file name would escape an otherwise in-scope namespace.\\\"\\\"\\\"\\n        component = _component(user_id=\\\"owner-id\\\")\\n        with pytest.raises(StorageNamespaceError, match=\\\"path separators or traversal\\\"):\\n            validate_storage_key(component, f\\\"owner-id/{file_name}\\\")\\n\\n    @pytest.mark.parametrize(\\\"path\\\", [\\\"\\\", \\\"no-separator.txt\\\", \\\"/leading.txt\\\", \\\"trailing/\\\"])\\n    def test_malformed_key_denied(self, path):\\n        component = _component(user_id=\\\"owner-id\\\")\\n        with pytest.raises(StorageNamespaceError, match=\\\"Invalid storage path\\\"):\\n            validate_storage_key(component, path)\\n\\n    def test_unscoped_execution_keeps_legacy_behavior(self):\\n        \\\"\\\"\\\"Standalone ``lfx run`` graphs carry no user or flow id and no tenant boundary.\\\"\\\"\\\"\\n        component = _component()\\n        assert validate_storage_key(component, \\\"some-namespace/report.csv\\\") == (\\\"some-namespace\\\", \\\"report.csv\\\")\\n\\n\\nclass TestStorageRootFloor:\\n    \\\"\\\"\\\"``allow_storage_root`` is a containment floor for scope-less shared plumbing.\\n\\n    Shared readers (``base/data/storage_utils.py``) are handed paths that a component already\\n    scope-checked, so they have no user/flow scope of their own. They must still refuse paths\\n    outside the storage dir rather than skipping the control entirely.\\n    \\\"\\\"\\\"\\n\\n    def test_floor_denies_path_outside_storage_dir(self, tmp_path):\\n        with mock_settings(restricted=True, config_dir=str(tmp_path)), pytest.raises(LocalFileAccessError):\\n            enforce_local_file_access(\\\"/etc/passwd\\\", allow_storage_root=True)\\n\\n    def test_floor_allows_path_inside_storage_dir_without_scope(self, tmp_path):\\n        inside = tmp_path / \\\"flow-id\\\" / \\\"upload.txt\\\"\\n        inside.parent.mkdir(parents=True)\\n        inside.write_text(\\\"hi\\\")\\n        with mock_settings(restricted=True, config_dir=str(tmp_path)):\\n            assert enforce_local_file_access(str(inside), allow_storage_root=True) == inside.resolve()\\n\\n    @pytest.mark.parametrize(\\\"name\\\", [\\\"secret_key\\\", \\\"private_key.pem\\\", \\\"public_key.pem\\\"])\\n    def test_floor_still_denies_reserved_secrets(self, tmp_path, name):\\n        \\\"\\\"\\\"The floor widens the root to config_dir, where the secrets live - they stay denied.\\\"\\\"\\\"\\n        (tmp_path / name).write_text(\\\"x\\\")\\n        with mock_settings(restricted=True, config_dir=str(tmp_path)), pytest.raises(LocalFileAccessError):\\n            enforce_local_file_access(str(tmp_path / name), allow_storage_root=True)\\n\\n    def test_floor_still_denies_sqlite_db_in_config_dir(self, tmp_path):\\n        db = tmp_path / \\\"langflow.db\\\"\\n        db.write_text(\\\"x\\\")\\n        with (\\n            mock_settings(restricted=True, config_dir=str(tmp_path), database_url=f\\\"sqlite:///{db}\\\"),\\n            pytest.raises(LocalFileAccessError),\\n        ):\\n            enforce_local_file_access(str(db), allow_storage_root=True)\\n\\n    def test_floor_is_noop_when_restriction_disabled(self, tmp_path):\\n        with mock_settings(restricted=False, config_dir=str(tmp_path)):\\n            assert enforce_local_file_access(\\\"/etc/passwd\\\", allow_storage_root=True) == Path(\\\"/etc/passwd\\\")\\n\\n    def test_scoped_call_is_unaffected_by_default(self, tmp_path):\\n        \\\"\\\"\\\"Without the flag a scope is still mandatory - existing callers keep failing closed.\\\"\\\"\\\"\\n        with mock_settings(restricted=True, config_dir=str(tmp_path)), pytest.raises(LocalFileAccessError):\\n            enforce_local_file_access(str(tmp_path / \\\"x.txt\\\"))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_lazy_import.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"18f53234e850cd49b124439337763c2c416414350f7aee42370adb3afd3d9908\",\"content\":\"\\\"\\\"\\\"Contract tests for the stable lazy-import helper (BUNDLE_API surface).\\n\\n``lfx.utils.lazy_import.import_mod`` is called by separately-installed bundle\\npackages from their ``__getattr__``-based ``__init__.py`` files, so its home,\\nname, and behavior are contract-stable (see BUNDLE_API.md).  The legacy\\ninternal path ``lfx.components._importing`` must keep re-exporting the same\\nobject for backward compatibility.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\n\\n\\ndef test_legacy_path_reexports_the_same_object() -> None:\\n    \\\"\\\"\\\"lfx.components._importing.import_mod IS lfx.utils.lazy_import.import_mod.\\\"\\\"\\\"\\n    from lfx.components._importing import import_mod as legacy\\n    from lfx.utils.lazy_import import import_mod as canonical\\n\\n    assert legacy is canonical\\n    assert canonical.__module__ == \\\"lfx.utils.lazy_import\\\"\\n\\n\\ndef test_import_mod_attribute_from_module() -> None:\\n    \\\"\\\"\\\"The (attr, module, package) form imports a submodule and pulls the attribute.\\\"\\\"\\\"\\n    from lfx.utils.lazy_import import import_mod\\n\\n    result = import_mod(\\\"import_mod\\\", \\\"lazy_import\\\", \\\"lfx.utils\\\")\\n    assert callable(result)\\n\\n\\ndef test_import_mod_package_form() -> None:\\n    \\\"\\\"\\\"The module_name='__module__' form imports `.attr_name` from the package.\\\"\\\"\\\"\\n    from lfx.utils.lazy_import import import_mod\\n\\n    module = import_mod(\\\"lazy_import\\\", \\\"__module__\\\", \\\"lfx.utils\\\")\\n    assert module.__name__ == \\\"lfx.utils.lazy_import\\\"\\n\\n\\ndef test_missing_attribute_raises_attribute_error() -> None:\\n    \\\"\\\"\\\"The package form converts ModuleNotFoundError to AttributeError (PEP 562 shape).\\\"\\\"\\\"\\n    from lfx.utils.lazy_import import import_mod\\n\\n    with pytest.raises(AttributeError, match=\\\"no attribute\\\"):\\n        import_mod(\\\"does_not_exist_xyz\\\", \\\"__module__\\\", \\\"lfx.utils\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_outdated_component_code_substitution.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b16f4e571d181ab0439f1bf46030863714374e3de0f9ef2cdacb4bf830079016\",\"content\":\"\\\"\\\"\\\"Tests for outdated built-in code substitution on the normal build path (issue #14455).\\n\\nWith ``LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false`` the code stored in a node never runs:\\n``resolve_trusted_code_for_build`` swaps in this server's copy before executing. The hash gate\\nnevertheless refused any flow whose stored built-in code had drifted across an upgrade, so a\\nversion bump that touched one built-in broke every saved flow using it \u2014 while the unauthenticated\\npublic path already rebuilt the same flows with the server's code by default.\\n\\nThese tests pin the swap-by-type rule, the setting that turns it off, and the invariant that it\\nnever widens what can execute.\\n\\\"\\\"\\\"\\n\\nimport hashlib\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom lfx.services.catalog_policy import CatalogPolicySnapshot\\nfrom lfx.utils import flow_validation as fv\\nfrom lfx.utils.flow_validation import (\\n    CustomComponentValidationError,\\n    SubstitutableComponentTypes,\\n    check_flow_and_raise,\\n    collect_component_code_lookups,\\n    collect_component_hash_lookups,\\n    substitute_outdated_component_code_in_place,\\n    validate_flow_for_current_settings,\\n)\\n\\nCURRENT_CHAT_INPUT = \\\"# ChatInput v2 (this server)\\\"\\nSTORED_CHAT_INPUT = \\\"# ChatInput v1 (saved before the upgrade)\\\"\\n# A components_path component the operator installed under a name a built-in already uses.\\nOVERRIDE_CHAT_INPUT = \\\"# ChatInput (operator's components_path copy)\\\"\\n\\n\\ndef _hash(code: str) -> str:\\n    return hashlib.sha256(code.encode()).hexdigest()[:12]\\n\\n\\ndef _node(node_id: str, component_type, code: str | None, *, display_name: str | None = None) -> dict:\\n    template = {\\\"code\\\": {\\\"value\\\": code}} if code is not None else {}\\n    node_block: dict = {\\\"template\\\": template}\\n    if display_name is not None:\\n        node_block[\\\"display_name\\\"] = display_name\\n    return {\\\"id\\\": node_id, \\\"data\\\": {\\\"id\\\": node_id, \\\"type\\\": component_type, \\\"node\\\": node_block}}\\n\\n\\ndef _code_of(node: dict) -> str | None:\\n    return node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"code\\\"][\\\"value\\\"]\\n\\n\\ndef _lookups() -> tuple[dict[str, set[str]], dict[str, str]]:\\n    return {\\\"ChatInput\\\": {_hash(CURRENT_CHAT_INPUT)}}, {\\\"ChatInput\\\": CURRENT_CHAT_INPUT}\\n\\n\\ndef _ambiguous_lookups() -> tuple[dict[str, set[str]], dict[str, str]]:\\n    \\\"\\\"\\\"A registry where two components claim the type ``ChatInput``.\\n\\n    ``collect_component_hash_lookups`` keeps both hashes; ``collect_component_code_lookups`` is\\n    first-wins, so its single code value may belong to either component.\\n    \\\"\\\"\\\"\\n    return (\\n        {\\\"ChatInput\\\": {_hash(CURRENT_CHAT_INPUT), _hash(OVERRIDE_CHAT_INPUT)}},\\n        {\\\"ChatInput\\\": CURRENT_CHAT_INPUT},\\n    )\\n\\n\\ndef _mismatched_lookups() -> tuple[dict[str, set[str]], dict[str, str]]:\\n    \\\"\\\"\\\"Build the exact first-alias mismatch reported on the PR review thread.\\\"\\\"\\\"\\n    all_types = {\\n        \\\"first\\\": {\\n            \\\"ChatInput\\\": {\\n                # This first alias contributes source but no hash metadata.\\n                \\\"template\\\": {\\\"code\\\": {\\\"value\\\": OVERRIDE_CHAT_INPUT}},\\n            }\\n        },\\n        \\\"second\\\": {\\n            \\\"ChatInput\\\": {\\n                \\\"metadata\\\": {\\\"code_hash\\\": _hash(CURRENT_CHAT_INPUT)},\\n                \\\"template\\\": {\\\"code\\\": {\\\"value\\\": CURRENT_CHAT_INPUT}},\\n            }\\n        },\\n    }\\n    type_to_hash, _ = collect_component_hash_lookups(all_types)\\n    return type_to_hash, collect_component_code_lookups(all_types)\\n\\n\\ndef _subst_args(lookups=_lookups) -> tuple[dict[str, str], SubstitutableComponentTypes]:\\n    \\\"\\\"\\\"Build ``_substitute_outdated_node_code``'s ``(type_to_code, substitutable_types)`` pair.\\\"\\\"\\\"\\n    type_to_hash, type_to_code = lookups()\\n    return type_to_code, SubstitutableComponentTypes(type_to_hash, type_to_code)\\n\\n\\ndef _settings(*, allow_custom=False, substitute=True) -> SimpleNamespace:\\n    return SimpleNamespace(\\n        settings=SimpleNamespace(\\n            allow_custom_components=allow_custom,\\n            substitute_outdated_component_code=substitute,\\n        )\\n    )\\n\\n\\ndef _enable(monkeypatch, *, allow_custom=False, substitute=True, lookups=_lookups) -> None:\\n    \\\"\\\"\\\"Point the substitution at a synthetic single-component registry.\\\"\\\"\\\"\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_settings_service\\\",\\n        lambda: _settings(allow_custom=allow_custom, substitute=substitute),\\n    )\\n    type_to_hash, type_to_code = lookups()\\n    monkeypatch.setattr(fv, \\\"get_component_hash_lookups_for_validation\\\", lambda: type_to_hash)\\n    monkeypatch.setattr(fv, \\\"get_component_code_lookups_for_validation\\\", lambda: type_to_code)\\n\\n\\n# --- _substitute_outdated_node_code ------------------------------------------------\\n\\n\\ndef test_drifted_builtin_is_rebuilt_with_server_code():\\n    nodes = [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT, display_name=\\\"Chat Input\\\")]\\n\\n    swapped = fv._substitute_outdated_node_code(nodes, *_subst_args())\\n\\n    assert swapped == [\\\"Chat Input (a)\\\"]\\n    assert _code_of(nodes[0]) == CURRENT_CHAT_INPUT\\n\\n\\ndef test_up_to_date_builtin_is_left_alone():\\n    nodes = [_node(\\\"a\\\", \\\"ChatInput\\\", CURRENT_CHAT_INPUT)]\\n\\n    assert fv._substitute_outdated_node_code(nodes, *_subst_args()) == []\\n    assert _code_of(nodes[0]) == CURRENT_CHAT_INPUT\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"component_type\\\",\\n    [\\\"TotallyCustom\\\", \\\"\\\", None, {\\\"not\\\": \\\"a string\\\"}],\\n    ids=[\\\"unknown\\\", \\\"empty\\\", \\\"missing\\\", \\\"malformed\\\"],\\n)\\ndef test_unrecognized_type_is_never_substituted(component_type):\\n    \\\"\\\"\\\"The substitution must not create a path for arbitrary or relabelled code to run.\\n\\n    Leaving these untouched is what keeps ``check_flow_and_raise`` blocking them.\\n    \\\"\\\"\\\"\\n    nodes = [_node(\\\"x\\\", component_type, \\\"import os; os.system('id')\\\", display_name=\\\"Sneaky\\\")]\\n\\n    assert fv._substitute_outdated_node_code(nodes, *_subst_args()) == []\\n    assert _code_of(nodes[0]) == \\\"import os; os.system('id')\\\"\\n\\n\\ndef test_relabelled_custom_code_is_replaced_not_executed():\\n    \\\"\\\"\\\"Arbitrary code wearing a known type gets this server's component, same as the public path.\\\"\\\"\\\"\\n    nodes = [_node(\\\"a\\\", \\\"ChatInput\\\", \\\"import os; os.system('pwned')\\\")]\\n\\n    assert fv._substitute_outdated_node_code(nodes, *_subst_args()) == [\\\"ChatInput (a)\\\"]\\n    assert _code_of(nodes[0]) == CURRENT_CHAT_INPUT\\n\\n\\ndef test_recurses_into_inlined_subflows():\\n    inner = _node(\\\"inner\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT, display_name=\\\"Inner\\\")\\n    wrapper = _node(\\\"wrap\\\", \\\"GroupNode\\\", None)\\n    wrapper[\\\"data\\\"][\\\"node\\\"][\\\"flow\\\"] = {\\\"data\\\": {\\\"nodes\\\": [inner]}}\\n\\n    swapped = fv._substitute_outdated_node_code([wrapper], *_subst_args())\\n\\n    assert swapped == [\\\"Inner (inner)\\\"]\\n    assert _code_of(inner) == CURRENT_CHAT_INPUT\\n\\n\\ndef test_codeless_and_malformed_nodes_are_skipped():\\n    nodes = [\\\"not-a-node\\\", {\\\"data\\\": \\\"not-a-dict\\\"}, {\\\"data\\\": {\\\"node\\\": \\\"not-a-dict\\\"}}, _node(\\\"n\\\", \\\"ChatInput\\\", None)]\\n\\n    assert fv._substitute_outdated_node_code(nodes, *_subst_args()) == []\\n\\n\\n# --- ambiguous types: two components claiming one name -----------------------------\\n\\n\\ndef test_ambiguous_type_is_never_substituted():\\n    \\\"\\\"\\\"Drift on a contested type must not be resolved into the *wrong* component.\\n\\n    When a built-in and a ``components_path`` component share a name the hash lookup keeps both\\n    hashes while the code lookup keeps only whichever the registry yielded first. Stored code\\n    matching neither hash is then indistinguishable from \\\"this node is the other component\\\", so\\n    the node is left for ``check_flow_and_raise`` to block, as it was before this pass existed.\\n    \\\"\\\"\\\"\\n    nodes = [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT, display_name=\\\"Chat Input\\\")]\\n\\n    assert fv._substitute_outdated_node_code(nodes, *_subst_args(_ambiguous_lookups)) == []\\n    assert _code_of(nodes[0]) == STORED_CHAT_INPUT\\n\\n\\n@pytest.mark.parametrize(\\\"code\\\", [CURRENT_CHAT_INPUT, OVERRIDE_CHAT_INPUT], ids=[\\\"builtin\\\", \\\"override\\\"])\\ndef test_ambiguous_type_still_builds_when_its_code_matches_either_component(code):\\n    \\\"\\\"\\\"Only *drift* is refused on a contested type; both current versions still build.\\\"\\\"\\\"\\n    type_to_hash, _ = _ambiguous_lookups()\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", code)]}\\n\\n    check_flow_and_raise(\\n        flow,\\n        allow_custom_components=False,\\n        type_to_current_hash=type_to_hash,\\n        substitutable_types=_subst_args(_ambiguous_lookups)[1],\\n    )\\n\\n\\ndef test_check_flow_and_raise_still_blocks_drift_on_an_ambiguous_type():\\n    \\\"\\\"\\\"The pre-check must agree with the substitution: not substituted means not exempted.\\n\\n    Otherwise the node would clear validation carrying code this server cannot resolve, and\\n    ``resolve_trusted_code_for_build`` would fail it later with a far less actionable message.\\n    \\\"\\\"\\\"\\n    type_to_hash, _ = _ambiguous_lookups()\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)]}\\n\\n    with pytest.raises(CustomComponentValidationError, match=\\\"outdated components must be updated\\\"):\\n        check_flow_and_raise(\\n            flow,\\n            allow_custom_components=False,\\n            type_to_current_hash=type_to_hash,\\n            substitutable_types=_subst_args(_ambiguous_lookups)[1],\\n        )\\n\\n\\ndef test_in_place_substitution_skips_ambiguous_type(monkeypatch):\\n    _enable(monkeypatch, lookups=_ambiguous_lookups)\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    assert substitute_outdated_component_code_in_place(flow) == []\\n    assert _code_of(flow[\\\"nodes\\\"][0]) == STORED_CHAT_INPUT\\n\\n\\ndef test_mismatched_trusted_code_is_neither_substituted_nor_exempted():\\n    \\\"\\\"\\\"A single hash is not enough when the type lookup points at different source.\\\"\\\"\\\"\\n    type_to_hash, type_to_code = _mismatched_lookups()\\n    substitutable_types = SubstitutableComponentTypes(type_to_hash, type_to_code)\\n    nodes = [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT, display_name=\\\"Chat Input\\\")]\\n\\n    assert \\\"ChatInput\\\" not in substitutable_types\\n    assert fv._substitute_outdated_node_code(nodes, type_to_code, substitutable_types) == []\\n    assert _code_of(nodes[0]) == STORED_CHAT_INPUT\\n\\n    with pytest.raises(CustomComponentValidationError, match=\\\"outdated components must be updated\\\"):\\n        check_flow_and_raise(\\n            {\\\"nodes\\\": nodes},\\n            allow_custom_components=False,\\n            type_to_current_hash=type_to_hash,\\n            substitutable_types=substitutable_types,\\n        )\\n\\n\\n# --- substitute_outdated_component_code_in_place (settings-aware) -------------------\\n\\n\\ndef test_in_place_substitution_swaps_when_enabled(monkeypatch):\\n    _enable(monkeypatch)\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    assert substitute_outdated_component_code_in_place(flow) == [\\\"ChatInput (a)\\\"]\\n    assert _code_of(flow[\\\"nodes\\\"][0]) == CURRENT_CHAT_INPUT\\n\\n\\ndef test_no_substitution_when_custom_components_are_allowed(monkeypatch):\\n    \\\"\\\"\\\"Permissive mode runs the node's own code, so nothing may be rewritten.\\\"\\\"\\\"\\n    _enable(monkeypatch, allow_custom=True)\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    assert substitute_outdated_component_code_in_place(flow) == []\\n    assert _code_of(flow[\\\"nodes\\\"][0]) == STORED_CHAT_INPUT\\n\\n\\ndef test_no_substitution_when_operator_opts_out(monkeypatch):\\n    _enable(monkeypatch, substitute=False)\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    assert substitute_outdated_component_code_in_place(flow) == []\\n    assert _code_of(flow[\\\"nodes\\\"][0]) == STORED_CHAT_INPUT\\n\\n\\ndef test_no_substitution_without_settings_service(monkeypatch):\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: None)\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    assert substitute_outdated_component_code_in_place(flow) == []\\n\\n\\ndef test_no_substitution_while_registry_is_still_loading(monkeypatch):\\n    \\\"\\\"\\\"Fail closed: with no trusted code available, the strict hash check must still apply.\\\"\\\"\\\"\\n    _enable(monkeypatch, lookups=lambda: (None, None))\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    assert substitute_outdated_component_code_in_place(flow) == []\\n    assert _code_of(flow[\\\"nodes\\\"][0]) == STORED_CHAT_INPUT\\n\\n\\ndef test_substitution_lookups_are_captured_under_one_cache_lock(monkeypatch):\\n    \\\"\\\"\\\"A hot reload cannot pair the hash index from one registry with code from another.\\\"\\\"\\\"\\n    from lfx.interface import components as component_module\\n\\n    class TrackingLock:\\n        def __init__(self) -> None:\\n            self.active = False\\n            self.entries = 0\\n\\n        def __enter__(self):\\n            assert not self.active\\n            self.active = True\\n            self.entries += 1\\n\\n        def __exit__(self, *_args) -> None:\\n            self.active = False\\n\\n    lock = TrackingLock()\\n    monkeypatch.setattr(component_module, \\\"component_cache\\\", SimpleNamespace(state_lock=lock))\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings())\\n    type_to_hash, type_to_code = _lookups()\\n\\n    def get_hashes():\\n        assert lock.active\\n        return type_to_hash\\n\\n    def get_code():\\n        assert lock.active\\n        return type_to_code\\n\\n    monkeypatch.setattr(fv, \\\"get_component_hash_lookups_for_validation\\\", get_hashes)\\n    monkeypatch.setattr(fv, \\\"get_component_code_lookups_for_validation\\\", get_code)\\n\\n    lookups = fv.get_outdated_code_substitution_lookups()\\n\\n    assert lookups is not None\\n    assert lock.entries == 1\\n\\n\\n@pytest.mark.parametrize(\\\"empty\\\", [None, {}, {\\\"nodes\\\": []}, {\\\"nodes\\\": \\\"not-a-list\\\"}])\\ndef test_in_place_substitution_noop_on_empty(monkeypatch, empty):\\n    _enable(monkeypatch)\\n    assert substitute_outdated_component_code_in_place(empty) == []\\n\\n\\ndef test_substitution_is_logged(monkeypatch):\\n    \\\"\\\"\\\"Swapping is safe but not neutral (see #14236), so it must never happen silently.\\\"\\\"\\\"\\n    _enable(monkeypatch)\\n    warnings: list[str] = []\\n    monkeypatch.setattr(fv, \\\"logger\\\", SimpleNamespace(warning=warnings.append))\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT, display_name=\\\"Chat Input\\\")], \\\"edges\\\": []}\\n\\n    substitute_outdated_component_code_in_place(flow)\\n\\n    assert len(warnings) == 1\\n    assert \\\"Chat Input (a)\\\" in warnings[0]\\n\\n\\ndef test_no_log_when_nothing_drifted(monkeypatch):\\n    _enable(monkeypatch)\\n    warnings: list[str] = []\\n    monkeypatch.setattr(fv, \\\"logger\\\", SimpleNamespace(warning=warnings.append))\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", CURRENT_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    substitute_outdated_component_code_in_place(flow)\\n\\n    assert warnings == []\\n\\n\\n# --- check_flow_and_raise / validate_flow_for_current_settings ----------------------\\n\\n\\ndef test_check_flow_and_raise_exempts_substitutable_drift():\\n    type_to_hash, _ = _lookups()\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)]}\\n\\n    check_flow_and_raise(\\n        flow,\\n        allow_custom_components=False,\\n        type_to_current_hash=type_to_hash,\\n        substitutable_types=_subst_args()[1],\\n    )\\n\\n\\ndef test_check_flow_and_raise_still_blocks_unknown_type_when_substituting():\\n    type_to_hash, _ = _lookups()\\n    flow = {\\\"nodes\\\": [_node(\\\"x\\\", \\\"TotallyCustom\\\", \\\"import os\\\", display_name=\\\"Custom\\\")]}\\n\\n    with pytest.raises(CustomComponentValidationError, match=\\\"custom components are not allowed\\\"):\\n        check_flow_and_raise(\\n            flow,\\n            allow_custom_components=False,\\n            type_to_current_hash=type_to_hash,\\n            substitutable_types=_subst_args()[1],\\n        )\\n\\n\\ndef test_check_flow_and_raise_keeps_blocking_drift_without_substitution():\\n    type_to_hash, _ = _lookups()\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)]}\\n\\n    with pytest.raises(CustomComponentValidationError, match=\\\"outdated components must be updated\\\"):\\n        check_flow_and_raise(flow, allow_custom_components=False, type_to_current_hash=type_to_hash)\\n\\n\\ndef test_validator_accepts_drifted_flow_and_leaves_it_untouched(monkeypatch):\\n    \\\"\\\"\\\"The pre-check stops refusing the build, but must not rewrite the stored flow.\\n\\n    The substitution itself happens in ``Graph.from_payload`` on the payload that is built.\\n    Leaving the caller's data alone is what keeps the editor flagging the node as outdated.\\n    \\\"\\\"\\\"\\n    _enable(monkeypatch)\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(snapshot=CatalogPolicySnapshot()),\\n    )\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    validate_flow_for_current_settings(flow)\\n\\n    assert _code_of(flow[\\\"nodes\\\"][0]) == STORED_CHAT_INPUT\\n\\n\\ndef test_validator_uses_hashes_from_the_same_snapshot_as_substitution(monkeypatch):\\n    \\\"\\\"\\\"Validation must not pair an earlier hash index with a later substitution index.\\\"\\\"\\\"\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings())\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(snapshot=CatalogPolicySnapshot()),\\n    )\\n    type_to_hash, type_to_code = _lookups()\\n    lookups = type_to_code, SubstitutableComponentTypes(type_to_hash, type_to_code)\\n    monkeypatch.setattr(fv, \\\"get_outdated_code_substitution_lookups\\\", lambda: lookups)\\n    monkeypatch.setattr(\\n        fv,\\n        \\\"get_component_hash_lookups_for_validation\\\",\\n        lambda: pytest.fail(\\\"standalone hash lookup would create a mixed registry snapshot\\\"),\\n    )\\n\\n    validate_flow_for_current_settings({\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)]})\\n\\n\\ndef test_from_payload_substitutes_before_validating(monkeypatch):\\n    \\\"\\\"\\\"Graph.from_payload owns the payload it builds, so the real swap happens there \u2014 first.\\\"\\\"\\\"\\n    from lfx.graph.graph.base import Graph\\n\\n    calls: list[tuple[str, dict, dict]] = []\\n    monkeypatch.setattr(\\n        fv,\\n        \\\"substitute_outdated_component_code_in_place\\\",\\n        lambda payload, **kwargs: (calls.append((\\\"substitute\\\", payload, kwargs)), [])[1],\\n    )\\n    monkeypatch.setattr(\\n        fv,\\n        \\\"validate_flow_for_current_settings\\\",\\n        lambda payload, **kwargs: calls.append((\\\"validate\\\", payload, kwargs)),\\n    )\\n\\n    payload = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n    Graph.from_payload(payload)\\n\\n    assert [name for name, *_ in calls] == [\\\"substitute\\\", \\\"validate\\\"]\\n    assert calls[0][1] is payload\\n    assert calls[0][2] == {\\\"validate_public_execution\\\": False}\\n\\n\\ndef test_validator_still_refuses_drifted_flow_when_opted_out(monkeypatch):\\n    _enable(monkeypatch, substitute=False)\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(snapshot=CatalogPolicySnapshot()),\\n    )\\n    flow = {\\\"nodes\\\": [_node(\\\"a\\\", \\\"ChatInput\\\", STORED_CHAT_INPUT)], \\\"edges\\\": []}\\n\\n    with pytest.raises(CustomComponentValidationError, match=\\\"outdated components must be updated\\\"):\\n        validate_flow_for_current_settings(flow)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_python_repl_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"95ba946a6db24afece1d4d838255a63447877a2a8b48115aa83474d2d309eb63\",\"content\":\"\\\"\\\"\\\"Unit tests for the Python REPL hardening helpers.\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.utils.python_repl_security import safe_builtins, validate_code_safety\\n\\n\\nclass TestSafeBuiltins:\\n    def test_excludes_dangerous_builtins(self):\\n        \\\"\\\"\\\"Code-execution, import, filesystem and introspection builtins are removed.\\\"\\\"\\\"\\n        builtins_map = safe_builtins()\\n        for name in (\\n            \\\"__import__\\\",\\n            \\\"eval\\\",\\n            \\\"exec\\\",\\n            \\\"compile\\\",\\n            \\\"open\\\",\\n            \\\"input\\\",\\n            \\\"globals\\\",\\n            \\\"locals\\\",\\n            \\\"vars\\\",\\n            \\\"getattr\\\",\\n            \\\"setattr\\\",\\n            \\\"delattr\\\",\\n            \\\"breakpoint\\\",\\n            \\\"memoryview\\\",\\n            \\\"exit\\\",\\n            \\\"quit\\\",\\n            \\\"help\\\",\\n        ):\\n            assert name not in builtins_map, f\\\"{name} must not be exposed\\\"\\n\\n    def test_includes_common_safe_builtins(self):\\n        \\\"\\\"\\\"Common, safe builtins remain available so normal code keeps working.\\\"\\\"\\\"\\n        builtins_map = safe_builtins()\\n        for name in (\\n            \\\"print\\\",\\n            \\\"len\\\",\\n            \\\"range\\\",\\n            \\\"int\\\",\\n            \\\"float\\\",\\n            \\\"str\\\",\\n            \\\"list\\\",\\n            \\\"dict\\\",\\n            \\\"tuple\\\",\\n            \\\"set\\\",\\n            \\\"sum\\\",\\n            \\\"min\\\",\\n            \\\"max\\\",\\n            \\\"sorted\\\",\\n            \\\"enumerate\\\",\\n            \\\"zip\\\",\\n            \\\"isinstance\\\",\\n            \\\"type\\\",\\n            \\\"Exception\\\",\\n            \\\"ValueError\\\",\\n        ):\\n            assert name in builtins_map, f\\\"{name} should be available\\\"\\n\\n    def test_returns_fresh_copy(self):\\n        \\\"\\\"\\\"Each call returns an independent dict so callers cannot mutate shared state.\\\"\\\"\\\"\\n        first = safe_builtins()\\n        first[\\\"injected\\\"] = object()\\n        assert \\\"injected\\\" not in safe_builtins()\\n\\n\\nclass TestValidateCodeSafety:\\n    @pytest.mark.parametrize(\\n        \\\"code\\\",\\n        [\\n            \\\"import os\\\",\\n            \\\"import subprocess\\\",\\n            \\\"from os import system\\\",\\n            \\\"().__class__\\\",\\n            \\\"[].__class__.__bases__[0].__subclasses__()\\\",\\n            \\\"(lambda: 0).__globals__\\\",\\n            \\\"().__class__.__mro__\\\",\\n            \\\"(x for x in []).gi_frame\\\",\\n            \\\"object.__subclasses__()\\\",\\n            'f\\\"{().__class__}\\\"',\\n            \\\"int.mro()\\\",\\n            '\\\"{0.__globals__}\\\".format(f)',\\n            '\\\"{0[__builtins__]}\\\".format(f)',\\n            '\\\"{0.__class__}\\\".format(obj)',\\n            \\\"'{0}'.format(1)\\\",\\n            \\\"'{name}'.format_map({'name': 'x'})\\\",\\n            \\\"template = '{0.' + 'value' + '}'\\\\ntemplate.format(obj)\\\",\\n            # Sibling formatter sinks that carry the dunder chain in a *string* argument\\n            # (invisible to the AST attribute check) \u2014 blocked via the method name.\\n            'string.Formatter().vformat(\\\"{0.__globals__[os].environ[SECRET]}\\\", (f,), {})',\\n            'string.Formatter().get_field(\\\"0.__loader__.find_spec.__globals__[sys]\\\", (f,), {})',\\n            \\\"string.Formatter().get_value(0, (f,), {})\\\",\\n            'operator.attrgetter(\\\"__globals__\\\")(f)',\\n            # ``operator.methodcaller`` defers a method name to call time, so a\\n            # runtime-assembled template (no literal \\\"{...__\\\" for the regex to catch)\\n            # reaches str.format/format_map invisibly. Blocked via the factory name.\\n            'operator.methodcaller(\\\"format\\\", f)(tmpl)',\\n            'operator.methodcaller(\\\"format_map\\\", d)(tmpl)',\\n            'operator.methodcaller(\\\"__getattribute__\\\", \\\"__globals__\\\")(f)',\\n            # A literal dunder-bearing template reaches a non-blocked formatter via a var;\\n            # the literal-field scan rejects the template regardless of the consumer.\\n            't = \\\"{0.__globals__}\\\"\\\\nstring.Formatter().vformat(t, (f,), {})',\\n        ],\\n    )\\n    def test_blocks_escape_and_import(self, code):\\n        \\\"\\\"\\\"Inline imports, escape gadgets, and formatter method access are rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"not allowed\\\"):\\n            validate_code_safety(code)\\n\\n    @pytest.mark.parametrize(\\n        \\\"code\\\",\\n        [\\n            \\\"print('Hello, World!')\\\",\\n            \\\"print(len([1, 2, 3]))\\\",\\n            \\\"x = 1\\\\ny = x + 2\\\\nprint(y)\\\",\\n            \\\"math.sqrt(16)\\\",\\n            \\\"result = [i * 2 for i in range(5)]\\\\nprint(sum(result))\\\",\\n            \\\"data = {'a': 1, 'b': 2}\\\\nprint(sorted(data.items()))\\\",\\n            \\\"name = 'x'\\\\nprint(f'{name}')\\\",\\n            \\\"print(format(3.14159, '.2f'))\\\",\\n        ],\\n    )\\n    def test_allows_safe_code(self, code):\\n        \\\"\\\"\\\"Ordinary code (no imports, no dunder/frame access) is allowed.\\\"\\\"\\\"\\n        validate_code_safety(code)  # should not raise\\n\\n    def test_syntax_error_propagates(self):\\n        \\\"\\\"\\\"Unparseable code surfaces a SyntaxError to the caller.\\\"\\\"\\\"\\n        with pytest.raises(SyntaxError):\\n            validate_code_safety(\\\"print('unterminated\\\")\\n\\n\\nclass TestFormatterSinkBypassesAreBlocked:\\n    \\\"\\\"\\\"Env-canary regression for the sibling-formatter sandbox bypass.\\n\\n    ``str.format``/``format_map`` are not the only formatter sinks: the same\\n    ``__globals__`` traversal lives in a *string* argument (invisible to the AST\\n    attribute check) when fed through ``string.Formatter`` traversal primitives,\\n    ``operator.attrgetter`` or ``operator.methodcaller``. Each test first proves the\\n    gadget *does* leak an env var canary when run unguarded, then asserts\\n    ``validate_code_safety`` rejects the exact input before it could execute.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _func_with_os():\\n        \\\"\\\"\\\"A function whose ``__globals__`` deterministically contains ``os``.\\n\\n        The gadget escapes via ``func.__globals__[os]``, so the precondition only leaks\\n        when ``os`` is bound in the function's module globals. Building the function with\\n        an explicit globals dict makes the leak reproducible regardless of which modules\\n        this test file happens to import.\\n        \\\"\\\"\\\"\\n        import os\\n\\n        namespace = {\\\"os\\\": os}\\n        exec(\\\"def _f():\\\\n    return 0\\\", namespace)  # noqa: S102 - test-only controlled exec\\n        return namespace[\\\"_f\\\"]\\n\\n    def test_formatter_vformat_bypass(self, monkeypatch):\\n        \\\"\\\"\\\"``string.Formatter().vformat`` reaches os.environ; the call is blocked.\\\"\\\"\\\"\\n        import string\\n\\n        monkeypatch.setenv(\\\"LFX_REPL_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        leaked = string.Formatter().vformat(\\\"{0.__globals__[os].environ[LFX_REPL_CANARY]}\\\", (self._func_with_os(),), {})\\n        assert leaked == \\\"SHOULD_NOT_LEAK\\\"  # gadget is real when unguarded\\n\\n        code = 'string.Formatter().vformat(\\\"{0.__globals__[os].environ[LFX_REPL_CANARY]}\\\", (f,), {})'\\n        with pytest.raises(ValueError, match=\\\"not allowed\\\"):\\n            validate_code_safety(code)\\n\\n    def test_formatter_get_field_bypass(self, monkeypatch):\\n        \\\"\\\"\\\"``string.Formatter().get_field`` traverses a dotted path; the call is blocked.\\\"\\\"\\\"\\n        import string\\n\\n        monkeypatch.setenv(\\\"LFX_REPL_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        obj, _ = string.Formatter().get_field(\\\"0.__globals__[os].environ[LFX_REPL_CANARY]\\\", (self._func_with_os(),), {})\\n        assert obj == \\\"SHOULD_NOT_LEAK\\\"  # gadget is real when unguarded\\n\\n        code = 'string.Formatter().get_field(\\\"0.__globals__[os].environ[LFX_REPL_CANARY]\\\", (f,), {})'\\n        with pytest.raises(ValueError, match=\\\"not allowed\\\"):\\n            validate_code_safety(code)\\n\\n    def test_operator_attrgetter_bypass(self, monkeypatch):\\n        \\\"\\\"\\\"``operator.attrgetter('__globals__')`` reaches os.environ; the call is blocked.\\\"\\\"\\\"\\n        import operator\\n\\n        monkeypatch.setenv(\\\"LFX_REPL_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        leaked = operator.attrgetter(\\\"__globals__\\\")(self._func_with_os())[\\\"os\\\"].environ[\\\"LFX_REPL_CANARY\\\"]\\n        assert leaked == \\\"SHOULD_NOT_LEAK\\\"  # gadget is real when unguarded\\n\\n        code = 'operator.attrgetter(\\\"__globals__\\\")(f)'\\n        with pytest.raises(ValueError, match=\\\"not allowed\\\"):\\n            validate_code_safety(code)\\n\\n    def test_operator_methodcaller_format_bypass(self, monkeypatch):\\n        \\\"\\\"\\\"``operator.methodcaller('format', f)`` invokes str.format on a runtime template.\\n\\n        Unlike a literal ``\\\"{0.__globals__}\\\".format(f)``, the template is assembled at\\n        runtime so the ``_FORMAT_FIELD_DUNDER_RE`` literal scan never sees ``{...__``,\\n        and ``methodcaller`` keeps the method name ``\\\"format\\\"`` in a *string* argument so\\n        there is no ``ast.Attribute`` named ``format`` either. Blocking the ``methodcaller``\\n        factory name is what rejects it.\\n        \\\"\\\"\\\"\\n        import operator\\n\\n        monkeypatch.setenv(\\\"LFX_REPL_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        # Template built from fragments at runtime \u2014 invisible to the literal-field scan.\\n        tmpl = \\\"{0.\\\" + \\\"__globals__\\\" + \\\"[os].environ[LFX_REPL_CANARY]}\\\"\\n        leaked = operator.methodcaller(\\\"format\\\", self._func_with_os())(tmpl)\\n        assert leaked == \\\"SHOULD_NOT_LEAK\\\"  # gadget is real when unguarded\\n\\n        code = 'operator.methodcaller(\\\"format\\\", f)(tmpl)'\\n        with pytest.raises(ValueError, match=\\\"not allowed\\\"):\\n            validate_code_safety(code)\\n\\n    def test_operator_methodcaller_getattribute_bypass(self, monkeypatch):\\n        \\\"\\\"\\\"``methodcaller('__getattribute__', '__globals__')`` reaches an attr by string name.\\n\\n        ``methodcaller`` can invoke *any* method \u2014 including ``__getattribute__`` \u2014 with the\\n        attribute name supplied as a runtime string, bypassing the dunder-attribute AST\\n        check. Blocked via the ``methodcaller`` factory name.\\n        \\\"\\\"\\\"\\n        import operator\\n\\n        monkeypatch.setenv(\\\"LFX_REPL_CANARY\\\", \\\"SHOULD_NOT_LEAK\\\")\\n        leaked = operator.methodcaller(\\\"__getattribute__\\\", \\\"__globals__\\\")(self._func_with_os())[\\\"os\\\"].environ[\\n            \\\"LFX_REPL_CANARY\\\"\\n        ]\\n        assert leaked == \\\"SHOULD_NOT_LEAK\\\"  # gadget is real when unguarded\\n\\n        code = 'operator.methodcaller(\\\"__getattribute__\\\", \\\"__globals__\\\")(f)'\\n        with pytest.raises(ValueError, match=\\\"not allowed\\\"):\\n            validate_code_safety(code)\\n\\n\\nclass TestEnsureCodeExecutionEnabled:\\n    \\\"\\\"\\\"GHSA-8qpj-27x8-pwpq: code execution honors allow_custom_components.\\\"\\\"\\\"\\n\\n    def test_blocks_when_custom_components_disabled(self, monkeypatch):\\n        from types import SimpleNamespace\\n\\n        from lfx.utils.python_repl_security import CodeExecutionDisabledError, ensure_code_execution_enabled\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=False)),\\n        )\\n        with pytest.raises(CodeExecutionDisabledError):\\n            ensure_code_execution_enabled()\\n\\n    def test_allows_when_custom_components_enabled(self, monkeypatch):\\n        from types import SimpleNamespace\\n\\n        from lfx.utils.python_repl_security import ensure_code_execution_enabled\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: SimpleNamespace(\\n                settings=SimpleNamespace(\\n                    allow_custom_components=True,\\n                    block_code_interpreter_components=False,\\n                )\\n            ),\\n        )\\n        ensure_code_execution_enabled()  # must not raise\\n\\n    def test_blocks_when_code_interpreter_components_disabled(self, monkeypatch):\\n        from types import SimpleNamespace\\n\\n        from lfx.utils.python_repl_security import CodeExecutionDisabledError, ensure_code_execution_enabled\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: SimpleNamespace(\\n                settings=SimpleNamespace(\\n                    allow_custom_components=True,\\n                    block_code_interpreter_components=True,\\n                )\\n            ),\\n        )\\n        with pytest.raises(CodeExecutionDisabledError, match=\\\"block_code_interpreter_components\\\"):\\n            ensure_code_execution_enabled()\\n\\n    def test_allows_when_services_layer_absent(self, monkeypatch):\\n        \\\"\\\"\\\"An absent services layer (ImportError) is a local/trusted context -> allowed.\\\"\\\"\\\"\\n        from lfx.utils.python_repl_security import ensure_code_execution_enabled\\n\\n        # Deleting the imported name makes ``from lfx.services.deps import\\n        # get_settings_service`` raise ImportError, simulating an absent services layer.\\n        monkeypatch.delattr(\\\"lfx.services.deps.get_settings_service\\\")\\n        ensure_code_execution_enabled()  # must not raise\\n\\n    def test_blocks_when_settings_service_is_none(self, monkeypatch):\\n        \\\"\\\"\\\"A None settings service (registered-but-failed stack) fails closed, not open.\\\"\\\"\\\"\\n        from lfx.utils.python_repl_security import CodeExecutionDisabledError, ensure_code_execution_enabled\\n\\n        # get_service swallows init errors into None; the gate must refuse, not bypass.\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: None)\\n        with pytest.raises(CodeExecutionDisabledError):\\n            ensure_code_execution_enabled()\\n\\n    def test_non_import_error_propagates(self, monkeypatch):\\n        \\\"\\\"\\\"A non-ImportError from get_settings_service() propagates, never failing open.\\\"\\\"\\\"\\n        from lfx.utils.python_repl_security import ensure_code_execution_enabled\\n\\n        # Only ImportError means \\\"no services layer\\\"; anything else must surface.\\n        def _boom():\\n            error = \\\"settings stack exploded\\\"\\n            raise RuntimeError(error)\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", _boom)\\n        with pytest.raises(RuntimeError, match=\\\"settings stack exploded\\\"):\\n            ensure_code_execution_enabled()\\n\\n    def test_import_error_from_settings_service_propagates(self, monkeypatch):\\n        \\\"\\\"\\\"An ImportError inside the registered settings stack must not fail open.\\\"\\\"\\\"\\n        from lfx.utils.python_repl_security import ensure_code_execution_enabled\\n\\n        def _boom():\\n            error = \\\"settings dependency failed to import\\\"\\n            raise ImportError(error)\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", _boom)\\n        with pytest.raises(ImportError, match=\\\"settings dependency failed to import\\\"):\\n            ensure_code_execution_enabled()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_resolve_trusted_code_for_build.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff4444593d125f1cd44d88bb24f722f4aaf921b6a7994a7398bf4f0f019f9dcb\",\"content\":\"\\\"\\\"\\\"Tests for resolve_trusted_code_for_build (LE-1680 / CWE-345).\\n\\nWhen LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false, the authenticated flow-build path validates each\\nnode's code only by a 48-bit truncated hash, then execs the node's stored bytes. A second-preimage\\ncollision against a built-in's template hash therefore yields RCE. resolve_trusted_code_for_build\\ncloses this by substituting the server's trusted copy (keyed by the code's hash) before exec, and\\nfailing closed when no trusted copy is known \u2014 while leaving permissive mode (the default) untouched.\\n\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom lfx.interface.initialize import loading\\nfrom lfx.services.authorization import PUBLIC_ANONYMOUS_ACTOR_ID\\nfrom lfx.utils import flow_validation\\nfrom lfx.utils.flow_validation import (\\n    CustomComponentValidationError,\\n    PublicFlowValidationError,\\n    resolve_trusted_code_for_build,\\n)\\n\\n\\ndef _set_allow_custom_components(monkeypatch, *, allow: bool) -> None:\\n    fake = SimpleNamespace(settings=SimpleNamespace(allow_custom_components=allow))\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: fake)\\n\\n\\ndef test_permissive_mode_returns_code_unchanged(monkeypatch):\\n    \\\"\\\"\\\"Default mode (allow_custom_components=True): the node's own code runs, untouched.\\\"\\\"\\\"\\n    _set_allow_custom_components(monkeypatch, allow=True)\\n\\n    def _must_not_be_called(_code):\\n        pytest.fail(\\\"trusted lookup must not run in permissive mode\\\")\\n\\n    monkeypatch.setattr(flow_validation, \\\"get_trusted_code_for_validation\\\", _must_not_be_called)\\n    assert resolve_trusted_code_for_build(\\\"user-authored code\\\") == \\\"user-authored code\\\"\\n\\n\\ndef test_restricted_mode_substitutes_trusted_copy(monkeypatch):\\n    \\\"\\\"\\\"Restricted mode + a hash match: the server's trusted source runs, not the node's bytes.\\\"\\\"\\\"\\n    _set_allow_custom_components(monkeypatch, allow=False)\\n    monkeypatch.setattr(flow_validation, \\\"get_trusted_code_for_validation\\\", lambda _code: \\\"SERVER_TRUSTED_SRC\\\")\\n    # Even a forged blob that collides with a known hash resolves to the server copy.\\n    assert resolve_trusted_code_for_build(\\\"forged colliding blob\\\") == \\\"SERVER_TRUSTED_SRC\\\"\\n\\n\\ndef test_public_restricted_mode_checks_the_final_trusted_copy(monkeypatch):\\n    \\\"\\\"\\\"The exact source selected immediately before eval is subject to public policy.\\\"\\\"\\\"\\n    _set_allow_custom_components(monkeypatch, allow=False)\\n    trusted_repl = \\\"class PythonREPLComponent(Component):\\\\n    pass\\\\n\\\"\\n    trusted_hash = flow_validation._compute_code_hash(trusted_repl)\\n    monkeypatch.setattr(\\n        flow_validation,\\n        \\\"get_trusted_code_and_hashes_for_validation\\\",\\n        lambda _code: (trusted_repl, {\\\"PythonREPLComponent\\\": {trusted_hash}}),\\n    )\\n\\n    with pytest.raises(PublicFlowValidationError, match=\\\"code-execution\\\"):\\n        resolve_trusted_code_for_build(\\\"previously checked source\\\", public_execution=True)\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"user_id\\\", \\\"expected_public_execution\\\"),\\n    [\\n        (str(PUBLIC_ANONYMOUS_ACTOR_ID), True),\\n        (\\\"authenticated-owner\\\", False),\\n    ],\\n)\\ndef test_instantiate_class_marks_only_the_public_principal(monkeypatch, user_id, expected_public_execution):\\n    \\\"\\\"\\\"The final pre-eval resolver receives the execution principal's public status.\\\"\\\"\\\"\\n    seen: dict[str, object] = {}\\n\\n    def resolve(code: str, *, public_execution: bool = False) -> str:\\n        seen.update(code=code, public_execution=public_execution)\\n        return \\\"trusted source\\\"\\n\\n    class TestComponent:\\n        def __init__(self, **_kwargs):\\n            pass\\n\\n    monkeypatch.setattr(flow_validation, \\\"resolve_trusted_code_for_build\\\", resolve)\\n    monkeypatch.setattr(loading, \\\"eval_custom_component_code\\\", lambda _code: TestComponent)\\n    vertex = SimpleNamespace(\\n        vertex_type=\\\"TestComponent\\\",\\n        base_type=\\\"component\\\",\\n        params={\\\"code\\\": \\\"stored source\\\"},\\n        id=\\\"test-component\\\",\\n    )\\n\\n    component, params = loading.instantiate_class(vertex, user_id=user_id)\\n\\n    assert isinstance(component, TestComponent)\\n    assert params == {}\\n    assert seen == {\\\"code\\\": \\\"stored source\\\", \\\"public_execution\\\": expected_public_execution}\\n\\n\\ndef test_restricted_mode_no_match_fails_closed(monkeypatch):\\n    \\\"\\\"\\\"Restricted mode + no trusted hash match: fail closed (never fall back to client bytes).\\\"\\\"\\\"\\n    _set_allow_custom_components(monkeypatch, allow=False)\\n    monkeypatch.setattr(flow_validation, \\\"get_trusted_code_for_validation\\\", lambda _code: None)\\n    with pytest.raises(CustomComponentValidationError):\\n        resolve_trusted_code_for_build(\\\"attacker code with no trusted match\\\")\\n\\n\\ndef test_missing_settings_service_defaults_permissive(monkeypatch):\\n    \\\"\\\"\\\"If settings are unavailable, mirror the module's default (allow) and run the code unchanged.\\\"\\\"\\\"\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: None)\\n\\n    def _fail_if_called(_code):\\n        pytest.fail(\\\"trusted lookup must not run when settings unavailable (permissive default)\\\")\\n\\n    monkeypatch.setattr(flow_validation, \\\"get_trusted_code_for_validation\\\", _fail_if_called)\\n    assert resolve_trusted_code_for_build(\\\"some code\\\") == \\\"some code\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_restricted_component_mismatch.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e9a242e14f95581aa6b9ee4e36c415777f6792f27da8a06f0d729d47de8706c5\",\"content\":\"\\\"\\\"\\\"Restricted-mode diagnosis for a saved component this server replaced with its own.\\n\\nWith ``LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false`` a node's stored code never runs: the build\\nexecutes this server's component of the same ``data.type`` instead. That keeps flows saved\\nbefore an upgrade runnable, but it is silent, so a node that is a *customized* copy of a\\nbuilt-in is quietly rebuilt as the stock component and fails with whatever that component\\ncomplains about -- a customized Agent surfaces as \\\"No model selected\\\", naming neither the\\ncustomization nor the policy that discarded it.\\n\\nThese tests pin the diagnosis appended to such a failure, and the cases it must stay quiet for.\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport json\\nfrom copy import deepcopy\\nfrom importlib.resources import files\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom lfx.interface.components import component_cache\\nfrom lfx.utils.flow_validation import (\\n    describe_restricted_component_mismatch,\\n    explain_restricted_component_mismatch,\\n)\\n\\nSERVER_AGENT_CODE = \\\"# Agent (this server)\\\"\\n\\nSERVER_AGENT_OUTPUTS = [\\n    {\\n        \\\"name\\\": \\\"response\\\",\\n        \\\"display_name\\\": \\\"Response\\\",\\n        \\\"types\\\": [\\\"Message\\\"],\\n        \\\"method\\\": \\\"message_response\\\",\\n        \\\"allows_loop\\\": False,\\n    }\\n]\\n\\n\\ndef _registry() -> dict:\\n    \\\"\\\"\\\"A one-component registry whose Agent declares a required, unfillable ``model`` input.\\\"\\\"\\\"\\n    return {\\n        \\\"models_and_agents\\\": {\\n            \\\"Agent\\\": {\\n                \\\"template\\\": {\\n                    \\\"code\\\": {\\\"value\\\": SERVER_AGENT_CODE, \\\"required\\\": True, \\\"show\\\": True},\\n                    \\\"model\\\": {\\\"required\\\": True, \\\"value\\\": \\\"\\\", \\\"show\\\": True, \\\"_input_type\\\": \\\"ModelInput\\\"},\\n                    \\\"system_prompt\\\": {\\\"required\\\": False, \\\"value\\\": \\\"\\\", \\\"show\\\": True},\\n                },\\n                \\\"outputs\\\": SERVER_AGENT_OUTPUTS,\\n                \\\"metadata\\\": {\\\"code_hash\\\": \\\"hash-agent\\\"},\\n            }\\n        }\\n    }\\n\\n\\ndef _saved_agent(*, template: dict | None = None) -> dict:\\n    return {\\n        \\\"display_name\\\": \\\"Agent\\\",\\n        \\\"template\\\": template\\n        if template is not None\\n        else {\\n            \\\"code\\\": {\\\"value\\\": SERVER_AGENT_CODE, \\\"required\\\": True, \\\"show\\\": True},\\n            \\\"model\\\": {\\\"required\\\": True, \\\"value\\\": \\\"\\\", \\\"show\\\": True, \\\"_input_type\\\": \\\"ModelInput\\\"},\\n            \\\"system_prompt\\\": {\\\"required\\\": False, \\\"value\\\": \\\"\\\", \\\"show\\\": True},\\n        },\\n        \\\"outputs\\\": SERVER_AGENT_OUTPUTS,\\n    }\\n\\n\\ndef _customized_agent() -> dict:\\n    \\\"\\\"\\\"A fork of the built-in Agent: same ``type``, its own provider inputs, no ``model``.\\\"\\\"\\\"\\n    return _saved_agent(\\n        template={\\n            \\\"code\\\": {\\\"value\\\": SERVER_AGENT_CODE + \\\"\\\\n# customization\\\\n\\\", \\\"required\\\": True, \\\"show\\\": True},\\n            \\\"provider\\\": {\\\"required\\\": True, \\\"value\\\": \\\"\\\", \\\"show\\\": True, \\\"_input_type\\\": \\\"DropdownInput\\\"},\\n            \\\"system_prompt\\\": {\\\"required\\\": False, \\\"value\\\": \\\"\\\", \\\"show\\\": True},\\n        }\\n    )\\n\\n\\ndef _restrict(monkeypatch, *, allow_custom=False, registry=_registry, ready=True) -> None:\\n    monkeypatch.setattr(\\n        \\\"lfx.services.deps.get_settings_service\\\",\\n        lambda: SimpleNamespace(settings=SimpleNamespace(allow_custom_components=allow_custom)),\\n    )\\n    monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", registry() if registry else None)\\n    monkeypatch.setattr(component_cache, \\\"all_types_ready\\\", ready)\\n\\n\\ndef test_customized_builtin_is_named_with_the_policy_that_replaced_it(monkeypatch):\\n    _restrict(monkeypatch)\\n\\n    hint = describe_restricted_component_mismatch(\\\"Agent\\\", _customized_agent())\\n\\n    assert hint is not None\\n    assert \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false\\\" in hint\\n    assert '\\\"Agent\\\"' in hint\\n    assert \\\"missing required input: model\\\" in hint\\n\\n\\ndef test_permissive_mode_says_nothing(monkeypatch):\\n    \\\"\\\"\\\"With custom components allowed the node's own code runs, so nothing was replaced.\\\"\\\"\\\"\\n    _restrict(monkeypatch, allow_custom=True)\\n\\n    assert describe_restricted_component_mismatch(\\\"Agent\\\", _customized_agent()) is None\\n\\n\\ndef test_component_matching_this_server_says_nothing(monkeypatch):\\n    \\\"\\\"\\\"A node this server's component can drive must not be blamed for an unrelated failure.\\\"\\\"\\\"\\n    _restrict(monkeypatch)\\n\\n    assert describe_restricted_component_mismatch(\\\"Agent\\\", _saved_agent()) is None\\n\\n\\ndef test_unknown_component_type_says_nothing(monkeypatch):\\n    \\\"\\\"\\\"An unrecognized type never reaches a build -- ``check_flow_and_raise`` blocks it first.\\\"\\\"\\\"\\n    _restrict(monkeypatch)\\n\\n    assert describe_restricted_component_mismatch(\\\"TotallyCustom\\\", _customized_agent()) is None\\n\\n\\ndef test_registry_not_loaded_says_nothing(monkeypatch):\\n    _restrict(monkeypatch, registry=None, ready=False)\\n\\n    assert describe_restricted_component_mismatch(\\\"Agent\\\", _customized_agent()) is None\\n\\n\\n@pytest.mark.parametrize((\\\"component_type\\\", \\\"node_info\\\"), [(None, _customized_agent()), (\\\"Agent\\\", None), (\\\"\\\", {})])\\ndef test_malformed_input_says_nothing(monkeypatch, component_type, node_info):\\n    _restrict(monkeypatch)\\n\\n    assert describe_restricted_component_mismatch(component_type, node_info) is None\\n\\n\\ndef test_breaking_outputs_are_reported_without_a_missing_input_clause(monkeypatch):\\n    \\\"\\\"\\\"Not every mismatch is a missing input; the clause is dropped rather than left empty.\\\"\\\"\\\"\\n    _restrict(monkeypatch)\\n    node_info = _saved_agent()\\n    node_info[\\\"outputs\\\"] = [{\\\"name\\\": \\\"renamed\\\", \\\"display_name\\\": \\\"Renamed\\\", \\\"types\\\": [\\\"Message\\\"]}]\\n\\n    hint = describe_restricted_component_mismatch(\\\"Agent\\\", node_info)\\n\\n    assert hint is not None\\n    assert \\\"missing required input\\\" not in hint\\n\\n\\ndef test_explain_never_raises(monkeypatch):\\n    \\\"\\\"\\\"The only caller is an error handler: a raising diagnosis would mask the real failure.\\\"\\\"\\\"\\n\\n    def _boom():\\n        msg = \\\"registry exploded\\\"\\n        raise RuntimeError(msg)\\n\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", _boom)\\n\\n    assert explain_restricted_component_mismatch(\\\"Agent\\\", _customized_agent()) is None\\n\\n\\nasync def test_build_error_carries_the_diagnosis(monkeypatch):\\n    \\\"\\\"\\\"The failure a user actually sees names the policy, not just the stock component's complaint.\\\"\\\"\\\"\\n    from lfx.exceptions.component import ComponentBuildError\\n    from lfx.graph.vertex.base import Vertex\\n\\n    _restrict(monkeypatch)\\n\\n    async def _raise(**_kwargs):\\n        msg = \\\"No model selected. Please select a language model from the available options.\\\"\\n        raise ValueError(msg)\\n\\n    monkeypatch.setattr(\\\"lfx.interface.initialize.loading.get_instance_results\\\", _raise)\\n\\n    vertex = Vertex.__new__(Vertex)\\n    vertex.display_name = \\\"Agent\\\"\\n    vertex.data = {\\\"type\\\": \\\"Agent\\\", \\\"node\\\": _customized_agent()}\\n    vertex.graph = SimpleNamespace(flow_id=None)\\n\\n    with pytest.raises(ComponentBuildError) as excinfo:\\n        await vertex._build_results(custom_component=None, custom_params={}, base_type=\\\"component\\\")\\n\\n    message = str(excinfo.value)\\n    assert \\\"No model selected\\\" in message\\n    assert \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false\\\" in message\\n    assert \\\"missing required input: model\\\" in message\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"allow_custom\\\", \\\"customized\\\", \\\"expect_hint\\\"),\\n    [(False, True, True), (False, False, False), (True, True, False)],\\n)\\nasync def test_first_streamed_error_carries_the_diagnosis(monkeypatch, allow_custom, customized, expect_hint):\\n    \\\"\\\"\\\"The real Agent emits an error before the vertex wraps it; AG-UI stops on that first event.\\\"\\\"\\\"\\n    from ag_ui.core import RunErrorEvent\\n    from lfx.events.event_manager import EventManager\\n    from lfx.exceptions.component import ComponentBuildError\\n    from lfx.graph import Graph\\n    from lfx.interface import components as components_module\\n    from lfx.services.deps import get_settings_service\\n    from lfx.workflow.agui_translator import AGUITranslator\\n\\n    registry = dict(json.loads(files(\\\"lfx\\\").joinpath(\\\"_assets/component_index.json\\\").read_text())[\\\"entries\\\"])\\n    # Keep the registry and its derived lookups isolated from earlier tests.\\n    cache = components_module.ComponentCache()\\n    cache.all_types_dict = registry\\n    cache.all_types_ready = True\\n    monkeypatch.setattr(components_module, \\\"component_cache\\\", cache)\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"allow_custom_components\\\", allow_custom)\\n    monkeypatch.setattr(settings, \\\"substitute_outdated_component_code\\\", True)\\n    saved = deepcopy(registry[\\\"models_and_agents\\\"][\\\"Agent\\\"])\\n    if customized:\\n        saved[\\\"template\\\"].pop(\\\"model\\\")\\n        saved[\\\"template\\\"][\\\"code\\\"][\\\"value\\\"] += \\\"\\\\n# Customized Agent\\\\n\\\"\\n        saved[\\\"template\\\"][\\\"provider\\\"] = {\\n            \\\"name\\\": \\\"provider\\\",\\n            \\\"type\\\": \\\"str\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"required\\\": True,\\n            \\\"show\\\": True,\\n        }\\n    node = {\\\"id\\\": \\\"Agent-repro\\\", \\\"data\\\": {\\\"id\\\": \\\"Agent-repro\\\", \\\"type\\\": \\\"Agent\\\", \\\"node\\\": saved}}\\n    graph = Graph.from_payload({\\\"nodes\\\": [node], \\\"edges\\\": []}, emit_extension_events=False)\\n    graph.set_run_id()\\n    graph.session_id = \\\"restricted-component-stream-test\\\"\\n    graph.persist_messages = False\\n    vertex = graph.get_vertex(\\\"Agent-repro\\\")\\n    queue = asyncio.Queue()\\n    event_manager = EventManager(queue)\\n    event_manager.register_event(\\\"on_error\\\", \\\"error\\\")\\n    vertex.custom_component.set_event_manager(event_manager)\\n\\n    with pytest.raises(ComponentBuildError, match=\\\"No model selected\\\") as excinfo:\\n        await vertex._build_results(custom_component=vertex.custom_component, custom_params={}, base_type=\\\"component\\\")\\n\\n    _, raw, _ = await asyncio.wait_for(queue.get(), timeout=1)\\n    payload = json.loads(raw)\\n    events = AGUITranslator(run_id=\\\"run\\\", thread_id=graph.session_id).translate(payload[\\\"event\\\"], payload[\\\"data\\\"])\\n    assert len(events) == 1\\n    assert isinstance(events[0], RunErrorEvent)\\n    assert \\\"No model selected\\\" in events[0].message\\n    assert (\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false\\\" in events[0].message) is expect_hint\\n    assert isinstance(excinfo.value.__cause__, ValueError)\\n    assert (\\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false\\\" in str(excinfo.value)) is expect_hint\\n    if expect_hint:\\n        assert \\\"missing required input: model\\\" in events[0].message\\n        reasons = [\\n            content[\\\"reason\\\"]\\n            for block in payload[\\\"data\\\"][\\\"content_blocks\\\"]\\n            for content in block.get(\\\"contents\\\", [])\\n            if content[\\\"type\\\"] == \\\"error\\\"\\n        ]\\n        assert len(reasons) == 1\\n        assert \\\"ValueError\\\" in reasons[0]\\n        assert \\\"LANGFLOW_ALLOW_CUSTOM_COMPONENTS=false\\\" in reasons[0]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_sandbox.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"85b9bb128429bfc65d6f404af7ca73a700968a93acf482a67cbe37183bae759c\",\"content\":\"\\\"\\\"\\\"Unit tests for the opt-in microVM sandbox backend (issue #12029).\\n\\nThese tests never require exec-sandbox or QEMU: the exec_sandbox module is\\nstubbed into sys.modules so the routing, fail-closed, and result-mapping logic\\nis exercised everywhere CI runs.\\n\\\"\\\"\\\"\\n\\nimport os\\nimport sys\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom lfx.utils import sandbox as sandbox_module\\nfrom lfx.utils.sandbox import (\\n    SandboxExecutionError,\\n    SandboxUnavailableError,\\n    build_import_preamble,\\n    get_sandbox_backend,\\n    is_sandbox_enabled,\\n    run_code_in_sandbox,\\n    sanitize_code,\\n)\\nfrom lfx.utils.sandbox import exec_sandbox as exec_module\\nfrom lfx.utils.sandbox import registry as registry_module\\n\\n\\ndef _settings(backend, **extra):\\n    \\\"\\\"\\\"Return a fake settings service with the given sandbox backend and overrides.\\\"\\\"\\\"\\n    defaults = {\\n        \\\"sandbox_backend\\\": backend,\\n        \\\"sandbox_timeout_seconds\\\": 30,\\n        \\\"sandbox_memory_mb\\\": 192,\\n        \\\"sandbox_allow_network\\\": False,\\n        \\\"sandbox_allowed_domains\\\": [],\\n        \\\"sandbox_allow_software_emulation\\\": False,\\n    }\\n    defaults.update(extra)\\n    return SimpleNamespace(settings=SimpleNamespace(**defaults))\\n\\n\\n@pytest.fixture(autouse=True)\\ndef fresh_executor(monkeypatch):\\n    \\\"\\\"\\\"Give each test its own executor and tear down its loop thread afterwards.\\\"\\\"\\\"\\n    import atexit\\n\\n    executor = exec_module._ExecSandboxExecutor()\\n    monkeypatch.setitem(registry_module._instances, \\\"exec-sandbox\\\", executor)\\n    yield executor\\n    # Tear down so daemon loop threads and atexit hooks don't accumulate\\n    # across the test session.\\n    atexit.unregister(executor.shutdown)\\n    executor.shutdown()\\n    loop, thread = executor._loop, executor._thread\\n    if loop is not None and not loop.is_closed():\\n        loop.call_soon_threadsafe(loop.stop)\\n        if thread is not None:\\n            thread.join(timeout=5)\\n        loop.close()\\n\\n\\nclass _FakeExecutionResult:\\n    \\\"\\\"\\\"Stand in for exec_sandbox's execution result value.\\\"\\\"\\\"\\n\\n    def __init__(self, stdout=\\\"\\\", stderr=\\\"\\\", exit_code=0, execution_time_ms=5):\\n        \\\"\\\"\\\"Store the fake stdout, stderr, exit code, and execution time.\\\"\\\"\\\"\\n        self.stdout = stdout\\n        self.stderr = stderr\\n        self.exit_code = exit_code\\n        self.execution_time_ms = execution_time_ms\\n\\n\\nclass _FakeScheduler:\\n    \\\"\\\"\\\"Stands in for exec_sandbox.Scheduler; records the kwargs run() received.\\\"\\\"\\\"\\n\\n    instances: list = []\\n\\n    def __init__(self, config=None):\\n        \\\"\\\"\\\"Store the config and record this instance for later inspection.\\\"\\\"\\\"\\n        self.config = config\\n        self.run_calls: list[dict] = []\\n        self.entered = False\\n        self.exited = False\\n        type(self).instances.append(self)\\n\\n    async def __aenter__(self):\\n        \\\"\\\"\\\"Yield control, then mark the scheduler as entered.\\\"\\\"\\\"\\n        # Yield control so concurrent first calls genuinely interleave here,\\n        # exercising the scheduler-creation lock.\\n        import asyncio\\n\\n        await asyncio.sleep(0.02)\\n        self.entered = True\\n        return self\\n\\n    async def __aexit__(self, *args):\\n        \\\"\\\"\\\"Mark the scheduler as exited without suppressing an exception.\\\"\\\"\\\"\\n        self.exited = True\\n        return False\\n\\n    async def run(self, **kwargs):\\n        \\\"\\\"\\\"Record the run call and return a canned result based on the code sent.\\\"\\\"\\\"\\n        # Yield once so lifecycle transitions (e.g. a concurrent shutdown)\\n        # can interleave between scheduler acquisition and completion.\\n        import asyncio\\n\\n        await asyncio.sleep(0)\\n        self.run_calls.append(kwargs)\\n        code = kwargs[\\\"code\\\"]\\n        if \\\"BOOM_INFRA\\\" in code:\\n            msg = \\\"vm exploded\\\"\\n            raise RuntimeError(msg)\\n        if \\\"FAIL_CODE\\\" in code:\\n            return _FakeExecutionResult(stderr=\\\"NameError: nope\\\", exit_code=1)\\n        if \\\"TIMEOUT\\\" in code:\\n            return _FakeExecutionResult(exit_code=-1)\\n        if \\\"OOM_KILL\\\" in code:\\n            return _FakeExecutionResult(exit_code=137)\\n        return _FakeExecutionResult(stdout=\\\"hello from vm\\\\n\\\")\\n\\n\\nclass _FakeSchedulerConfig:\\n    \\\"\\\"\\\"Stand in for exec_sandbox.SchedulerConfig; records the kwargs it received.\\\"\\\"\\\"\\n\\n    def __init__(self, **kwargs):\\n        \\\"\\\"\\\"Store the kwargs the config was built with.\\\"\\\"\\\"\\n        self.kwargs = kwargs\\n\\n\\n@pytest.fixture\\ndef fake_exec_sandbox(monkeypatch):\\n    \\\"\\\"\\\"See _install_fake_exec_sandbox; kept as a named fixture for value access.\\\"\\\"\\\"\\n    return _install_fake_exec_sandbox(monkeypatch)\\n\\n\\ndef _install_fake_exec_sandbox(monkeypatch):\\n    \\\"\\\"\\\"Install a stub exec_sandbox module and return the fake Scheduler class.\\n\\n    Also fakes hardware acceleration as available: CI runners have no\\n    /dev/kvm, and these tests exercise routing/mapping logic, not the\\n    TCG-refusal gate (which has its own dedicated tests).\\n    \\\"\\\"\\\"\\n    _FakeScheduler.instances = []\\n\\n    def _fake_upstream_settings():\\n        \\\"\\\"\\\"Return a fake upstream settings object reading EXEC_SANDBOX_FORCE_EMULATION.\\\"\\\"\\\"\\n        # Mirrors upstream: a pydantic bool field fed by EXEC_SANDBOX_FORCE_EMULATION.\\n        raw = os.environ.get(\\\"EXEC_SANDBOX_FORCE_EMULATION\\\", \\\"\\\").strip().lower()\\n        return SimpleNamespace(force_emulation=raw in {\\\"1\\\", \\\"true\\\", \\\"yes\\\", \\\"on\\\", \\\"y\\\", \\\"t\\\"})\\n\\n    async def _detect_accel_type(kvm_available=None, hvf_available=None, *, force_emulation=False):  # noqa: ARG001\\n        \\\"\\\"\\\"Return \\\"kvm\\\", or \\\"tcg\\\" when emulation is forced.\\\"\\\"\\\"\\n        return \\\"tcg\\\" if force_emulation else \\\"kvm\\\"\\n\\n    accel_type = SimpleNamespace(KVM=\\\"kvm\\\", HVF=\\\"hvf\\\", TCG=\\\"tcg\\\")\\n    probes = SimpleNamespace(detect_accel_type=_detect_accel_type)\\n    settings_mod = SimpleNamespace(Settings=_fake_upstream_settings)\\n    vm_types = SimpleNamespace(AccelType=accel_type)\\n    module = SimpleNamespace(\\n        Scheduler=_FakeScheduler,\\n        SchedulerConfig=_FakeSchedulerConfig,\\n        system_probes=probes,\\n        settings=settings_mod,\\n        vm_types=vm_types,\\n    )\\n    monkeypatch.setitem(sys.modules, \\\"exec_sandbox\\\", module)\\n    monkeypatch.setitem(sys.modules, \\\"exec_sandbox.system_probes\\\", probes)\\n    monkeypatch.setitem(sys.modules, \\\"exec_sandbox.settings\\\", settings_mod)\\n    monkeypatch.setitem(sys.modules, \\\"exec_sandbox.vm_types\\\", vm_types)\\n    monkeypatch.setattr(exec_module, \\\"_hardware_acceleration_available\\\", lambda: True)\\n    return _FakeScheduler\\n\\n\\nclass TestBackendSelection:\\n    \\\"\\\"\\\"Verify how the configured sandbox backend is resolved.\\\"\\\"\\\"\\n\\n    def test_default_is_none(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that the sandbox backend defaults to \\\"none\\\" and stays disabled.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"none\\\"))\\n        assert get_sandbox_backend() == \\\"none\\\"\\n        assert not is_sandbox_enabled()\\n\\n    def test_exec_sandbox_enables(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that selecting exec-sandbox enables the sandbox.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        assert get_sandbox_backend() == \\\"exec-sandbox\\\"\\n        assert is_sandbox_enabled()\\n\\n    # An unresolvable settings stack falls back to the environment, so these\\n    # three assert the \\\"nothing is configured anywhere\\\" case and have to clear\\n    # the variable. TestSettingsUnavailableFailsClosed covers the case where\\n    # the operator DID configure a backend and settings failed to build.\\n    def test_absent_services_layer_means_none(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a missing settings service with no env var means \\\"none\\\".\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LANGFLOW_SANDBOX_BACKEND\\\", raising=False)\\n        monkeypatch.delattr(\\\"lfx.services.deps.get_settings_service\\\")\\n        assert get_sandbox_backend() == \\\"none\\\"\\n\\n    def test_none_settings_service_means_none(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a settings service returning None means \\\"none\\\".\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LANGFLOW_SANDBOX_BACKEND\\\", raising=False)\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: None)\\n        assert get_sandbox_backend() == \\\"none\\\"\\n\\n    def test_settings_without_field_means_none(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a settings object missing the sandbox_backend field means \\\"none\\\".\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LANGFLOW_SANDBOX_BACKEND\\\", raising=False)\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: SimpleNamespace(settings=SimpleNamespace()),\\n        )\\n        assert get_sandbox_backend() == \\\"none\\\"\\n\\n\\nclass TestImportPreamble:\\n    \\\"\\\"\\\"Verify how build_import_preamble turns a module list into import statements.\\\"\\\"\\\"\\n\\n    def test_string_input(self):\\n        \\\"\\\"\\\"Verify that a comma-separated string builds one import per module.\\\"\\\"\\\"\\n        assert build_import_preamble(\\\"math, json\\\") == \\\"import math\\\\nimport json\\\"\\n\\n    def test_list_input(self):\\n        \\\"\\\"\\\"Verify that a list of module names builds one import per module.\\\"\\\"\\\"\\n        assert build_import_preamble([\\\"math\\\", \\\"os.path\\\"]) == \\\"import math\\\\nimport os.path\\\"\\n\\n    def test_empty(self):\\n        \\\"\\\"\\\"Verify that an empty string or list builds an empty preamble.\\\"\\\"\\\"\\n        assert build_import_preamble(\\\"\\\") == \\\"\\\"\\n        assert build_import_preamble([]) == \\\"\\\"\\n\\n    def test_rejects_injection(self):\\n        \\\"\\\"\\\"Verify that a module name with extra statements is rejected.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid module name\\\"):\\n            build_import_preamble(\\\"math; import os\\\")\\n        with pytest.raises(ValueError, match=\\\"Invalid module name\\\"):\\n            build_import_preamble(\\\"os\\\\nimport subprocess\\\")\\n\\n    def test_rejects_non_string_types(self):\\n        \\\"\\\"\\\"Verify that a non-string, non-list input raises TypeError.\\\"\\\"\\\"\\n        with pytest.raises(TypeError):\\n            build_import_preamble(42)\\n\\n\\nclass TestSanitizeCode:\\n    \\\"\\\"\\\"Parity with PythonREPL.sanitize_input: markdown fences are stripped.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"raw\\\", \\\"expected\\\"),\\n        [\\n            (\\\"print('hi')\\\", \\\"print('hi')\\\"),\\n            (\\\"```python\\\\nprint('hi')\\\\n```\\\", \\\"print('hi')\\\"),\\n            (\\\"```\\\\nprint('hi')\\\\n```\\\", \\\"print('hi')\\\"),\\n            (\\\"python\\\\nprint('hi')\\\", \\\"print('hi')\\\"),\\n            (\\\"  print('hi')  \\\", \\\"print('hi')\\\"),\\n        ],\\n    )\\n    def test_strips_fences(self, raw, expected):\\n        \\\"\\\"\\\"Verify that markdown code fences and surrounding whitespace are stripped.\\\"\\\"\\\"\\n        assert sanitize_code(raw) == expected\\n\\n\\nclass TestRunCodeInSandbox:\\n    \\\"\\\"\\\"Verify run_code_in_sandbox's routing, result mapping, and fail-closed behavior.\\\"\\\"\\\"\\n\\n    def test_refuses_when_not_configured(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a \\\"none\\\" backend raises SandboxExecutionError.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"none\\\"))\\n        with pytest.raises(SandboxExecutionError, match=\\\"no sandbox backend\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n\\n    def test_unknown_backend_fails_closed(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that an unrecognized backend name raises SandboxUnavailableError.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"firecracker\\\"))\\n        with pytest.raises(SandboxUnavailableError, match=\\\"Unknown sandbox backend\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n\\n    def test_missing_package_fails_closed(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a configured backend whose package cannot import fails closed.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        monkeypatch.setitem(sys.modules, \\\"exec_sandbox\\\", None)  # import raises ImportError\\n        with pytest.raises(SandboxUnavailableError, match=r\\\"exec-sandbox.*not installed\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_success_maps_result(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a successful run maps to a success result with stdout and exit code.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        result = run_code_in_sandbox(\\\"print('hello from vm')\\\")\\n        assert result.success\\n        assert result.stdout == \\\"hello from vm\\\\n\\\"\\n        assert result.exit_code == 0\\n\\n    def test_global_imports_prepended(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Verify that global_imports are prepended as import statements before the code.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        run_code_in_sandbox(\\\"print(math.pi)\\\", global_imports=\\\"math, json\\\")\\n        scheduler = fake_exec_sandbox.instances[-1]\\n        code = scheduler.run_calls[-1][\\\"code\\\"]\\n        assert code.startswith(\\\"import math\\\\nimport json\\\\n\\\")\\n        assert code.endswith(\\\"print(math.pi)\\\")\\n\\n    def test_settings_forwarded_to_backend(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Verify that timeout, memory, network, and domain settings reach the backend's run call.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: _settings(\\n                \\\"exec-sandbox\\\",\\n                sandbox_timeout_seconds=77,\\n                sandbox_memory_mb=256,\\n                sandbox_allow_network=True,\\n                sandbox_allowed_domains=[\\\"api.example.com\\\"],\\n            ),\\n        )\\n        run_code_in_sandbox(\\\"print('hi')\\\")\\n        scheduler = fake_exec_sandbox.instances[-1]\\n        call = scheduler.run_calls[-1]\\n        assert call[\\\"timeout_seconds\\\"] == 77\\n        assert call[\\\"memory_mb\\\"] == 256\\n        assert call[\\\"allow_network\\\"] is True\\n        assert call[\\\"allowed_domains\\\"] == [\\\"api.example.com\\\"]\\n        # exec_sandbox's run() takes env_vars (not env)\\n        assert call[\\\"env_vars\\\"] == {}\\n        # Warm pool is deliberately not configured (upstream pool contract\\n        # mismatch: per-language pools at fixed memory).\\n        assert scheduler.config.kwargs == {}\\n\\n    def test_network_is_disabled_by_default(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Default settings must reach the backend as allow_network=False (offline VM).\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        run_code_in_sandbox(\\\"print('hi')\\\")\\n        call = fake_exec_sandbox.instances[-1].run_calls[-1]\\n        assert call[\\\"allow_network\\\"] is False\\n        # No allowed_domains configured -> None reaches the backend (which\\n        # then applies its package-registry-only default filter).\\n        assert call[\\\"allowed_domains\\\"] is None\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_user_code_failure_is_result_not_exception(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that user code failure returns a failed result, not a raised exception.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        result = run_code_in_sandbox(\\\"FAIL_CODE\\\")\\n        assert not result.success\\n        assert result.exit_code == 1\\n        assert \\\"NameError\\\" in result.error_message()\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_timeout_exit_code_message(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a timeout exit code produces a \\\"timed out\\\" error message.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        result = run_code_in_sandbox(\\\"TIMEOUT\\\")\\n        assert not result.success\\n        assert \\\"timed out\\\" in result.error_message()\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_infrastructure_error_wrapped(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a scheduler exception is wrapped in SandboxExecutionError.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        with pytest.raises(SandboxExecutionError, match=\\\"vm exploded\\\"):\\n            run_code_in_sandbox(\\\"BOOM_INFRA\\\")\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_oom_exit_code_message(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that an OOM exit code produces a \\\"memory\\\" error message.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        result = run_code_in_sandbox(\\\"OOM_KILL\\\")\\n        assert not result.success\\n        assert \\\"memory\\\" in result.error_message()\\n\\n    def test_blank_code_returns_empty_success(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Blank code is an empty result, matching the in-process interpreter.\\n\\n        exec-sandbox rejects empty code outright, which would otherwise\\n        surface as an infrastructure error, so it must never be invoked.\\n        \\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        result = run_code_in_sandbox(\\\"   \\\\n  \\\")\\n        assert result.success\\n        assert result.stdout == \\\"\\\"\\n        assert not fake_exec_sandbox.instances\\n\\n    def test_future_imports_stay_first(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"The import preamble must not precede `from __future__ import ...`.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        code = '\\\"\\\"\\\"doc.\\\"\\\"\\\"\\\\nfrom __future__ import annotations\\\\nprint(1)'\\n        run_code_in_sandbox(code, global_imports=\\\"math\\\")\\n        sent = fake_exec_sandbox.instances[-1].run_calls[-1][\\\"code\\\"]\\n        lines = sent.splitlines()\\n        assert lines[0] == '\\\"\\\"\\\"doc.\\\"\\\"\\\"'\\n        assert lines[1] == \\\"from __future__ import annotations\\\"\\n        assert \\\"import math\\\" in lines[2]\\n        compile(sent, \\\"<test>\\\", \\\"exec\\\")  # composed code must be valid Python\\n\\n    def test_deep_probe_refusal_overrides_shallow_pass(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Upstream's accelerator decision is authoritative over the shallow preflight.\\n\\n        detect_accel_type is exec-sandbox's single source of truth; when it\\n        says TCG, a shallow pass must not permit execution.\\n        \\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n\\n        async def _tcg_accel(**_kwargs):\\n            \\\"\\\"\\\"Return \\\"tcg\\\" regardless of arguments.\\\"\\\"\\\"\\n            return \\\"tcg\\\"\\n\\n        monkeypatch.setattr(sys.modules[\\\"exec_sandbox.system_probes\\\"], \\\"detect_accel_type\\\", _tcg_accel)\\n        with pytest.raises(SandboxUnavailableError, match=\\\"TCG\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n        assert not fake_exec_sandbox.instances\\n\\n    def test_fails_closed_when_accel_decision_unobtainable(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"If upstream's decision API is missing, refuse \u2014 never guess via the shallow check.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n\\n        async def _boom(**_kwargs):\\n            \\\"\\\"\\\"Raise RuntimeError to simulate a missing accelerator decision API.\\\"\\\"\\\"\\n            msg = \\\"probe API moved\\\"\\n            raise RuntimeError(msg)\\n\\n        monkeypatch.setattr(sys.modules[\\\"exec_sandbox.system_probes\\\"], \\\"detect_accel_type\\\", _boom)\\n        with pytest.raises(SandboxUnavailableError, match=\\\"could not determine\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n        assert not fake_exec_sandbox.instances\\n\\n    @pytest.mark.parametrize(\\\"spelling\\\", [\\\"true\\\", \\\"on\\\", \\\"t\\\", \\\"Y\\\"])\\n    def test_forced_emulation_env_refused(self, monkeypatch, fake_exec_sandbox, spelling):\\n        \\\"\\\"\\\"Every pydantic-truthy spelling upstream accepts must be refused here too.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        monkeypatch.setenv(\\\"EXEC_SANDBOX_FORCE_EMULATION\\\", spelling)\\n        with pytest.raises(SandboxUnavailableError, match=\\\"TCG\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n        assert not fake_exec_sandbox.instances\\n\\n    def test_shutdown_is_restartable(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Run -> shutdown_sandbox() -> run must create a fresh scheduler.\\\"\\\"\\\"\\n        from lfx.utils.sandbox import shutdown_sandbox\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        assert run_code_in_sandbox(\\\"print('hi')\\\").success\\n        shutdown_sandbox()\\n        assert run_code_in_sandbox(\\\"print('hi')\\\").success\\n        assert len(fake_exec_sandbox.instances) == 2\\n\\n    def test_same_line_future_import_composes_correctly(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Semicolon-joined statements after a future import must run AFTER the preamble.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        code = \\\"from __future__ import annotations; print(math.pi)\\\"\\n        run_code_in_sandbox(code, global_imports=\\\"math\\\")\\n        sent = fake_exec_sandbox.instances[-1].run_calls[-1][\\\"code\\\"]\\n        compile(sent, \\\"<test>\\\", \\\"exec\\\")\\n        assert sent.index(\\\"import math\\\") < sent.index(\\\"print(math.pi)\\\")\\n        assert sent.index(\\\"from __future__\\\") < sent.index(\\\"import math\\\")\\n\\n    def test_same_line_docstring_composes_correctly(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Verify that a semicolon-joined statement after a docstring composes correctly.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        code = '\\\"\\\"\\\"doc.\\\"\\\"\\\"; print(math.pi)'\\n        run_code_in_sandbox(code, global_imports=\\\"math\\\")\\n        sent = fake_exec_sandbox.instances[-1].run_calls[-1][\\\"code\\\"]\\n        compile(sent, \\\"<test>\\\", \\\"exec\\\")\\n        assert sent.index(\\\"import math\\\") < sent.index(\\\"print(math.pi)\\\")\\n\\n    def test_refuses_tcg_without_override(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"No hardware hypervisor -> fail closed rather than silently run under TCG.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        monkeypatch.setattr(exec_module, \\\"_hardware_acceleration_available\\\", lambda: False)\\n        with pytest.raises(SandboxUnavailableError, match=\\\"hardware\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n        assert not fake_exec_sandbox.instances\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_software_emulation_override_allows_tcg(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that sandbox_allow_software_emulation lets a run proceed under TCG.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: _settings(\\\"exec-sandbox\\\", sandbox_allow_software_emulation=True),\\n        )\\n        monkeypatch.setattr(exec_module, \\\"_hardware_acceleration_available\\\", lambda: False)\\n        result = run_code_in_sandbox(\\\"print('hello from vm')\\\")\\n        assert result.success\\n\\n    def test_unicode_docstring_same_line_composes_correctly(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Ast col_offset is a UTF-8 byte offset; non-ASCII text must not shift the split.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        code = '\\\"\\\"\\\"caf\\\\u00e9.\\\"\\\"\\\"; print(math.pi)'\\n        run_code_in_sandbox(code, global_imports=\\\"math\\\")\\n        sent = fake_exec_sandbox.instances[-1].run_calls[-1][\\\"code\\\"]\\n        compile(sent, \\\"<test>\\\", \\\"exec\\\")\\n        assert \\\"print(math.pi)\\\" in sent\\n        assert sent.index(\\\"import math\\\") < sent.index(\\\"print(math.pi)\\\")\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_startup_grace_until_first_run_completes(self, monkeypatch, fresh_executor):\\n        \\\"\\\"\\\"Readiness flips only after a run completes, not when the scheduler appears.\\\"\\\"\\\"\\n        from lfx.utils.sandbox import shutdown_sandbox\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        assert not fresh_executor._startup_complete\\n        run_code_in_sandbox(\\\"print('hi')\\\")\\n        assert fresh_executor._startup_complete\\n        shutdown_sandbox()\\n        # A restarted sandbox needs the startup margin again.\\n        assert not fresh_executor._startup_complete\\n\\n    def test_unknown_accelerator_refused(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Allowlist semantics: anything that is not exactly KVM/HVF fails closed.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n\\n        async def _novel_accel(**_kwargs):\\n            \\\"\\\"\\\"Return an accelerator type that is neither KVM, HVF, nor TCG.\\\"\\\"\\\"\\n            return \\\"warp-drive\\\"\\n\\n        monkeypatch.setattr(sys.modules[\\\"exec_sandbox.system_probes\\\"], \\\"detect_accel_type\\\", _novel_accel)\\n        with pytest.raises(SandboxUnavailableError, match=\\\"warp-drive\\\"):\\n            run_code_in_sandbox(\\\"print('hi')\\\")\\n        assert not fake_exec_sandbox.instances\\n\\n    @pytest.mark.parametrize(\\\"separator\\\", [\\\"\\\\u2028\\\", \\\"\\\\u2029\\\"])\\n    def test_unicode_line_separator_in_docstring_composes_correctly(self, monkeypatch, fake_exec_sandbox, separator):\\n        \\\"\\\"\\\"U+2028/U+2029 are ordinary characters to the tokenizer, not line breaks.\\n\\n        str.splitlines() would treat them as boundaries and shift every\\n        subsequent offset, dropping the preamble inside the docstring.\\n        \\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        code = f'\\\"\\\"\\\"a{separator}b\\\"\\\"\\\"; print(math.pi)'\\n        run_code_in_sandbox(code, global_imports=\\\"math\\\")\\n        sent = fake_exec_sandbox.instances[-1].run_calls[-1][\\\"code\\\"]\\n        compile(sent, \\\"<test>\\\", \\\"exec\\\")\\n        assert \\\"print(math.pi)\\\" in sent\\n        assert sent.index(\\\"import math\\\") < sent.index(\\\"print(math.pi)\\\")\\n\\n    def test_shutdown_closes_run_submitted_before_loop_executed_it(\\n        self, monkeypatch, fresh_executor, fake_exec_sandbox\\n    ):\\n        \\\"\\\"\\\"A run accepted before shutdown is closed even before its coroutine runs.\\n\\n        The pre-creation-lock window: the loop is frozen so the submitted run\\n        coroutine cannot execute; the shutdown submitted afterwards must queue\\n        behind it and close the scheduler that run creates.\\n        \\\"\\\"\\\"\\n        import threading\\n        import time\\n\\n        from lfx.utils.sandbox import shutdown_sandbox\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n\\n        # Create the loop, then freeze it so nothing submitted can execute.\\n        with fresh_executor._lock:\\n            loop = fresh_executor._ensure_loop_locked()\\n        release = threading.Event()\\n        frozen = threading.Event()\\n\\n        def freeze():\\n            \\\"\\\"\\\"Signal that the loop is frozen, then block until released.\\\"\\\"\\\"\\n            frozen.set()\\n            release.wait(timeout=5)\\n\\n        loop.call_soon_threadsafe(freeze)\\n        assert frozen.wait(timeout=5)\\n\\n        results = []\\n        worker = threading.Thread(target=lambda: results.append(run_code_in_sandbox(\\\"print('hi')\\\")), daemon=True)\\n        worker.start()\\n        # Wait for the worker to have SUBMITTED (it then blocks in\\n        # future.result); the loop is still frozen, so no scheduler exists yet.\\n        deadline = time.monotonic() + 5\\n        while time.monotonic() < deadline:\\n            with fresh_executor._lock:\\n                submitted = fresh_executor._loop is loop and fresh_executor._scheduler_lock is not None\\n            if submitted and worker.is_alive():\\n                break\\n            time.sleep(0.001)\\n        assert not fake_exec_sandbox.instances\\n\\n        shutdown_pathway = threading.Thread(target=shutdown_sandbox, daemon=True)\\n        shutdown_pathway.start()\\n        time.sleep(0.01)  # let shutdown submit its close behind the run\\n        release.set()\\n        worker.join(timeout=5)\\n        shutdown_pathway.join(timeout=5)\\n        assert not worker.is_alive()\\n        assert not shutdown_pathway.is_alive()\\n        # The run executed first (FIFO), created a scheduler, and the queued\\n        # close then closed it \u2014 nothing left open.\\n        assert fake_exec_sandbox.instances\\n        assert fake_exec_sandbox.instances[0].exited\\n        assert fresh_executor._scheduler is None\\n        assert not fresh_executor._startup_complete\\n\\n    def test_run_after_shutdown_gets_startup_grace(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"A cold start following a shutdown must run under the startup margin.\\n\\n        Reproduces the compressed-margin scenario: with the steady-state\\n        grace squeezed to zero, a post-shutdown run only succeeds because it\\n        is classified as a first execution (startup grace), proving the\\n        readiness capture and shutdown are ordered.\\n        \\\"\\\"\\\"\\n        from lfx.utils.sandbox import shutdown_sandbox\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: _settings(\\\"exec-sandbox\\\", sandbox_timeout_seconds=0),\\n        )\\n        monkeypatch.setattr(exec_module, \\\"_RUN_GRACE_SECONDS\\\", 0)\\n        monkeypatch.setattr(exec_module, \\\"_STARTUP_GRACE_SECONDS\\\", 5)\\n        # Cold start (creation sleeps 20ms): succeeds only under startup grace.\\n        assert run_code_in_sandbox(\\\"print('hi')\\\").success\\n        shutdown_sandbox()\\n        # Post-shutdown run is another cold start and must again be\\n        # classified as first execution; with stale steady-state grace the\\n        # 0-second deadline would fail before creation completes.\\n        assert run_code_in_sandbox(\\\"print('hi')\\\").success\\n        assert len(fake_exec_sandbox.instances) == 2\\n\\n    def test_run_during_pending_shutdown_gets_startup_grace(self, monkeypatch, fresh_executor, fake_exec_sandbox):\\n        \\\"\\\"\\\"A run accepted while a shutdown's close is queued must cold-start.\\n\\n        The lifecycle transition (readiness clear + generation bump) happens\\n        synchronously in _shutdown() under the mutex, so even before the\\n        queued close coroutine executes, a newly accepted run classifies\\n        itself as a first execution and gets the startup grace \u2014 with stale\\n        warm state and the steady margin squeezed to zero it would time out\\n        before its fresh scheduler finishes creating.\\n        \\\"\\\"\\\"\\n        import threading\\n        import time\\n\\n        from lfx.utils.sandbox import shutdown_sandbox\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: _settings(\\\"exec-sandbox\\\", sandbox_timeout_seconds=0),\\n        )\\n        monkeypatch.setattr(exec_module, \\\"_RUN_GRACE_SECONDS\\\", 0)\\n        monkeypatch.setattr(exec_module, \\\"_STARTUP_GRACE_SECONDS\\\", 5)\\n\\n        # Warm up (cold, startup grace), leaving readiness True.\\n        assert run_code_in_sandbox(\\\"print('hi')\\\").success\\n        assert fresh_executor._startup_complete\\n\\n        # Freeze the loop so the shutdown's queued close cannot execute.\\n        loop = fresh_executor._loop\\n        release = threading.Event()\\n        frozen = threading.Event()\\n\\n        def freeze():\\n            \\\"\\\"\\\"Signal that the loop is frozen, then block until released.\\\"\\\"\\\"\\n            frozen.set()\\n            release.wait(timeout=5)\\n\\n        loop.call_soon_threadsafe(freeze)\\n        assert frozen.wait(timeout=5)\\n\\n        # Shutdown submits its close (queued behind the freeze) and blocks\\n        # waiting for it; the lifecycle transition must already be visible.\\n        shutdown_thread = threading.Thread(target=shutdown_sandbox, daemon=True)\\n        shutdown_thread.start()\\n        deadline = time.monotonic() + 5\\n        while fresh_executor._startup_complete and time.monotonic() < deadline:\\n            time.sleep(0.001)\\n        assert not fresh_executor._startup_complete, \\\"shutdown did not clear readiness synchronously\\\"\\n\\n        # Accept a run while the close is still pending: it must classify as\\n        # a first execution (startup grace) or the 0-second steady deadline\\n        # fails before its fresh scheduler finishes creating.\\n        results = []\\n\\n        def call():\\n            \\\"\\\"\\\"Run code in the sandbox and collect the result.\\\"\\\"\\\"\\n            results.append(run_code_in_sandbox(\\\"print('hi')\\\"))\\n\\n        run_thread = threading.Thread(target=call, daemon=True)\\n        run_thread.start()\\n        time.sleep(0.02)  # let it submit behind the queued close\\n        release.set()\\n        run_thread.join(timeout=5)\\n        shutdown_thread.join(timeout=5)\\n        assert not run_thread.is_alive()\\n        assert results\\n        assert results[0].success\\n        # Old scheduler closed by the pending shutdown; fresh one created.\\n        assert len(fake_exec_sandbox.instances) == 2\\n        assert fake_exec_sandbox.instances[0].exited\\n        # The post-shutdown run completed on the current epoch: readiness set.\\n        assert fresh_executor._startup_complete\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_fork_hook_replaces_held_mutex(self, monkeypatch, fresh_executor):\\n        \\\"\\\"\\\"The after-fork hook must rebuild a mutex a dead parent thread held.\\n\\n        Simulates the child side of a fork taken while another thread owned\\n        the executor mutex: the inherited lock is locked with no surviving\\n        owner, and without the hook the next run() would block forever before\\n        reaching the dead-loop recovery.\\n        \\\"\\\"\\\"\\n        import threading\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        # Establish live state, then simulate the fork child: the mutex is\\n        # held by a thread that no longer exists.\\n        assert run_code_in_sandbox(\\\"print('hi')\\\").success\\n        inherited_lock = fresh_executor._lock\\n        assert inherited_lock.acquire(blocking=False)  # now \\\"held by a dead thread\\\"\\n        old_generation = fresh_executor._generation\\n\\n        sandbox_module._reinit_backends_after_fork()\\n\\n        assert fresh_executor._lock is not inherited_lock\\n        assert fresh_executor._lock.acquire(blocking=False)\\n        fresh_executor._lock.release()\\n        assert fresh_executor._loop is None\\n        assert fresh_executor._thread is None\\n        assert fresh_executor._scheduler is None\\n        assert fresh_executor._scheduler_lock is None\\n        assert not fresh_executor._startup_complete\\n        assert fresh_executor._generation == old_generation + 1\\n\\n        # A run in the \\\"child\\\" must complete instead of deadlocking on the\\n        # inherited mutex; bound it with a joined thread so a regression\\n        # fails the test rather than hanging the suite.\\n        results = []\\n        worker = threading.Thread(target=lambda: results.append(run_code_in_sandbox(\\\"print('hi')\\\")), daemon=True)\\n        worker.start()\\n        worker.join(timeout=5)\\n        assert not worker.is_alive(), \\\"run() deadlocked on the fork-inherited mutex\\\"\\n        assert results\\n        assert results[0].success\\n\\n    def test_shutdown_is_a_barrier_for_inflight_creation(self, monkeypatch, fresh_executor, fake_exec_sandbox):\\n        \\\"\\\"\\\"A shutdown overlapping Scheduler.__aenter__ must wait and then close it.\\n\\n        Also covers the generation guard: the overlapped run completes against\\n        the closed scheduler and must not mark the next generation's startup\\n        as complete.\\n        \\\"\\\"\\\"\\n        import threading\\n        import time\\n\\n        from lfx.utils.sandbox import shutdown_sandbox\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        results = []\\n\\n        def call():\\n            \\\"\\\"\\\"Run code in the sandbox and collect the result.\\\"\\\"\\\"\\n            results.append(run_code_in_sandbox(\\\"print('hi')\\\"))\\n\\n        worker = threading.Thread(target=call, daemon=True)\\n        worker.start()\\n        # Wait until Scheduler construction started (its __aenter__ is still\\n        # sleeping), then shut down mid-creation.\\n        deadline = time.monotonic() + 5\\n        while not fake_exec_sandbox.instances and time.monotonic() < deadline:\\n            time.sleep(0.001)\\n        assert fake_exec_sandbox.instances, \\\"scheduler creation never started\\\"\\n        shutdown_sandbox()\\n        worker.join(timeout=5)\\n        assert not worker.is_alive()\\n        # The barrier waited for creation and closed the new scheduler.\\n        assert fake_exec_sandbox.instances[0].exited\\n        # The overlapped run belongs to the closed generation: readiness for\\n        # the next scheduler must still be False.\\n        assert not fresh_executor._startup_complete\\n\\n    def test_concurrent_first_calls_create_one_scheduler(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Two racing first executions must share one scheduler (no leaked VM pool).\\n\\n        A barrier releases both threads together and the fake __aenter__ yields\\n        control (asyncio.sleep) so the two coroutines genuinely interleave at\\n        the creation await; without the creation lock this test fails.\\n        \\\"\\\"\\\"\\n        import threading\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        errors = []\\n        start_barrier = threading.Barrier(2)\\n\\n        def call():\\n            \\\"\\\"\\\"Wait at the barrier, then run code in the sandbox, recording any exception.\\\"\\\"\\\"\\n            try:\\n                start_barrier.wait(timeout=5)\\n                run_code_in_sandbox(\\\"print('hi')\\\")\\n            except Exception as e:\\n                errors.append(e)\\n\\n        threads = [threading.Thread(target=call, daemon=True) for _ in range(2)]\\n        for t in threads:\\n            t.start()\\n        for t in threads:\\n            t.join(timeout=5)\\n        assert all(not t.is_alive() for t in threads), \\\"sandbox execution deadlocked\\\"\\n        assert not errors\\n        assert len(fake_exec_sandbox.instances) == 1\\n\\n    def test_scheduler_reused_across_calls(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Verify that a second call reuses the same scheduler instance.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        run_code_in_sandbox(\\\"print('one')\\\")\\n        run_code_in_sandbox(\\\"print('two')\\\")\\n        assert len(fake_exec_sandbox.instances) == 1\\n        assert fake_exec_sandbox.instances[0].entered\\n        assert len(fake_exec_sandbox.instances[0].run_calls) == 2\\n\\n\\nclass TestComponentRouting:\\n    \\\"\\\"\\\"The code-execution components route through the sandbox when enabled.\\\"\\\"\\\"\\n\\n    def test_python_interpreter_sandbox_strips_fences(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Fenced LLM tool-mode code is normalized before reaching the guest.\\\"\\\"\\\"\\n        from lfx.components.utilities.python_repl_core import PythonREPLComponent\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        component = PythonREPLComponent(global_imports=\\\"math\\\", python_code=\\\"```python\\\\nprint('hello from vm')\\\\n```\\\")\\n        data = component.run_python_repl()\\n        assert data.data == {\\\"result\\\": \\\"hello from vm\\\"}\\n        sent = fake_exec_sandbox.instances[-1].run_calls[-1][\\\"code\\\"]\\n        assert \\\"`\\\" not in sent\\n\\n    def test_python_interpreter_sandbox_path(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Verify that the Python Interpreter component routes code through the sandbox.\\\"\\\"\\\"\\n        from lfx.components.utilities.python_repl_core import PythonREPLComponent\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        component = PythonREPLComponent(global_imports=\\\"math\\\", python_code=\\\"print('hello from vm')\\\")\\n        data = component.run_python_repl()\\n        assert data.data == {\\\"result\\\": \\\"hello from vm\\\"}\\n        # Sandbox mode must not exec in-process: the fake scheduler saw the code.\\n        assert fake_exec_sandbox.instances[-1].run_calls\\n\\n    @pytest.mark.usefixtures(\\\"fake_exec_sandbox\\\")\\n    def test_python_interpreter_sandbox_error(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a sandboxed user-code error surfaces in the component's error data.\\\"\\\"\\\"\\n        from lfx.components.utilities.python_repl_core import PythonREPLComponent\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        component = PythonREPLComponent(global_imports=\\\"math\\\", python_code=\\\"FAIL_CODE\\\")\\n        data = component.run_python_repl()\\n        assert \\\"NameError\\\" in data.data[\\\"error\\\"]\\n\\n    def test_python_interpreter_fails_closed_without_package(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that the component raises SandboxUnavailableError when exec-sandbox is missing.\\\"\\\"\\\"\\n        from lfx.components.utilities.python_repl_core import PythonREPLComponent\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        monkeypatch.setitem(sys.modules, \\\"exec_sandbox\\\", None)\\n        component = PythonREPLComponent(global_imports=\\\"math\\\", python_code=\\\"print('hi')\\\")\\n        # Fail closed: the configured-but-unavailable sandbox surfaces as an\\n        # exception, never a silent in-process execution of the code.\\n        with pytest.raises(SandboxUnavailableError):\\n            component.run_python_repl()\\n\\n    def test_python_interpreter_default_stays_in_process(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Backend \\\"none\\\" runs in-process and never touches the sandbox backend.\\n\\n        langchain_experimental is stubbed so this regression test runs in the\\n        isolated lfx CI environment too (it is not installed there); the real\\n        library is exercised by the langflow-base component tests.\\n        \\\"\\\"\\\"\\n        import io\\n        from contextlib import redirect_stdout\\n\\n        from lfx.components.utilities import python_repl_core\\n        from lfx.components.utilities.python_repl_core import PythonREPLComponent\\n\\n        class _FakePythonREPL:\\n            \\\"\\\"\\\"Stand in for langchain_experimental's PythonREPL, exec'ing in-process.\\\"\\\"\\\"\\n\\n            def __init__(self, _globals=None):\\n                \\\"\\\"\\\"Store the globals dict code will execute against.\\\"\\\"\\\"\\n                self._globals = _globals or {}\\n\\n            @staticmethod\\n            def sanitize_input(code):\\n                \\\"\\\"\\\"Return the code stripped of surrounding whitespace.\\\"\\\"\\\"\\n                return code.strip()\\n\\n            def run(self, code):\\n                \\\"\\\"\\\"Execute the code in-process and return captured stdout.\\\"\\\"\\\"\\n                out = io.StringIO()\\n                with redirect_stdout(out):\\n                    exec(code, self._globals)  # noqa: S102\\n                return out.getvalue()\\n\\n        fake_utilities = SimpleNamespace(PythonREPL=_FakePythonREPL)\\n        monkeypatch.setitem(sys.modules, \\\"langchain_experimental\\\", SimpleNamespace(utilities=fake_utilities))\\n        monkeypatch.setitem(sys.modules, \\\"langchain_experimental.utilities\\\", fake_utilities)\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"none\\\"))\\n\\n        # Belt and suspenders: the in-process path must not call the sandbox\\n        # entry point at all, regardless of what the fake backend would do.\\n        def _explode(*_args, **_kwargs):\\n            \\\"\\\"\\\"Raise AssertionError to prove the sandbox entry point is never called.\\\"\\\"\\\"\\n            msg = \\\"run_code_in_sandbox must not be called when backend is none\\\"\\n            raise AssertionError(msg)\\n\\n        monkeypatch.setattr(python_repl_core, \\\"run_code_in_sandbox\\\", _explode)\\n\\n        component = PythonREPLComponent(global_imports=\\\"math\\\", python_code=\\\"print(math.sqrt(4))\\\")\\n        data = component.run_python_repl()\\n        assert data.data == {\\\"result\\\": \\\"2.0\\\"}\\n        # In-process path must never touch the sandbox backend.\\n        assert not fake_exec_sandbox.instances\\n\\n    def test_repl_tool_user_error_returned_as_observation(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"User-code errors come back as the tool observation, not ToolException.\\n\\n        Parity with PythonREPL.run(), which returns error text so agents can\\n        read the traceback and self-correct. Exercises build_tool(), the path\\n        agents actually use (run_model has a pre-existing self.code collision).\\n        \\\"\\\"\\\"\\n        from lfx.components.tools.python_repl import PythonREPLToolComponent\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        component = PythonREPLToolComponent(name=\\\"python_repl\\\", description=\\\"repl\\\", global_imports=\\\"math\\\")\\n        tool = component.build_tool()\\n        observation = tool.run(\\\"FAIL_CODE\\\")\\n        assert \\\"NameError\\\" in observation\\n        assert fake_exec_sandbox.instances[-1].run_calls\\n\\n    def test_repl_tool_sandbox_path(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Verify that the Python REPL tool component routes code through the sandbox.\\\"\\\"\\\"\\n        from lfx.components.tools.python_repl import PythonREPLToolComponent\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        component = PythonREPLToolComponent(name=\\\"python_repl\\\", description=\\\"repl\\\", global_imports=\\\"math\\\")\\n        tool = component.build_tool()\\n        observation = tool.run(\\\"print('hello from vm')\\\")\\n        assert observation == \\\"hello from vm\\\\n\\\"\\n        sent = fake_exec_sandbox.instances[-1].run_calls[-1][\\\"code\\\"]\\n        assert sent.endswith(\\\"print('hello from vm')\\\")\\n\\n    def test_repl_tool_default_stays_in_process(self, monkeypatch, fake_exec_sandbox):\\n        \\\"\\\"\\\"Backend \\\"none\\\": the tool executes in-process and never touches the sandbox.\\n\\n        langchain_experimental is stubbed (see the interpreter counterpart) so\\n        this runs in the isolated lfx CI environment.\\n        \\\"\\\"\\\"\\n        import io\\n        from contextlib import redirect_stdout\\n\\n        from lfx.components.tools import python_repl as python_repl_module\\n        from lfx.components.tools.python_repl import PythonREPLToolComponent\\n\\n        class _FakePythonREPL:\\n            \\\"\\\"\\\"Stand in for langchain_experimental's PythonREPL, exec'ing in-process.\\\"\\\"\\\"\\n\\n            def __init__(self, _globals=None):\\n                \\\"\\\"\\\"Store the globals dict code will execute against.\\\"\\\"\\\"\\n                self._globals = _globals or {}\\n\\n            @staticmethod\\n            def sanitize_input(code):\\n                \\\"\\\"\\\"Return the code stripped of surrounding whitespace.\\\"\\\"\\\"\\n                return code.strip()\\n\\n            def run(self, code):\\n                \\\"\\\"\\\"Execute the code in-process and return captured stdout.\\\"\\\"\\\"\\n                out = io.StringIO()\\n                with redirect_stdout(out):\\n                    exec(code, self._globals)  # noqa: S102\\n                return out.getvalue()\\n\\n        fake_utilities = SimpleNamespace(PythonREPL=_FakePythonREPL)\\n        monkeypatch.setitem(sys.modules, \\\"langchain_experimental\\\", SimpleNamespace(utilities=fake_utilities))\\n        monkeypatch.setitem(sys.modules, \\\"langchain_experimental.utilities\\\", fake_utilities)\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"none\\\"))\\n\\n        def _explode(*_args, **_kwargs):\\n            \\\"\\\"\\\"Raise AssertionError to prove the sandbox entry point is never called.\\\"\\\"\\\"\\n            msg = \\\"run_code_in_sandbox must not be called when backend is none\\\"\\n            raise AssertionError(msg)\\n\\n        monkeypatch.setattr(python_repl_module, \\\"run_code_in_sandbox\\\", _explode)\\n\\n        component = PythonREPLToolComponent(name=\\\"python_repl\\\", description=\\\"repl\\\", global_imports=\\\"math\\\")\\n        tool = component.build_tool()\\n        observation = tool.run(\\\"print(math.sqrt(4))\\\")\\n        assert observation == \\\"2.0\\\\n\\\"\\n        assert not fake_exec_sandbox.instances\\n\\n    def test_repl_tool_fails_closed_without_package(self, monkeypatch):\\n        \\\"\\\"\\\"Configured-but-unavailable backend surfaces as ToolException, never local exec.\\\"\\\"\\\"\\n        from langchain_core.tools import ToolException\\n        from lfx.components.tools.python_repl import PythonREPLToolComponent\\n\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        monkeypatch.setitem(sys.modules, \\\"exec_sandbox\\\", None)\\n        component = PythonREPLToolComponent(name=\\\"python_repl\\\", description=\\\"repl\\\", global_imports=\\\"math\\\")\\n        tool = component.build_tool()\\n        with pytest.raises(ToolException, match=r\\\"exec-sandbox.*not installed\\\"):\\n            tool.run(\\\"print('hi')\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_sandbox_registry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9cefce0aadf244a073e31854002557957f70801b2b1569cb508c9b08f92380a9\",\"content\":\"\\\"\\\"\\\"Tests for sandbox settings, backend registration, and policy enforcement.\\\"\\\"\\\"\\n\\nimport importlib\\nimport importlib.util\\nimport os\\nimport threading\\nimport time\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom lfx.utils import sandbox as sandbox_module\\nfrom lfx.utils.sandbox import SandboxUnavailableError, get_sandbox_backend, is_sandbox_enabled, run_code_in_sandbox\\nfrom lfx.utils.sandbox import base as base_module\\nfrom lfx.utils.sandbox import exec_sandbox as exec_module\\nfrom lfx.utils.sandbox import registry as registry_module\\n\\n\\ndef _settings(backend, **extra):\\n    \\\"\\\"\\\"Return a fake settings service with the given sandbox backend and overrides.\\\"\\\"\\\"\\n    defaults = {\\n        \\\"sandbox_backend\\\": backend,\\n        \\\"sandbox_timeout_seconds\\\": 30,\\n        \\\"sandbox_memory_mb\\\": 192,\\n        \\\"sandbox_allow_network\\\": False,\\n        \\\"sandbox_allowed_domains\\\": [],\\n        \\\"sandbox_allow_software_emulation\\\": False,\\n    }\\n    defaults.update(extra)\\n    return SimpleNamespace(settings=SimpleNamespace(**defaults))\\n\\n\\n@pytest.fixture(autouse=True)\\ndef fresh_executor(monkeypatch):\\n    \\\"\\\"\\\"Give each test its own executor and tear down its loop thread afterwards.\\\"\\\"\\\"\\n    import atexit\\n\\n    executor = exec_module._ExecSandboxExecutor()\\n    monkeypatch.setitem(registry_module._instances, \\\"exec-sandbox\\\", executor)\\n    yield executor\\n    atexit.unregister(executor.shutdown)\\n    executor.shutdown()\\n    loop, thread = executor._loop, executor._thread\\n    if loop is not None and not loop.is_closed():\\n        loop.call_soon_threadsafe(loop.stop)\\n        if thread is not None:\\n            thread.join(timeout=5)\\n        loop.close()\\n\\n\\nclass TestSettingsValidation:\\n    \\\"\\\"\\\"Verify SecuritySettings validates and normalizes sandbox configuration.\\\"\\\"\\\"\\n\\n    def test_unknown_backend_rejected_at_settings_level(self):\\n        \\\"\\\"\\\"Verify that an unrecognized sandbox_backend is rejected at settings construction.\\\"\\\"\\\"\\n        from lfx.services.settings.groups.security import SecuritySettings\\n\\n        with pytest.raises(ValueError, match=\\\"sandbox_backend must be one of\\\"):\\n            SecuritySettings(sandbox_backend=\\\"not-a-backend\\\")\\n\\n    def test_resource_bounds_enforced(self):\\n        \\\"\\\"\\\"Documented ranges are enforced at startup, not deep inside exec-sandbox.\\\"\\\"\\\"\\n        from lfx.services.settings.groups.security import SecuritySettings\\n        from pydantic import ValidationError\\n\\n        with pytest.raises(ValidationError):\\n            SecuritySettings(sandbox_timeout_seconds=0)\\n        with pytest.raises(ValidationError):\\n            SecuritySettings(sandbox_timeout_seconds=301)\\n        with pytest.raises(ValidationError):\\n            SecuritySettings(sandbox_memory_mb=64)\\n\\n    def test_allowed_domains_normalized(self):\\n        \\\"\\\"\\\"Verify that allowed domains are trimmed and blanks are dropped.\\\"\\\"\\\"\\n        from lfx.services.settings.groups.security import SecuritySettings\\n\\n        settings = SecuritySettings(sandbox_allowed_domains=[\\\"api.example.com\\\", \\\" files.pythonhosted.org \\\", \\\"\\\"])\\n        assert settings.sandbox_allowed_domains == [\\\"api.example.com\\\", \\\"files.pythonhosted.org\\\"]\\n\\n    def test_allowed_domains_env_comma_space(self, monkeypatch):\\n        \\\"\\\"\\\"The natural comma-and-space env spelling must reach the backend clean.\\\"\\\"\\\"\\n        from lfx.services.settings.base import Settings\\n\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_ALLOWED_DOMAINS\\\", \\\"api.example.com, files.pythonhosted.org\\\")\\n        settings = Settings()\\n        assert settings.sandbox_allowed_domains == [\\\"api.example.com\\\", \\\"files.pythonhosted.org\\\"]\\n\\n    def test_backend_normalized(self):\\n        \\\"\\\"\\\"Verify that sandbox_backend is lowercased, and defaults to \\\"none\\\".\\\"\\\"\\\"\\n        from lfx.services.settings.groups.security import SecuritySettings\\n\\n        assert SecuritySettings(sandbox_backend=\\\"Exec-Sandbox\\\").sandbox_backend == \\\"exec-sandbox\\\"\\n        assert SecuritySettings().sandbox_backend == \\\"none\\\"\\n\\n\\n_HAS_REAL_EXEC_SANDBOX = importlib.util.find_spec(\\\"exec_sandbox\\\") is not None\\n\\n\\n_LIVE_TESTS_ENABLED = os.getenv(\\\"LANGFLOW_SANDBOX_LIVE_TESTS\\\", \\\"\\\").strip().lower() in {\\\"1\\\", \\\"true\\\", \\\"yes\\\"}\\n\\n\\n@pytest.mark.qemu\\n@pytest.mark.skipif(not _HAS_REAL_EXEC_SANDBOX, reason=\\\"requires the exec-sandbox extra (Python >= 3.12)\\\")\\n@pytest.mark.skipif(\\n    not _LIVE_TESTS_ENABLED,\\n    reason=\\\"live microVM test; set LANGFLOW_SANDBOX_LIVE_TESTS=1 on a host with QEMU 8+ to run\\\",\\n)\\nclass TestLiveExecSandbox:\\n    \\\"\\\"\\\"Opt-in end-to-end test against the real exec-sandbox backend.\\n\\n    Exercises the genuine Scheduler/SchedulerConfig API and a real guest\\n    execution so upstream API changes or scheduler lifecycle regressions are\\n    not hidden by the stubs above. Requires the sandbox extra, QEMU 8+, and\\n    network access for the one-time VM image download.\\n    \\\"\\\"\\\"\\n\\n    def test_real_guest_execution(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that real guest code executes successfully in a live microVM.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        result = run_code_in_sandbox(\\\"print('sandbox ok')\\\", global_imports=\\\"math\\\")\\n        assert result.success\\n        assert result.stdout.strip() == \\\"sandbox ok\\\"\\n\\n    def test_real_guest_user_error(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that a real guest NameError is reported as a failed result.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"exec-sandbox\\\"))\\n        result = run_code_in_sandbox(\\\"this_name_does_not_exist\\\")\\n        assert not result.success\\n        assert \\\"NameError\\\" in result.stderr\\n\\n\\n# ---------------------------------------------------------------------------\\n# Registry and the policy gate\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _StubBackend:\\n    \\\"\\\"\\\"A minimal backend, used to prove the dispatcher decides and not the backend.\\\"\\\"\\\"\\n\\n    name = \\\"stub\\\"\\n\\n    def __init__(self, capabilities=None):\\n        \\\"\\\"\\\"Store the given capabilities, or a fully-permissive default set.\\\"\\\"\\\"\\n        self._capabilities = capabilities or base_module.Capabilities(\\n            isolation=\\\"hardware-virtualized\\\", supports_deny_all_egress=True, supports_domain_allowlist=True\\n        )\\n        self.runs: list[str] = []\\n\\n    def capabilities(self):\\n        \\\"\\\"\\\"Return the stored capabilities.\\\"\\\"\\\"\\n        return self._capabilities\\n\\n    def run(self, code, *, env=None):  # noqa: ARG002\\n        \\\"\\\"\\\"Record the code and return a canned success result.\\\"\\\"\\\"\\n        self.runs.append(code)\\n        return base_module.SandboxResult(stdout=\\\"stub\\\", stderr=\\\"\\\", exit_code=0)\\n\\n    def shutdown(self):\\n        \\\"\\\"\\\"Do nothing; a no-op shutdown for the stub backend.\\\"\\\"\\\"\\n\\n    def reset_after_fork(self):\\n        \\\"\\\"\\\"Do nothing; a no-op fork reset for the stub backend.\\\"\\\"\\\"\\n\\n\\n@pytest.fixture\\ndef stub_backend(monkeypatch):\\n    \\\"\\\"\\\"Register a stub under its own name and return an installer for it.\\\"\\\"\\\"\\n\\n    def _install(capabilities=None):\\n        \\\"\\\"\\\"Register and return a stub backend built with the given capabilities.\\\"\\\"\\\"\\n        backend = _StubBackend(capabilities)\\n        monkeypatch.setitem(registry_module._factories, \\\"stub\\\", lambda: backend)\\n        monkeypatch.setitem(registry_module._instances, \\\"stub\\\", backend)\\n        return backend\\n\\n    return _install\\n\\n\\nclass TestRegistry:\\n    \\\"\\\"\\\"Verify how the sandbox backend registry registers and resolves backends.\\\"\\\"\\\"\\n\\n    def test_in_tree_backends_are_registered(self):\\n        \\\"\\\"\\\"Verify that \\\"none\\\" and \\\"exec-sandbox\\\" are known backends.\\\"\\\"\\\"\\n        names = registry_module.known_sandbox_backends()\\n        assert \\\"none\\\" in names\\n        assert \\\"exec-sandbox\\\" in names\\n\\n    def test_none_cannot_be_claimed_by_a_backend(self):\\n        \\\"\\\"\\\"Verify that registering a backend under the reserved name \\\"none\\\" is refused.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"reserved\\\"):\\n            registry_module.register_sandbox_backend(\\\"none\\\", _StubBackend)\\n\\n    @pytest.mark.parametrize(\\\"name\\\", [\\\"\\\", \\\"   \\\"])\\n    def test_a_backend_name_cannot_be_empty(self, name):\\n        \\\"\\\"\\\"Verify that an empty normalized name is not added to the registry.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"cannot be empty\\\"):\\n            registry_module.register_sandbox_backend(name, _StubBackend)\\n\\n    def test_a_backend_factory_must_be_callable(self):\\n        \\\"\\\"\\\"Verify that malformed plugin objects fail during registration, not first execution.\\\"\\\"\\\"\\n        with pytest.raises(TypeError, match=\\\"callable factory\\\"):\\n            registry_module.register_sandbox_backend(\\\"broken\\\", object())  # type: ignore[arg-type]\\n\\n    def test_a_registered_name_cannot_be_replaced(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that re-registration cannot orphan a live backend or race its factory.\\\"\\\"\\\"\\n        monkeypatch.setitem(registry_module._factories, \\\"taken\\\", _StubBackend)\\n\\n        with pytest.raises(ValueError, match=\\\"already registered\\\"):\\n            registry_module.register_sandbox_backend(\\\"taken\\\", lambda: _StubBackend())\\n\\n        assert registry_module._factories[\\\"taken\\\"] is _StubBackend\\n\\n    def test_a_registered_backend_is_dispatched_to(self, monkeypatch, stub_backend):\\n        \\\"\\\"\\\"Verify that a registered backend receives the run call and its result is returned.\\\"\\\"\\\"\\n        backend = stub_backend()\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"stub\\\"))\\n\\n        result = run_code_in_sandbox(\\\"print(1)\\\")\\n\\n        assert result.stdout == \\\"stub\\\"\\n        assert len(backend.runs) == 1\\n\\n    def test_an_unregistered_backend_fails_closed(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that an unregistered backend name raises SandboxUnavailableError.\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"no-such-backend\\\"))\\n        with pytest.raises(SandboxUnavailableError, match=\\\"Unknown sandbox backend\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n    def test_the_factory_is_called_once(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that resolve_sandbox_backend caches the built instance across calls.\\\"\\\"\\\"\\n        built = []\\n\\n        def factory():\\n            \\\"\\\"\\\"Record a build and return a new stub backend.\\\"\\\"\\\"\\n            built.append(1)\\n            return _StubBackend()\\n\\n        monkeypatch.setitem(registry_module._factories, \\\"counted\\\", factory)\\n        monkeypatch.delitem(registry_module._instances, \\\"counted\\\", raising=False)\\n\\n        first = registry_module.resolve_sandbox_backend(\\\"counted\\\")\\n        second = registry_module.resolve_sandbox_backend(\\\"counted\\\")\\n\\n        assert first is second\\n        assert len(built) == 1\\n\\n    def test_the_settings_validator_reads_the_same_list(self, monkeypatch, stub_backend):\\n        \\\"\\\"\\\"D6: one source of truth, so a backend cannot be accepted by only one of them.\\\"\\\"\\\"\\n        from lfx.services.settings.groups.security import SecuritySettings\\n\\n        stub_backend()\\n        monkeypatch.setattr(registry_module, \\\"_entry_points_loaded\\\", True)\\n        assert SecuritySettings(sandbox_backend=\\\"stub\\\").sandbox_backend == \\\"stub\\\"\\n\\n\\nclass TestPolicyGate:\\n    \\\"\\\"\\\"The backend declares; the dispatcher decides. Every branch fails closed.\\\"\\\"\\\"\\n\\n    def test_software_isolation_is_refused(self, monkeypatch, stub_backend):\\n        \\\"\\\"\\\"Verify that a backend with process-level isolation is refused.\\\"\\\"\\\"\\n        stub_backend(base_module.Capabilities(isolation=\\\"process\\\", supports_deny_all_egress=True))\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"stub\\\"))\\n\\n        with pytest.raises(SandboxUnavailableError, match=\\\"not a hardware-virtualized boundary\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n    def test_a_backend_that_cannot_deny_egress_is_refused(self, monkeypatch, stub_backend):\\n        \\\"\\\"\\\"Verify that a backend unable to deny all egress is refused.\\\"\\\"\\\"\\n        stub_backend(base_module.Capabilities(isolation=\\\"hardware-virtualized\\\", supports_deny_all_egress=False))\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"stub\\\"))\\n\\n        with pytest.raises(SandboxUnavailableError, match=\\\"cannot block all egress\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n    def test_a_backend_without_domain_filtering_is_refused(self, monkeypatch, stub_backend):\\n        \\\"\\\"\\\"Verify that a backend without domain-allowlist support is refused when domains are configured.\\\"\\\"\\\"\\n        stub_backend(\\n            base_module.Capabilities(\\n                isolation=\\\"hardware-virtualized\\\", supports_deny_all_egress=True, supports_domain_allowlist=False\\n            )\\n        )\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: _settings(\\\"stub\\\", sandbox_allow_network=True, sandbox_allowed_domains=[\\\"pypi.org\\\"]),\\n        )\\n\\n        with pytest.raises(SandboxUnavailableError, match=\\\"cannot restrict egress by domain\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n    def test_a_timeout_above_the_backend_cap_is_refused(self, monkeypatch, stub_backend):\\n        \\\"\\\"\\\"Verify that a configured timeout above the backend's max_timeout_seconds is refused.\\\"\\\"\\\"\\n        stub_backend(\\n            base_module.Capabilities(\\n                isolation=\\\"hardware-virtualized\\\",\\n                supports_deny_all_egress=True,\\n                supports_domain_allowlist=True,\\n                max_timeout_seconds=10,\\n            )\\n        )\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: _settings(\\\"stub\\\", sandbox_timeout_seconds=60),\\n        )\\n\\n        with pytest.raises(SandboxUnavailableError, match=\\\"caps one execution at 10s\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n\\nclass _FakeEntryPoint:\\n    \\\"\\\"\\\"Records whether load() ran, which is the thing that imports foreign code.\\\"\\\"\\\"\\n\\n    def __init__(self, name, factory=None, *, explode=False, dist=None):\\n        \\\"\\\"\\\"Store the entry point name, factory, distribution, and whether load() should raise.\\\"\\\"\\\"\\n        self.name = name\\n        self.dist = SimpleNamespace(name=dist) if dist else None\\n        self._factory = factory or (lambda: _StubBackend())\\n        self._explode = explode\\n        self.loaded = False\\n\\n    def load(self):\\n        \\\"\\\"\\\"Mark the entry point as loaded, then return the factory or raise if configured to explode.\\\"\\\"\\\"\\n        self.loaded = True\\n        if self._explode:\\n            msg = \\\"hostile plugin\\\"\\n            raise RuntimeError(msg)\\n        return self._factory\\n\\n\\n@pytest.fixture\\ndef entry_points(monkeypatch):\\n    \\\"\\\"\\\"Serve a canned set of lfx.sandbox_backends entry points to the registry.\\\"\\\"\\\"\\n\\n    def _install(*points):\\n        \\\"\\\"\\\"Register the given entry points as the registry's canned plugin list.\\\"\\\"\\\"\\n        monkeypatch.setattr(registry_module, \\\"_entry_points_loaded\\\", False)\\n        monkeypatch.setattr(\\n            registry_module,\\n            \\\"_factories\\\",\\n            dict(registry_module._factories),\\n        )\\n        monkeypatch.setattr(registry_module, \\\"_instances\\\", dict(registry_module._instances))\\n        import importlib.metadata\\n\\n        monkeypatch.setattr(\\n            importlib.metadata,\\n            \\\"entry_points\\\",\\n            lambda group=None: list(points) if group == registry_module._ENTRY_POINT_GROUP else [],\\n        )\\n        return points\\n\\n    return _install\\n\\n\\nclass TestSandboxBackendPlugins:\\n    \\\"\\\"\\\"Loading a plugin imports foreign code into the security path, so it is opt-in.\\\"\\\"\\\"\\n\\n    def test_nothing_is_imported_without_the_allowlist(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Verify that a plugin absent from the allowlist is never loaded.\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", raising=False)\\n        (point,) = entry_points(_FakeEntryPoint(\\\"vendor\\\"))\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert not point.loaded, \\\"an unlisted plugin must never be imported\\\"\\n        assert \\\"vendor\\\" not in names\\n\\n    def test_an_allowlisted_plugin_is_loaded(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Verify that a plugin named in the allowlist is loaded and registered.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"vendor\\\")\\n        (point,) = entry_points(_FakeEntryPoint(\\\"vendor\\\"))\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert point.loaded\\n        assert \\\"vendor\\\" in names\\n\\n    def test_a_plugin_import_may_read_the_registry_without_recursive_loading(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"A plugin import can call the public registry API without re-entering its own load.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"vendor\\\")\\n        point = _FakeEntryPoint(\\\"vendor\\\")\\n        loads = 0\\n\\n        def load_and_read_registry():\\n            \\\"\\\"\\\"Model plugin import-time code that asks which backends are known.\\\"\\\"\\\"\\n            nonlocal loads\\n            loads += 1\\n            registry_module.known_sandbox_backends()\\n            return lambda: _StubBackend()\\n\\n        point.load = load_and_read_registry\\n        entry_points(point)\\n\\n        assert \\\"vendor\\\" in registry_module.known_sandbox_backends()\\n        assert loads == 1\\n\\n    def test_an_unlisted_plugin_is_skipped_while_a_listed_one_loads(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Verify that only the allowlisted plugin loads when several entry points are present.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"wanted\\\")\\n        wanted, unwanted = entry_points(_FakeEntryPoint(\\\"wanted\\\"), _FakeEntryPoint(\\\"unwanted\\\"))\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert wanted.loaded\\n        assert not unwanted.loaded\\n        assert \\\"wanted\\\" in names\\n        assert \\\"unwanted\\\" not in names\\n\\n    def test_two_distributions_claiming_one_name_are_both_refused(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"The allowlist names a backend, not a distribution, so it cannot choose.\\n\\n        Loading either would be a guess decided by whatever order\\n        importlib.metadata returns, and the old loop imported BOTH and let the\\n        second overwrite the first -- so the code that ran an import was not\\n        even the code that ended up registered.\\n        \\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"vendor\\\")\\n        first, second = entry_points(\\n            _FakeEntryPoint(\\\"vendor\\\", dist=\\\"vendor-a\\\"),\\n            _FakeEntryPoint(\\\"vendor\\\", dist=\\\"vendor-b\\\"),\\n        )\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert not first.loaded, \\\"a contested name must not import anything\\\"\\n        assert not second.loaded, \\\"a contested name must not import anything\\\"\\n        assert \\\"vendor\\\" not in names\\n\\n    def test_a_contested_name_does_not_stop_an_uncontested_one(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Verify that one contested plugin name does not block another that is unambiguous.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"contested,clear\\\")\\n        one, two, clear = entry_points(\\n            _FakeEntryPoint(\\\"contested\\\", dist=\\\"a\\\"),\\n            _FakeEntryPoint(\\\"contested\\\", dist=\\\"b\\\"),\\n            _FakeEntryPoint(\\\"clear\\\", dist=\\\"c\\\"),\\n        )\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert not one.loaded\\n        assert not two.loaded\\n        assert clear.loaded\\n        assert \\\"contested\\\" not in names\\n        assert \\\"clear\\\" in names\\n\\n    def test_a_duplicate_name_nobody_allowlisted_is_still_never_loaded(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Verify that an unlisted contested name is skipped without any import.\\\"\\\"\\\"\\n        monkeypatch.delenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", raising=False)\\n        first, second = entry_points(_FakeEntryPoint(\\\"vendor\\\"), _FakeEntryPoint(\\\"vendor\\\"))\\n\\n        registry_module.known_sandbox_backends()\\n\\n        assert not first.loaded\\n        assert not second.loaded\\n\\n    def test_a_plugin_cannot_take_over_a_builtin_name(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Otherwise an installed package becomes exec-sandbox while settings still say so.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"exec-sandbox\\\")\\n        (point,) = entry_points(_FakeEntryPoint(\\\"exec-sandbox\\\"))\\n\\n        registry_module.known_sandbox_backends()\\n\\n        assert not point.loaded, \\\"a built-in name must be refused before the import\\\"\\n        assert registry_module._factories[\\\"exec-sandbox\\\"] is exec_module._ExecSandboxExecutor\\n\\n    def test_registering_over_a_builtin_is_refused(self):\\n        \\\"\\\"\\\"Verify that registering a plugin under a built-in backend name is refused.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"built-in sandbox backend\\\"):\\n            registry_module.register_sandbox_backend(\\\"exec-sandbox\\\", _StubBackend)\\n\\n    def test_a_plugin_that_fails_to_load_does_not_break_startup(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Verify that one plugin's load failure does not stop a working plugin from loading.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"broken,fine\\\")\\n        broken, fine = entry_points(_FakeEntryPoint(\\\"broken\\\", explode=True), _FakeEntryPoint(\\\"fine\\\"))\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert broken.loaded\\n        assert fine.loaded\\n        assert \\\"broken\\\" not in names\\n        assert \\\"fine\\\" in names\\n\\n    def test_a_missing_plugin_fails_closed_at_dispatch(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"An absent backend refuses the run; it never degrades to in-process exec.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"vendor\\\")\\n        entry_points(_FakeEntryPoint(\\\"vendor\\\", explode=True))\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"vendor\\\"))\\n\\n        with pytest.raises(SandboxUnavailableError, match=\\\"Unknown sandbox backend\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n    def test_the_allowlist_ignores_blanks_and_spacing(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Verify that blank entries and surrounding spaces in the allowlist are ignored.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\" vendor , , \\\")\\n        (point,) = entry_points(_FakeEntryPoint(\\\"vendor\\\"))\\n\\n        assert \\\"vendor\\\" in registry_module.known_sandbox_backends()\\n        assert point.loaded\\n\\n    def test_an_allowlisted_plugin_still_faces_the_policy_gate(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"A declaration is configuration metadata, not evidence of enforcement.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"vendor\\\")\\n        weak = _StubBackend(base_module.Capabilities(isolation=\\\"process\\\", supports_deny_all_egress=True))\\n        weak.name = \\\"vendor\\\"\\n        entry_points(_FakeEntryPoint(\\\"vendor\\\", factory=lambda: weak))\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"vendor\\\"))\\n\\n        with pytest.raises(SandboxUnavailableError, match=\\\"not a hardware-virtualized boundary\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n\\nclass TestRegistryLockDiscipline:\\n    \\\"\\\"\\\"The registry mutex must never be held while foreign code runs, or inherited across a fork.\\\"\\\"\\\"\\n\\n    def test_a_factory_may_call_back_into_the_registry(self, monkeypatch):\\n        \\\"\\\"\\\"A factory that reads the registry must not deadlock on the registry's own lock.\\n\\n        `_lock` is a plain Lock, so building the instance while holding it hangs\\n        the process permanently the first time any factory calls back in. There\\n        is no timeout and no error to observe, so this test asserts on\\n        completion rather than on a value.\\n        \\\"\\\"\\\"\\n        seen = {}\\n\\n        def factory():\\n            \\\"\\\"\\\"Read the registry's known backends, then return a new stub backend.\\\"\\\"\\\"\\n            seen[\\\"names\\\"] = registry_module.known_sandbox_backends()\\n            return _StubBackend()\\n\\n        monkeypatch.setitem(registry_module._factories, \\\"callsback\\\", factory)\\n        monkeypatch.delitem(registry_module._instances, \\\"callsback\\\", raising=False)\\n\\n        done = threading.Event()\\n        result = {}\\n\\n        def build():\\n            \\\"\\\"\\\"Resolve the callsback backend and signal completion.\\\"\\\"\\\"\\n            result[\\\"backend\\\"] = registry_module.resolve_sandbox_backend(\\\"callsback\\\")\\n            done.set()\\n\\n        worker = threading.Thread(target=build, daemon=True)\\n        worker.start()\\n        assert done.wait(timeout=5), \\\"resolve_sandbox_backend deadlocked while calling the factory\\\"\\n        assert \\\"callsback\\\" in seen[\\\"names\\\"]\\n        assert isinstance(result[\\\"backend\\\"], _StubBackend)\\n\\n    def test_a_slow_factory_does_not_block_other_readers(self, monkeypatch):\\n        \\\"\\\"\\\"known_sandbox_backends() runs in the settings validator at startup.\\n\\n        A factory probes hardware or validates control-plane configuration, so\\n        holding a process-wide lock for its duration stalls an unrelated\\n        caller for exactly that long.\\n        \\\"\\\"\\\"\\n        release = threading.Event()\\n\\n        def slow_factory():\\n            \\\"\\\"\\\"Block until released, then return a new stub backend.\\\"\\\"\\\"\\n            release.wait(timeout=5)\\n            return _StubBackend()\\n\\n        monkeypatch.setitem(registry_module._factories, \\\"slow\\\", slow_factory)\\n        monkeypatch.delitem(registry_module._instances, \\\"slow\\\", raising=False)\\n\\n        building = threading.Thread(target=lambda: registry_module.resolve_sandbox_backend(\\\"slow\\\"), daemon=True)\\n        building.start()\\n        time.sleep(0.1)  # let the factory get inside\\n\\n        read = threading.Event()\\n        threading.Thread(target=lambda: (registry_module.known_sandbox_backends(), read.set()), daemon=True).start()\\n        assert read.wait(timeout=2), \\\"known_sandbox_backends() blocked behind a running factory\\\"\\n\\n        release.set()\\n        building.join(timeout=5)\\n\\n    def test_the_registry_mutex_is_replaced_after_a_fork(self):\\n        \\\"\\\"\\\"A lock inherited locked has no owner in the child, so every reader hangs forever.\\n\\n        The fork hook reads the registry before it touches anything else, so\\n        the child would block inside the hook itself, where the surrounding\\n        suppress() cannot help: it is blocked, not raising.\\n        \\\"\\\"\\\"\\n        before = registry_module._lock\\n        registry_module.reset_registry_after_fork()\\n        try:\\n            assert registry_module._lock is not before\\n            assert not registry_module._lock.locked()\\n        finally:\\n            registry_module._lock = before\\n\\n    def test_the_fork_hook_resets_the_registry_before_reading_it(self, monkeypatch):\\n        \\\"\\\"\\\"Order matters: the reset has to happen before live_sandbox_backends() is called.\\\"\\\"\\\"\\n        order = []\\n        monkeypatch.setattr(sandbox_module, \\\"reset_registry_after_fork\\\", lambda: order.append(\\\"reset\\\"))\\n        monkeypatch.setattr(sandbox_module, \\\"live_sandbox_backends\\\", lambda: order.append(\\\"read\\\") or ())\\n\\n        sandbox_module._reinit_backends_after_fork()\\n\\n        assert order == [\\\"reset\\\", \\\"read\\\"]\\n\\n\\nclass TestEntryPointLoadingIsAtomic:\\n    \\\"\\\"\\\"A reader must never observe a half-populated registry.\\\"\\\"\\\"\\n\\n    def test_a_concurrent_reader_waits_for_the_load_to_finish(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Setting the latch before loading lets a second thread read a partial list.\\n\\n        The settings validator consumes exactly that list, so a plugin backend\\n        that is still registering is reported as unknown and startup fails\\n        with \\\"sandbox_backend must be one of\\\".\\n        \\\"\\\"\\\"\\n        inside = threading.Event()\\n        release = threading.Event()\\n\\n        class _SlowEntryPoint:\\n            \\\"\\\"\\\"load() imports third-party code, which is the slow part.\\\"\\\"\\\"\\n\\n            name = \\\"slowplugin\\\"\\n\\n            def load(self):\\n                \\\"\\\"\\\"Signal that loading has started, then block until released.\\\"\\\"\\\"\\n                inside.set()\\n                release.wait(timeout=5)\\n                return _StubBackend\\n\\n        entry_points(_SlowEntryPoint())\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"slowplugin\\\")\\n\\n        threading.Thread(target=registry_module.known_sandbox_backends, daemon=True).start()\\n        assert inside.wait(timeout=5)\\n\\n        observed = {}\\n        reader = threading.Thread(\\n            target=lambda: observed.update(names=registry_module.known_sandbox_backends()), daemon=True\\n        )\\n        reader.start()\\n        reader.join(timeout=0.5)\\n        assert not observed, \\\"a reader returned while the load was still running\\\"\\n\\n        release.set()\\n        reader.join(timeout=5)\\n        assert \\\"slowplugin\\\" in observed[\\\"names\\\"]\\n\\n\\nclass TestPluginRegistrationFailuresAreNotFatal:\\n    \\\"\\\"\\\"A broken plugin must leave Langflow able to start.\\\"\\\"\\\"\\n\\n    def test_a_plugin_named_none_is_refused_instead_of_crashing(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"`none` is reserved, and register_sandbox_backend raises ValueError on it.\\n\\n        Unguarded, that ValueError propagates out of the settings validator and\\n        Langflow does not start -- the opposite of what _load_entry_points\\n        documents.\\n        \\\"\\\"\\\"\\n        entry_points(_FakeEntryPoint(\\\"none\\\", lambda: _StubBackend))\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"none\\\")\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert names.count(\\\"none\\\") == 1\\n        assert registry_module._factories.get(\\\"none\\\") is None\\n\\n    def test_a_plugin_that_is_not_a_factory_is_refused_instead_of_crashing(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"A malformed entry-point value must not break settings validation at startup.\\\"\\\"\\\"\\n        entry_points(_FakeEntryPoint(\\\"broken\\\", object()))\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"broken\\\")\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert \\\"broken\\\" not in names\\n\\n    def test_a_plugin_name_is_lowercased_so_it_can_be_selected(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"The settings validator lowercases sandbox_backend before the membership check.\\n\\n        A name kept in its original case is listed as available and yet can\\n        never be selected, which reports \\\"must be one of\\\" against a list that\\n        looks identical to what the operator configured.\\n        \\\"\\\"\\\"\\n        entry_points(_FakeEntryPoint(\\\"VendorBox\\\", lambda: _StubBackend))\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"VendorBox\\\")\\n\\n        names = registry_module.known_sandbox_backends()\\n\\n        assert \\\"vendorbox\\\" in names\\n        assert \\\"VendorBox\\\" not in names\\n\\n\\nclass TestSettingsUnavailableFailsClosed:\\n    \\\"\\\"\\\"A settings stack that failed to build must not silently disable the sandbox.\\\"\\\"\\\"\\n\\n    def test_the_configured_backend_survives_an_unresolvable_settings_service(self, monkeypatch):\\n        \\\"\\\"\\\"get_settings_service() returns None when settings failed to build.\\n\\n        Answering \\\"none\\\" there sends user code to in-process exec on a\\n        deployment that explicitly asked for a sandbox.\\n        \\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: None)\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND\\\", \\\"exec-sandbox\\\")\\n\\n        assert get_sandbox_backend() == \\\"exec-sandbox\\\"\\n        assert is_sandbox_enabled()\\n\\n    def test_an_unconfigured_deployment_still_reports_none(self, monkeypatch):\\n        \\\"\\\"\\\"Verify that an unresolvable settings service with no env var still reports \\\"none\\\".\\\"\\\"\\\"\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: None)\\n        monkeypatch.delenv(\\\"LANGFLOW_SANDBOX_BACKEND\\\", raising=False)\\n\\n        assert get_sandbox_backend() == \\\"none\\\"\\n\\n\\nclass TestCapabilitiesDefaultsGrantNothing:\\n    \\\"\\\"\\\"An omitted capability must be refused, not trusted.\\\"\\\"\\\"\\n\\n    def test_a_backend_that_never_names_its_isolation_is_refused(self, monkeypatch, stub_backend):\\n        \\\"\\\"\\\"The isolation field is what the strongest gate reads.\\n\\n        Defaulting it to \\\"hardware-virtualized\\\" lets a plugin clear that gate\\n        by saying nothing, which contradicts the rule that a backend never\\n        approves its own policy.\\n        \\\"\\\"\\\"\\n        stub_backend(base_module.Capabilities(supports_deny_all_egress=True, supports_domain_allowlist=True))\\n        monkeypatch.setattr(\\\"lfx.services.deps.get_settings_service\\\", lambda: _settings(\\\"stub\\\"))\\n\\n        with pytest.raises(SandboxUnavailableError, match=\\\"not a hardware-virtualized boundary\\\"):\\n            run_code_in_sandbox(\\\"print(1)\\\")\\n\\n    def test_every_other_default_grants_nothing_either(self):\\n        \\\"\\\"\\\"Verify that every Capabilities field defaults to a value that grants nothing.\\\"\\\"\\\"\\n        caps = base_module.Capabilities()\\n        assert caps.isolation != \\\"hardware-virtualized\\\"\\n        assert not caps.supports_deny_all_egress\\n        assert not caps.supports_domain_allowlist\\n        assert caps.max_timeout_seconds is None\\n\\n\\nclass TestBackendRegistrationIsIdempotent:\\n    \\\"\\\"\\\"Re-executing a backend module must not raise.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"module_name\\\", [\\\"exec_sandbox\\\"])\\n    def test_reimporting_a_builtin_backend_module_does_not_raise(self, module_name):\\n        \\\"\\\"\\\"seal_builtins() has already run, so a second registration is refused by design.\\n\\n        The refusal is correct. Letting it escape as ValueError out of an\\n        import is not.\\n\\n        The reload rebinds every attribute of the module, and the suppressed\\n        re-registration means _factories keeps pointing at the PRE-reload\\n        class. test_a_plugin_cannot_take_over_a_builtin_name asserts exactly\\n        that identity, so the module state is restored here rather than left\\n        for whatever test happens to run next.\\n        \\\"\\\"\\\"\\n        module = importlib.import_module(f\\\"lfx.utils.sandbox.{module_name}\\\")\\n        before = dict(vars(module))\\n\\n        importlib.reload(module)\\n\\n        # Put the original attribute objects back, so the identity the registry\\n        # holds and the identity the module exposes stay the same object.\\n        for name, value in before.items():\\n            setattr(module, name, value)\\n\\n\\nclass TestTheLosingInstanceIsShutDown:\\n    \\\"\\\"\\\"Only one instance is kept, so the other one has to be told to stop.\\\"\\\"\\\"\\n\\n    def test_the_instance_that_loses_the_race_is_shut_down(self, monkeypatch):\\n        \\\"\\\"\\\"The setdefault call keeps the first instance and drops the second.\\n\\n        The dropped one is not in _instances, so live_sandbox_backends() never\\n        returns it and shutdown_sandbox() cannot reach it. A factory that\\n        acquired a loop thread or a client pool would leak it for the process\\n        lifetime.\\n        \\\"\\\"\\\"\\n\\n        class _Closable(_StubBackend):\\n            \\\"\\\"\\\"A stub backend that tracks whether shutdown() ran.\\\"\\\"\\\"\\n\\n            def __init__(self):\\n                \\\"\\\"\\\"Initialize the stub backend and clear the stopped flag.\\\"\\\"\\\"\\n                super().__init__()\\n                self.stopped = False\\n\\n            def shutdown(self):\\n                \\\"\\\"\\\"Mark this instance as stopped.\\\"\\\"\\\"\\n                self.stopped = True\\n\\n        winner = _Closable()\\n        loser = _Closable()\\n\\n        def factory():\\n            \\\"\\\"\\\"Simulate a concurrent winner claiming the slot, then return the loser.\\\"\\\"\\\"\\n            # Stands in for another thread that finished first while this\\n            # factory was still building.\\n            registry_module._instances[\\\"racy\\\"] = winner\\n            return loser\\n\\n        monkeypatch.setitem(registry_module._factories, \\\"racy\\\", factory)\\n        monkeypatch.delitem(registry_module._instances, \\\"racy\\\", raising=False)\\n\\n        assert registry_module.resolve_sandbox_backend(\\\"racy\\\") is winner\\n        assert loser.stopped, \\\"the losing instance was never shut down\\\"\\n        assert not winner.stopped, \\\"the kept instance must not be shut down\\\"\\n\\n    def test_a_shutdown_that_raises_does_not_break_resolution(self, monkeypatch):\\n        \\\"\\\"\\\"Cleaning up the loser is best effort; it must not fail the caller.\\\"\\\"\\\"\\n\\n        class _Angry(_StubBackend):\\n            \\\"\\\"\\\"A stub backend whose shutdown() always raises.\\\"\\\"\\\"\\n\\n            def shutdown(self):\\n                \\\"\\\"\\\"Raise RuntimeError to simulate a broken shutdown.\\\"\\\"\\\"\\n                msg = \\\"no\\\"\\n                raise RuntimeError(msg)\\n\\n        winner = _Angry()\\n\\n        def factory():\\n            \\\"\\\"\\\"Simulate a concurrent winner claiming the slot, then return a new loser.\\\"\\\"\\\"\\n            registry_module._instances[\\\"angry\\\"] = winner\\n            return _Angry()\\n\\n        monkeypatch.setitem(registry_module._factories, \\\"angry\\\", factory)\\n        monkeypatch.delitem(registry_module._instances, \\\"angry\\\", raising=False)\\n\\n        assert registry_module.resolve_sandbox_backend(\\\"angry\\\") is winner\\n\\n\\nclass TestPluginAllowlistMatchingIsCaseInsensitive:\\n    \\\"\\\"\\\"Registration lowercases, so the allowlist match has to as well.\\\"\\\"\\\"\\n\\n    def test_an_operator_may_spell_the_plugin_name_in_any_case(self, monkeypatch, entry_points):\\n        \\\"\\\"\\\"Matching verbatim on one side and normalizing on the other is a silent skip.\\n\\n        The only trace is a debug log, and the startup failure then reports the\\n        backend as unknown.\\n        \\\"\\\"\\\"\\n        entry_points(_FakeEntryPoint(\\\"VendorBox\\\", lambda: _StubBackend))\\n        monkeypatch.setenv(\\\"LANGFLOW_SANDBOX_BACKEND_PLUGINS\\\", \\\"vendorbox\\\")\\n\\n        assert \\\"vendorbox\\\" in registry_module.known_sandbox_backends()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f41724e324cae4c6c0e6b511355be59b93fa9c34c59f8b2b976af7bab3b11a8b\",\"content\":\"from uuid import uuid4\\n\\nimport pytest\\nfrom lfx.utils.schemas import ChatOutputResponse\\nfrom pydantic import ValidationError\\n\\n\\ndef test_chat_output_response_coerces_uuid_session_id():\\n    \\\"\\\"\\\"Model-level coercion should convert UUID session_id to string.\\\"\\\"\\\"\\n    session_id = uuid4()\\n    response = ChatOutputResponse(message=\\\"hello\\\", session_id=session_id, type=\\\"text\\\")\\n    assert response.session_id == str(session_id)\\n\\n\\ndef test_chat_output_response_rejects_non_string_non_uuid_session_id():\\n    \\\"\\\"\\\"Non-string/non-UUID session_id should still fail validation.\\\"\\\"\\\"\\n    with pytest.raises(ValidationError, match=\\\"must be a UUID, string, or None\\\"):\\n        ChatOutputResponse(message=\\\"hello\\\", session_id=123, type=\\\"text\\\")\\n\\n\\ndef test_chat_output_response_accepts_none_session_id():\\n    \\\"\\\"\\\"None session_id should be accepted as-is.\\\"\\\"\\\"\\n    response = ChatOutputResponse(message=\\\"hello\\\", session_id=None, type=\\\"text\\\")\\n    assert response.session_id is None\\n\\n\\ndef test_chat_output_response_accepts_string_session_id():\\n    \\\"\\\"\\\"String session_id should be accepted unchanged.\\\"\\\"\\\"\\n    response = ChatOutputResponse(message=\\\"hello\\\", session_id=\\\"session-123\\\", type=\\\"text\\\")\\n    assert response.session_id == \\\"session-123\\\"\\n\\n\\n@pytest.mark.parametrize(\\\"invalid_session_id\\\", [{}, [], object()])\\ndef test_chat_output_response_rejects_other_invalid_session_id_types(invalid_session_id):\\n    \\\"\\\"\\\"Other non-string/non-UUID session_id types should fail validation.\\\"\\\"\\\"\\n    with pytest.raises(ValidationError, match=\\\"must be a UUID, string, or None\\\"):\\n        ChatOutputResponse(message=\\\"hello\\\", session_id=invalid_session_id, type=\\\"text\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7be3811c81b1b65d9bbc25af7d4fdd39b2af41f88150bc48e4b585a7447f8a6c\",\"content\":\"from lfx.utils.secrets import is_secret_value, secret_value_to_str, unwrap_secret_value\\nfrom pydantic import SecretStr\\nfrom pydantic.v1 import SecretStr as SecretStrV1\\n\\n\\nclass NestedSecret:\\n    def __init__(self, value):\\n        self.value = value\\n\\n    def get_secret_value(self):\\n        return self.value\\n\\n\\ndef test_unwrap_secret_value_supports_pydantic_v1_and_v2():\\n    assert unwrap_secret_value(SecretStr(\\\"v2-secret\\\")) == \\\"v2-secret\\\"\\n    assert unwrap_secret_value(SecretStrV1(\\\"v1-secret\\\")) == \\\"v1-secret\\\"\\n\\n\\ndef test_unwrap_secret_value_unwraps_nested_secret_like_values():\\n    assert unwrap_secret_value(NestedSecret(SecretStr(\\\"nested-secret\\\"))) == \\\"nested-secret\\\"\\n\\n\\ndef test_secret_value_to_str_handles_none_and_stripping():\\n    assert secret_value_to_str(None) is None\\n    assert secret_value_to_str(\\\"  literal  \\\") == \\\"  literal  \\\"\\n    assert secret_value_to_str(\\\"  literal  \\\", strip=True) == \\\"literal\\\"\\n\\n\\ndef test_is_secret_value_uses_secret_protocol():\\n    assert is_secret_value(SecretStr(\\\"secret\\\"))\\n    assert not is_secret_value(\\\"secret\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_ssrf_httpx.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b7c36a1a1ae561a45830d4914a55337be1f311d4a145825ae7b65afb79f37e9a\",\"content\":\"import os\\nimport socket\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport httpcore\\nimport httpx\\nimport pytest\\nfrom lfx.utils.ssrf_httpx import (\\n    ssrf_protected_httpx_client_kwargs_for_url,\\n    ssrf_safe_async_get,\\n    ssrf_safe_async_post,\\n    ssrf_safe_httpx_get,\\n)\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom lfx.utils.ssrf_transport import SSRFProtectedSyncTransport, SSRFProtectedTransport\\n\\n\\nclass TestSSRFSafeHTTPX:\\n    def test_client_kwargs_pin_idn_under_httpx_connect_host(self):\\n        with (\\n            patch(\\n                \\\"lfx.utils.ssrf_httpx.validate_and_resolve_connector_url\\\",\\n                return_value=(\\\"https://ex\u00e4mple.com/v1\\\", [\\\"93.184.216.34\\\"]),\\n            ),\\n            patch(\\\"lfx.utils.ssrf_httpx.is_ssrf_protection_enabled\\\", return_value=True),\\n        ):\\n            sync_kwargs, async_kwargs = ssrf_protected_httpx_client_kwargs_for_url(\\\"https://ex\u00e4mple.com/v1\\\")\\n\\n        sync_transport = sync_kwargs[\\\"transport\\\"]\\n        async_transport = async_kwargs[\\\"transport\\\"]\\n        assert isinstance(sync_transport, SSRFProtectedSyncTransport)\\n        assert isinstance(async_transport, SSRFProtectedTransport)\\n        assert sync_transport.pinned_ips == {\\\"xn--exmple-cua.com\\\": [\\\"93.184.216.34\\\"]}\\n        assert async_transport.pinned_ips == {\\\"xn--exmple-cua.com\\\": [\\\"93.184.216.34\\\"]}\\n\\n    def test_literal_loopback_is_allowed_by_connector_policy(self):\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\": \\\"true\\\",\\n                },\\n                clear=True,\\n            ),\\n            patch(\\\"httpx.Client.get\\\") as mock_get,\\n        ):\\n            ssrf_safe_httpx_get(\\\"http://127.0.0.1:1234/v1/models\\\", timeout=5)\\n\\n        mock_get.assert_called_once()\\n\\n    def test_literal_loopback_is_blocked_when_connector_policy_opts_out(self):\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\": \\\"false\\\",\\n                },\\n                clear=True,\\n            ),\\n            patch(\\\"httpx.Client.get\\\") as mock_get,\\n            pytest.raises(SSRFProtectionError, match=r\\\"127\\\\.0\\\\.0\\\\.1.*blocked\\\"),\\n        ):\\n            ssrf_safe_httpx_get(\\\"http://127.0.0.1:1234/v1/models\\\", timeout=5)\\n\\n        mock_get.assert_not_called()\\n\\n    @pytest.mark.parametrize(\\n        (\\\"request_fn\\\", \\\"client_method\\\"),\\n        [(ssrf_safe_async_get, \\\"get\\\"), (ssrf_safe_async_post, \\\"post\\\")],\\n    )\\n    async def test_async_literal_loopback_is_allowed_by_connector_policy(self, request_fn, client_method):\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\": \\\"true\\\",\\n                },\\n                clear=True,\\n            ),\\n            patch(f\\\"httpx.AsyncClient.{client_method}\\\", new_callable=AsyncMock) as mock_request,\\n        ):\\n            await request_fn(\\\"http://127.0.0.1:1234/v1/models\\\", timeout=5)\\n\\n        mock_request.assert_awaited_once()\\n\\n    @pytest.mark.parametrize(\\n        (\\\"request_fn\\\", \\\"client_method\\\"),\\n        [(ssrf_safe_async_get, \\\"get\\\"), (ssrf_safe_async_post, \\\"post\\\")],\\n    )\\n    async def test_async_literal_loopback_is_blocked_when_connector_policy_opts_out(self, request_fn, client_method):\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_ALLOW_LOOPBACK\\\": \\\"false\\\",\\n                },\\n                clear=True,\\n            ),\\n            patch(f\\\"httpx.AsyncClient.{client_method}\\\", new_callable=AsyncMock) as mock_request,\\n            pytest.raises(SSRFProtectionError, match=r\\\"127\\\\.0\\\\.0\\\\.1.*blocked\\\"),\\n        ):\\n            await request_fn(\\\"http://127.0.0.1:1234/v1/models\\\", timeout=5)\\n\\n        mock_request.assert_not_awaited()\\n\\n    def test_direct_internal_ip_is_blocked(self):\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"httpx.Client.get\\\") as mock_get,\\n            pytest.raises(SSRFProtectionError),\\n        ):\\n            ssrf_safe_httpx_get(\\\"http://169.254.169.254/latest/meta-data/\\\", timeout=5)\\n        mock_get.assert_not_called()\\n\\n    @pytest.mark.parametrize(\\n        \\\"url\\\",\\n        [\\n            \\\"http://127.0.0.1\\\\\\\\@1.1.1.1/\\\",\\n            \\\"http://1.1.1.1\\\\\\\\@127.0.0.1/\\\",\\n        ],\\n    )\\n    def test_ambiguous_authority_is_blocked_before_transport(self, url):\\n        with (\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\",\\n                    \\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\",\\n                },\\n                clear=True,\\n            ),\\n            patch(\\\"httpx.Client.get\\\") as mock_get,\\n            pytest.raises(SSRFProtectionError, match=\\\"backslash\\\"),\\n        ):\\n            ssrf_safe_httpx_get(url, timeout=5)\\n        mock_get.assert_not_called()\\n\\n    def test_sync_dns_pinning_prevents_rebinding_attack(self):\\n        call_count = 0\\n        connected_to_ip = None\\n\\n        def mock_getaddrinfo(_hostname, _port, *_args, **_kwargs):\\n            nonlocal call_count\\n            call_count += 1\\n            if call_count == 1:\\n                return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"8.8.8.8\\\", 0))]\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (\\\"127.0.0.1\\\", 0))]\\n\\n        def mock_connect_tcp(_self, host, port, **_kwargs):\\n            nonlocal connected_to_ip\\n            assert port == 8080\\n            connected_to_ip = host\\n            return httpcore.MockStream(\\n                [\\n                    b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\",\\n                    b\\\"Content-Type: application/json\\\\r\\\\n\\\",\\n                    b\\\"Content-Length: 15\\\\r\\\\n\\\",\\n                    b\\\"\\\\r\\\\n\\\",\\n                    b'{\\\"status\\\":\\\"ok\\\"}',\\n                ]\\n            )\\n\\n        with (\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch.object(httpcore.SyncBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            response = ssrf_safe_httpx_get(\\\"http://rebinding.test:8080/models\\\", timeout=5)\\n\\n        assert response.status_code == 200\\n        assert call_count == 1\\n        assert connected_to_ip == \\\"8.8.8.8\\\"\\n\\n    def test_sync_redirects_are_revalidated_and_strip_cross_origin_credentials(self):\\n        first_url = \\\"https://models.example/v1/models\\\"\\n        second_url = \\\"https://catalog.example/models\\\"\\n        auth = httpx.BasicAuth(\\\"user\\\", \\\"secret\\\")\\n        responses = [\\n            httpx.Response(302, headers={\\\"location\\\": second_url}, request=httpx.Request(\\\"GET\\\", first_url)),\\n            httpx.Response(200, json={\\\"data\\\": []}, request=httpx.Request(\\\"GET\\\", second_url)),\\n        ]\\n\\n        with (\\n            patch(\\n                \\\"lfx.utils.ssrf_httpx.validate_and_resolve_connector_url\\\",\\n                side_effect=lambda url: (url, []),\\n            ) as validate_url,\\n            patch(\\\"httpx.Client.get\\\", side_effect=responses) as get,\\n        ):\\n            response = ssrf_safe_httpx_get(\\n                first_url,\\n                headers=[\\n                    (b\\\"Authorization\\\", b\\\"Bearer secret\\\"),\\n                    (b\\\"Cookie\\\", b\\\"session=header-secret\\\"),\\n                    (b\\\"Proxy-Authorization\\\", b\\\"Basic proxy-secret\\\"),\\n                    (b\\\"User-Agent\\\", b\\\"langflow-test\\\"),\\n                ],\\n                auth=auth,\\n                cookies={\\\"session\\\": \\\"kwarg-secret\\\"},\\n                timeout=5,\\n                follow_redirects=True,\\n            )\\n\\n        assert response.status_code == 200\\n        assert [call.args[0] for call in validate_url.call_args_list] == [first_url, second_url]\\n        first_headers = get.call_args_list[0].kwargs[\\\"headers\\\"]\\n        assert first_headers[\\\"Authorization\\\"] == \\\"Bearer secret\\\"\\n        assert first_headers[\\\"Cookie\\\"] == \\\"session=header-secret\\\"\\n        assert first_headers[\\\"Proxy-Authorization\\\"] == \\\"Basic proxy-secret\\\"\\n        assert get.call_args_list[0].kwargs[\\\"auth\\\"] is auth\\n        assert get.call_args_list[0].kwargs[\\\"cookies\\\"] == {\\\"session\\\": \\\"kwarg-secret\\\"}\\n\\n        second_headers = get.call_args_list[1].kwargs[\\\"headers\\\"]\\n        assert dict(second_headers) == {\\\"user-agent\\\": \\\"langflow-test\\\"}\\n        assert \\\"auth\\\" not in get.call_args_list[1].kwargs\\n        assert \\\"cookies\\\" not in get.call_args_list[1].kwargs\\n        assert all(call.kwargs[\\\"follow_redirects\\\"] is False for call in get.call_args_list)\\n\\n    def test_sync_https_upgrade_preserves_auth_but_not_cookie_or_proxy_credentials(self):\\n        first_url = \\\"http://models.example:80/v1/models\\\"\\n        second_url = \\\"https://models.example:443/v1/models\\\"\\n        auth = httpx.BasicAuth(\\\"user\\\", \\\"secret\\\")\\n        responses = [\\n            httpx.Response(308, headers={\\\"location\\\": second_url}, request=httpx.Request(\\\"GET\\\", first_url)),\\n            httpx.Response(200, json={\\\"data\\\": []}, request=httpx.Request(\\\"GET\\\", second_url)),\\n        ]\\n\\n        with (\\n            patch(\\n                \\\"lfx.utils.ssrf_httpx.validate_and_resolve_connector_url\\\",\\n                side_effect=lambda url: (url, []),\\n            ),\\n            patch(\\\"httpx.Client.get\\\", side_effect=responses) as get,\\n        ):\\n            response = ssrf_safe_httpx_get(\\n                first_url,\\n                headers=[\\n                    (b\\\"Authorization\\\", b\\\"Bearer secret\\\"),\\n                    (b\\\"Cookie\\\", b\\\"session=header-secret\\\"),\\n                    (b\\\"Proxy-Authorization\\\", b\\\"Basic proxy-secret\\\"),\\n                ],\\n                auth=auth,\\n                cookies={\\\"session\\\": \\\"kwarg-secret\\\"},\\n                follow_redirects=True,\\n            )\\n\\n        assert response.status_code == 200\\n        second_call = get.call_args_list[1]\\n        assert second_call.kwargs[\\\"headers\\\"][\\\"Authorization\\\"] == \\\"Bearer secret\\\"\\n        assert \\\"Cookie\\\" not in second_call.kwargs[\\\"headers\\\"]\\n        assert \\\"Proxy-Authorization\\\" not in second_call.kwargs[\\\"headers\\\"]\\n        assert second_call.kwargs[\\\"auth\\\"] is auth\\n        assert \\\"cookies\\\" not in second_call.kwargs\\n\\n    def test_sync_public_redirect_uses_each_hops_validated_pinned_ip(self):\\n        first_url = \\\"http://first.example:8080/models\\\"\\n        second_url = \\\"http://second.example:8081/models\\\"\\n        public_ips = {\\\"first.example\\\": \\\"8.8.8.8\\\", \\\"second.example\\\": \\\"1.1.1.1\\\"}\\n        resolved_hosts: list[str] = []\\n        connections: list[tuple[str, int]] = []\\n\\n        def mock_getaddrinfo(host, _port, *_args, **_kwargs):\\n            resolved_hosts.append(host)\\n            return [(socket.AF_INET, socket.SOCK_STREAM, 6, \\\"\\\", (public_ips[host], 0))]\\n\\n        def mock_connect_tcp(_self, host, port, **_kwargs):\\n            connections.append((host, port))\\n            if host == public_ips[\\\"first.example\\\"]:\\n                body = b\\\"\\\"\\n                status_line = b\\\"HTTP/1.1 302 Found\\\\r\\\\n\\\"\\n                location = f\\\"Location: {second_url}\\\\r\\\\n\\\".encode()\\n            else:\\n                body = b'{\\\"data\\\":[]}'\\n                status_line = b\\\"HTTP/1.1 200 OK\\\\r\\\\n\\\"\\n                location = b\\\"\\\"\\n            response_chunks = [status_line, f\\\"Content-Length: {len(body)}\\\\r\\\\n\\\".encode()]\\n            if location:\\n                response_chunks.append(location)\\n            response_chunks.extend([b\\\"Content-Type: application/json\\\\r\\\\n\\\", b\\\"\\\\r\\\\n\\\", body])\\n            return httpcore.MockStream(response_chunks)\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=mock_getaddrinfo),\\n            patch.object(httpcore.SyncBackend, \\\"connect_tcp\\\", mock_connect_tcp),\\n        ):\\n            response = ssrf_safe_httpx_get(first_url, timeout=5, follow_redirects=True)\\n\\n        assert response.status_code == 200\\n        assert resolved_hosts == [\\\"first.example\\\", \\\"second.example\\\"]\\n        assert connections == [(\\\"8.8.8.8\\\", 8080), (\\\"1.1.1.1\\\", 8081)]\\n\\n\\nclass TestBoundedGet:\\n    \\\"\\\"\\\"``ssrf_safe_httpx_get_bounded`` must refuse an oversized body without buffering it.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _fake_streaming_client(chunk: bytes, chunks_served: list[int], *, status_code: int = 200):\\n        \\\"\\\"\\\"A client whose stream yields ``chunk`` forever, recording how many were consumed.\\\"\\\"\\\"\\n        import contextlib\\n\\n        class _FakeResponse:\\n            status_code = 200\\n            headers: httpx.Headers = httpx.Headers({})\\n\\n            def raise_for_status(self):\\n                return None\\n\\n            def iter_bytes(self):\\n                while True:\\n                    chunks_served[0] += 1\\n                    yield chunk\\n\\n        class _FakeClient:\\n            def __enter__(self):\\n                return self\\n\\n            def __exit__(self, *_exc):\\n                return False\\n\\n            @contextlib.contextmanager\\n            def stream(self, *_args, **_kwargs):\\n                yield _FakeResponse()\\n\\n        _FakeResponse.status_code = status_code\\n        return _FakeClient()\\n\\n    def test_oversized_body_is_refused_before_it_is_fully_read(self):\\n        \\\"\\\"\\\"The transfer stops as soon as the cap is passed, rather than buffering everything.\\n\\n        An endpoint can pass SSRF validation and still answer with an unbounded body, so\\n        measuring the size after a buffered read has already paid the memory cost.\\n        \\\"\\\"\\\"\\n        from lfx.utils import ssrf_httpx\\n\\n        chunk = b\\\"x\\\" * 1024\\n        chunks_served = [0]\\n        max_bytes = 4096\\n\\n        with (\\n            patch.object(\\n                ssrf_httpx,\\n                \\\"_sync_client_for_url\\\",\\n                return_value=self._fake_streaming_client(chunk, chunks_served),\\n            ),\\n            patch.object(\\n                ssrf_httpx, \\\"validate_and_resolve_connector_url\\\", return_value=(\\\"http://ok.test/\\\", [\\\"1.2.3.4\\\"])\\n            ),\\n            pytest.raises(ValueError, match=\\\"exceeds the maximum size\\\"),\\n        ):\\n            ssrf_httpx.ssrf_safe_httpx_get_bounded(\\\"http://ok.test/\\\", max_bytes=max_bytes)\\n\\n        # One chunk past the cap is enough to detect it; an unbounded generator would keep\\n        # going forever if the reader did not stop.\\n        assert chunks_served[0] == (max_bytes // len(chunk)) + 1\\n\\n    def test_body_within_the_cap_is_returned_intact(self):\\n        from lfx.utils import ssrf_httpx\\n\\n        chunk = b\\\"y\\\" * 512\\n\\n        class _BoundedResponse:\\n            status_code = 200\\n            headers = httpx.Headers({})\\n\\n            def raise_for_status(self):\\n                return None\\n\\n            def iter_bytes(self):\\n                yield chunk\\n                yield chunk\\n\\n        import contextlib\\n\\n        class _Client:\\n            def __enter__(self):\\n                return self\\n\\n            def __exit__(self, *_exc):\\n                return False\\n\\n            @contextlib.contextmanager\\n            def stream(self, *_args, **_kwargs):\\n                yield _BoundedResponse()\\n\\n        with (\\n            patch.object(ssrf_httpx, \\\"_sync_client_for_url\\\", return_value=_Client()),\\n            patch.object(\\n                ssrf_httpx, \\\"validate_and_resolve_connector_url\\\", return_value=(\\\"http://ok.test/\\\", [\\\"1.2.3.4\\\"])\\n            ),\\n        ):\\n            body = ssrf_httpx.ssrf_safe_httpx_get_bounded(\\\"http://ok.test/\\\", max_bytes=4096)\\n\\n        assert body == chunk * 2\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_ssrf_protection.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3308219424edc384ff9a8f417f4302ed02fe9e6803e89778fa4eca83fd52f52e\",\"content\":\"\\\"\\\"\\\"Unit tests for SSRF protection utilities.\\\"\\\"\\\"\\n\\nimport os\\nfrom contextlib import contextmanager\\nfrom unittest.mock import MagicMock, patch\\nfrom urllib.parse import urlencode\\n\\nimport pytest\\nfrom lfx.utils.ssrf_protection import (\\n    SSRFProtectionError,\\n    get_allowed_hosts,\\n    is_host_allowed,\\n    is_ip_blocked,\\n    is_ssrf_protection_enabled,\\n    resolve_hostname,\\n    validate_and_resolve_url,\\n    validate_connector_url_for_ssrf,\\n    validate_database_url_for_ssrf,\\n    validate_git_repository_url,\\n    validate_url_for_ssrf,\\n)\\n\\n\\n@contextmanager\\ndef mock_ssrf_settings(*, enabled=False, allowed_hosts=None, restrict_files=False, connector_validation=True):\\n    \\\"\\\"\\\"Context manager to mock SSRF settings.\\\"\\\"\\\"\\n    if allowed_hosts is None:\\n        allowed_hosts = []\\n\\n    mock_settings = MagicMock()\\n    mock_settings.settings.ssrf_protection_enabled = enabled\\n    mock_settings.settings.ssrf_allowed_hosts = allowed_hosts\\n    mock_settings.settings.connector_ssrf_validation_enabled = connector_validation\\n    # Explicit (not a truthy MagicMock) so DB local-file checks behave deterministically.\\n    mock_settings.settings.restrict_local_file_access = restrict_files\\n    # The local-file-restriction read lives in file_path_security (is_local_file_access_restricted,\\n    # reused by the DB/git validators here), so patch its settings source too.\\n    with (\\n        patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\", return_value=mock_settings),\\n        patch(\\\"lfx.utils.file_path_security.get_settings_service\\\", return_value=mock_settings),\\n    ):\\n        yield\\n\\n\\ndef _sqlalchemy_odbc_connect_string(uri: str) -> str:\\n    \\\"\\\"\\\"Return SQLAlchemy's serialized PyODBC connection string when available.\\\"\\\"\\\"\\n    sqlalchemy = pytest.importorskip(\\\"sqlalchemy\\\")\\n    pyodbc = pytest.importorskip(\\\"sqlalchemy.dialects.mssql.pyodbc\\\")\\n    connect_args, _connect_kwargs = pyodbc.MSDialect_pyodbc().create_connect_args(sqlalchemy.engine.make_url(uri))\\n    return connect_args[0]\\n\\n\\nclass TestSSRFProtectionConfiguration:\\n    \\\"\\\"\\\"Test SSRF protection configuration and environment variables.\\\"\\\"\\\"\\n\\n    def test_ssrf_protection_disabled_by_default(self):\\n        \\\"\\\"\\\"Test that SSRF protection is disabled by default (for now).\\\"\\\"\\\"\\n        # TODO: Update this test when default changes to enabled in v2.0\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_protection_enabled = False\\n            mock_get_settings.return_value = mock_settings\\n            assert is_ssrf_protection_enabled() is False\\n\\n    @pytest.mark.parametrize(\\n        (\\\"setting_value\\\", \\\"expected\\\"),\\n        [\\n            (True, True),\\n            (False, False),\\n        ],\\n    )\\n    def test_ssrf_protection_setting(self, setting_value, expected):\\n        \\\"\\\"\\\"Test SSRF protection setting value.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_protection_enabled = setting_value\\n            mock_get_settings.return_value = mock_settings\\n            assert is_ssrf_protection_enabled() == expected\\n\\n    def test_allowed_hosts_empty_by_default(self):\\n        \\\"\\\"\\\"Test that allowed hosts is empty by default.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = []\\n            mock_get_settings.return_value = mock_settings\\n            assert get_allowed_hosts() == []\\n\\n    @pytest.mark.parametrize(\\n        (\\\"setting_value\\\", \\\"expected\\\"),\\n        [\\n            ([], []),\\n            ([\\\"example.com\\\"], [\\\"example.com\\\"]),\\n            ([\\\"example.com\\\", \\\"api.example.com\\\"], [\\\"example.com\\\", \\\"api.example.com\\\"]),\\n            ([\\\"192.168.1.0/24\\\", \\\"10.0.0.5\\\"], [\\\"192.168.1.0/24\\\", \\\"10.0.0.5\\\"]),\\n            ([\\\"  example.com  \\\", \\\"  api.example.com  \\\"], [\\\"example.com\\\", \\\"api.example.com\\\"]),\\n            ([\\\"*.example.com\\\"], [\\\"*.example.com\\\"]),\\n            ([\\\"\\\", \\\"example.com\\\", \\\"  \\\", \\\"api.example.com\\\"], [\\\"example.com\\\", \\\"api.example.com\\\"]),  # Test filtering\\n        ],\\n    )\\n    def test_allowed_hosts_parsing(self, setting_value, expected):\\n        \\\"\\\"\\\"Test allowed hosts list cleaning and filtering.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = setting_value\\n            mock_get_settings.return_value = mock_settings\\n            assert get_allowed_hosts() == expected\\n\\n\\nclass TestIPBlocking:\\n    \\\"\\\"\\\"Test IP address blocking functionality.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        \\\"ip\\\",\\n        [\\n            # Loopback\\n            \\\"127.0.0.1\\\",\\n            \\\"127.0.0.2\\\",\\n            \\\"127.255.255.255\\\",\\n            \\\"::1\\\",\\n            # Private networks (RFC 1918)\\n            \\\"10.0.0.1\\\",\\n            \\\"10.255.255.255\\\",\\n            \\\"172.16.0.1\\\",\\n            \\\"172.31.255.255\\\",\\n            \\\"192.168.0.1\\\",\\n            \\\"192.168.255.255\\\",\\n            # Link-local / Cloud metadata\\n            \\\"169.254.0.1\\\",\\n            \\\"169.254.169.254\\\",  # AWS/GCP/Azure metadata\\n            \\\"169.254.255.255\\\",\\n            # Carrier-grade NAT\\n            \\\"100.64.0.1\\\",\\n            \\\"100.127.255.255\\\",\\n            # Documentation/Test ranges\\n            \\\"192.0.2.1\\\",\\n            \\\"198.51.100.1\\\",\\n            \\\"203.0.113.1\\\",\\n            # Multicast\\n            \\\"224.0.0.1\\\",\\n            \\\"239.255.255.255\\\",\\n            # Reserved\\n            \\\"240.0.0.1\\\",\\n            \\\"255.255.255.254\\\",\\n            # Broadcast\\n            \\\"255.255.255.255\\\",\\n            # IPv6 ranges\\n            \\\"fc00::1\\\",  # ULA\\n            \\\"fe80::1\\\",  # Link-local\\n            \\\"ff00::1\\\",  # Multicast\\n            # IPv6 transition prefixes whose embedded IPv4 is blocked (decoded + re-checked, SSRF)\\n            \\\"2002:a9fe:a9fe::1\\\",  # 6to4 of 169.254.169.254 (metadata)\\n            \\\"2002:0a00:0005::1\\\",  # 6to4 of 10.0.0.5 (RFC 1918)\\n            \\\"64:ff9b::a9fe:a9fe\\\",  # NAT64 of 169.254.169.254 (metadata)\\n            \\\"64:ff9b::169.254.169.254\\\",  # NAT64 dotted form of metadata\\n        ],\\n    )\\n    def test_blocked_ips(self, ip):\\n        \\\"\\\"\\\"Test that private/internal IPs are blocked.\\\"\\\"\\\"\\n        assert is_ip_blocked(ip) is True\\n\\n    @pytest.mark.parametrize(\\n        \\\"ip\\\",\\n        [\\n            # Public IPv4 addresses\\n            \\\"8.8.8.8\\\",  # Google DNS\\n            \\\"1.1.1.1\\\",  # Cloudflare DNS\\n            \\\"93.184.216.34\\\",  # example.com\\n            \\\"151.101.1.140\\\",  # Reddit\\n            \\\"13.107.42.14\\\",  # Microsoft\\n            # Public IPv6 addresses\\n            \\\"2001:4860:4860::8888\\\",  # Google DNS\\n            \\\"2606:4700:4700::1111\\\",  # Cloudflare DNS\\n            # Transition prefixes encoding a *public* IPv4 must stay reachable (IPv6-only / DNS64)\\n            \\\"64:ff9b::8.8.8.8\\\",  # NAT64 of 8.8.8.8 (public)\\n            \\\"64:ff9b::0808:0808\\\",  # NAT64 of 8.8.8.8, hextet form\\n            \\\"2002:0808:0808::1\\\",  # 6to4 of 8.8.8.8 (public)\\n        ],\\n    )\\n    def test_allowed_ips(self, ip):\\n        \\\"\\\"\\\"Test that public IPs are allowed.\\\"\\\"\\\"\\n        assert is_ip_blocked(ip) is False\\n\\n    def test_invalid_ip_is_blocked(self):\\n        \\\"\\\"\\\"Test that invalid IPs are treated as blocked for safety.\\\"\\\"\\\"\\n        assert is_ip_blocked(\\\"not.an.ip.address\\\") is True\\n        assert is_ip_blocked(\\\"999.999.999.999\\\") is True\\n\\n\\nclass TestHostnameAllowlist:\\n    \\\"\\\"\\\"Test hostname allowlist functionality.\\\"\\\"\\\"\\n\\n    def test_exact_hostname_match(self):\\n        \\\"\\\"\\\"Test exact hostname matching in allowlist.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = [\\\"internal.company.local\\\"]\\n            mock_get_settings.return_value = mock_settings\\n            assert is_host_allowed(\\\"internal.company.local\\\") is True\\n            assert is_host_allowed(\\\"other.company.local\\\") is False\\n\\n    def test_wildcard_hostname_match(self):\\n        \\\"\\\"\\\"Test wildcard hostname matching in allowlist.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = [\\\"*.company.local\\\"]\\n            mock_get_settings.return_value = mock_settings\\n            assert is_host_allowed(\\\"api.company.local\\\") is True\\n            assert is_host_allowed(\\\"internal.company.local\\\") is True\\n            assert is_host_allowed(\\\"company.local\\\") is True\\n            assert is_host_allowed(\\\"other.domain.com\\\") is False\\n\\n    def test_exact_ip_match(self):\\n        \\\"\\\"\\\"Test exact IP matching in allowlist.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = [\\\"192.168.1.5\\\"]\\n            mock_get_settings.return_value = mock_settings\\n            assert is_host_allowed(\\\"example.com\\\", \\\"192.168.1.5\\\") is True\\n            assert is_host_allowed(\\\"example.com\\\", \\\"192.168.1.6\\\") is False\\n\\n    def test_cidr_range_match(self):\\n        \\\"\\\"\\\"Test CIDR range matching in allowlist.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = [\\\"192.168.1.0/24\\\", \\\"10.0.0.0/16\\\"]\\n            mock_get_settings.return_value = mock_settings\\n            assert is_host_allowed(\\\"example.com\\\", \\\"192.168.1.5\\\") is True\\n            assert is_host_allowed(\\\"example.com\\\", \\\"192.168.1.255\\\") is True\\n            assert is_host_allowed(\\\"example.com\\\", \\\"192.168.2.5\\\") is False\\n            assert is_host_allowed(\\\"example.com\\\", \\\"10.0.0.1\\\") is True\\n            assert is_host_allowed(\\\"example.com\\\", \\\"10.0.255.255\\\") is True\\n            assert is_host_allowed(\\\"example.com\\\", \\\"10.1.0.1\\\") is False\\n\\n    def test_multiple_allowed_hosts(self):\\n        \\\"\\\"\\\"Test multiple entries in allowlist.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = [\\\"internal.local\\\", \\\"192.168.1.0/24\\\", \\\"*.api.company.com\\\"]\\n            mock_get_settings.return_value = mock_settings\\n            assert is_host_allowed(\\\"internal.local\\\") is True\\n            assert is_host_allowed(\\\"v1.api.company.com\\\") is True\\n            assert is_host_allowed(\\\"example.com\\\", \\\"192.168.1.100\\\") is True\\n            assert is_host_allowed(\\\"other.com\\\", \\\"10.0.0.1\\\") is False\\n\\n    def test_empty_allowlist(self):\\n        \\\"\\\"\\\"Test that empty allowlist returns False.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_allowed_hosts = []\\n            mock_get_settings.return_value = mock_settings\\n            assert is_host_allowed(\\\"example.com\\\") is False\\n            assert is_host_allowed(\\\"example.com\\\", \\\"192.168.1.1\\\") is False\\n\\n\\nclass TestHostnameResolution:\\n    \\\"\\\"\\\"Test DNS hostname resolution.\\\"\\\"\\\"\\n\\n    def test_resolve_public_hostname(self):\\n        \\\"\\\"\\\"Test resolving a public hostname.\\\"\\\"\\\"\\n        # Use a stable public hostname\\n        ips = resolve_hostname(\\\"dns.google\\\")\\n        assert len(ips) > 0\\n        # Should resolve to public IPs (8.8.8.8 or 8.8.4.4)\\n        assert any(not is_ip_blocked(ip) for ip in ips)\\n\\n    def test_resolve_localhost(self):\\n        \\\"\\\"\\\"Test resolving localhost.\\\"\\\"\\\"\\n        ips = resolve_hostname(\\\"localhost\\\")\\n        assert len(ips) > 0\\n        # Should include 127.0.0.1 or ::1\\n        assert any(ip in (\\\"127.0.0.1\\\", \\\"::1\\\") for ip in ips)\\n\\n    def test_resolve_invalid_hostname(self):\\n        \\\"\\\"\\\"Test that invalid hostnames raise SSRFProtectionError.\\\"\\\"\\\"\\n        with pytest.raises(SSRFProtectionError, match=\\\"DNS resolution failed\\\"):\\n            resolve_hostname(\\\"this-hostname-definitely-does-not-exist-12345.invalid\\\")\\n\\n\\nclass TestURLValidation:\\n    \\\"\\\"\\\"Test URL validation for SSRF protection.\\\"\\\"\\\"\\n\\n    def test_protection_disabled_allows_all(self):\\n        \\\"\\\"\\\"Test that when protection is disabled, all URLs are allowed.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_protection_enabled = False\\n            mock_get_settings.return_value = mock_settings\\n            # These should all pass without errors when protection is disabled\\n            validate_url_for_ssrf(\\\"http://127.0.0.1\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"http://169.254.169.254\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"http://192.168.1.1\\\", warn_only=False)\\n\\n    def test_invalid_scheme_blocked(self):\\n        \\\"\\\"\\\"Test that non-http/https schemes are blocked.\\\"\\\"\\\"\\n        with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.ssrf_protection_enabled = True\\n            mock_get_settings.return_value = mock_settings\\n\\n            with pytest.raises(SSRFProtectionError, match=\\\"Invalid URL scheme\\\"):\\n                validate_url_for_ssrf(\\\"ftp://example.com\\\", warn_only=False)\\n\\n            with pytest.raises(SSRFProtectionError, match=\\\"Invalid URL scheme\\\"):\\n                validate_url_for_ssrf(\\\"file:///etc/passwd\\\", warn_only=False)\\n\\n    def test_valid_schemes_allowed(self):\\n        \\\"\\\"\\\"Test that http and https schemes are explicitly allowed.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"93.184.216.34\\\"]  # Public IP (example.com)\\n\\n            # Should not raise - valid schemes with public IPs\\n            validate_url_for_ssrf(\\\"http://example.com\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"https://example.com\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"https://api.example.com/v1\\\", warn_only=False)\\n\\n    def test_dns_pinning_validator_blocks_ambiguous_authority(self):\\n        \\\"\\\"\\\"The DNS-pinning validator applies the same raw-authority validation.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n            pytest.raises(SSRFProtectionError, match=\\\"backslash\\\"),\\n        ):\\n            validate_and_resolve_url(\\\"http://127.0.0.1\\\\\\\\@1.1.1.1/\\\")\\n        mock_resolve.assert_not_called()\\n\\n    def test_direct_ip_blocking(self):\\n        \\\"\\\"\\\"Test blocking of direct IP addresses.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True):\\n            # Loopback\\n            with pytest.raises(SSRFProtectionError, match=\\\"blocked\\\"):\\n                validate_url_for_ssrf(\\\"http://127.0.0.1\\\", warn_only=False)\\n\\n            # Private network\\n            with pytest.raises(SSRFProtectionError, match=\\\"blocked\\\"):\\n                validate_url_for_ssrf(\\\"http://192.168.1.1\\\", warn_only=False)\\n\\n            # Metadata endpoint\\n            with pytest.raises(SSRFProtectionError, match=\\\"blocked\\\"):\\n                validate_url_for_ssrf(\\\"http://169.254.169.254/latest/meta-data/\\\", warn_only=False)\\n\\n    def test_public_ips_allowed(self):\\n        \\\"\\\"\\\"Test that public IP addresses are allowed.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True):\\n            # Should not raise\\n            validate_url_for_ssrf(\\\"http://8.8.8.8\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"http://1.1.1.1\\\", warn_only=False)\\n\\n    def test_public_hostnames_allowed(self):\\n        \\\"\\\"\\\"Test that public hostnames are allowed.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True):\\n            # Test with real DNS to stable Google service\\n            validate_url_for_ssrf(\\\"https://www.google.com\\\", warn_only=False)\\n\\n            # Mock DNS for other domains\\n            with patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve:\\n                mock_resolve.return_value = [\\\"93.184.216.34\\\"]  # Public IP\\n                validate_url_for_ssrf(\\\"https://api.example.com\\\", warn_only=False)\\n                validate_url_for_ssrf(\\\"https://example.com\\\", warn_only=False)\\n\\n    def test_localhost_hostname_blocked(self):\\n        \\\"\\\"\\\"Test that localhost hostname is blocked.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError, match=\\\"blocked IP address\\\"):\\n            validate_url_for_ssrf(\\\"http://localhost:8080\\\", warn_only=False)\\n\\n    def test_allowlist_bypass_hostname(self):\\n        \\\"\\\"\\\"Test that allowlisted hostnames bypass SSRF checks.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True, allowed_hosts=[\\\"internal.company.local\\\"]):\\n            # Should not raise even if it resolves to private IP\\n            # (We can't easily test actual resolution without mocking, but the allowlist check happens first)\\n            validate_url_for_ssrf(\\\"http://internal.company.local\\\", warn_only=False)\\n\\n    def test_allowlist_bypass_ip(self):\\n        \\\"\\\"\\\"Test that allowlisted IPs bypass SSRF checks.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True, allowed_hosts=[\\\"192.168.1.5\\\"]):\\n            # Should not raise\\n            validate_url_for_ssrf(\\\"http://192.168.1.5\\\", warn_only=False)\\n\\n    def test_allowlist_bypass_cidr(self):\\n        \\\"\\\"\\\"Test that IPs in allowlisted CIDR ranges bypass SSRF checks.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True, allowed_hosts=[\\\"192.168.1.0/24\\\"]):\\n            # Should not raise\\n            validate_url_for_ssrf(\\\"http://192.168.1.5\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"http://192.168.1.100\\\", warn_only=False)\\n\\n    def test_warn_only_mode_logs_warnings(self):\\n        \\\"\\\"\\\"Test that warn_only mode logs warnings instead of raising errors.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), patch(\\\"lfx.utils.ssrf_protection.logger\\\") as mock_logger:\\n            # Should not raise, but should log warning\\n            validate_url_for_ssrf(\\\"http://127.0.0.1\\\", warn_only=True)\\n\\n            # Check that warning was logged\\n            mock_logger.warning.assert_called()\\n            assert any(\\\"SSRF Protection Warning\\\" in str(call) for call in mock_logger.warning.call_args_list)\\n\\n    def test_malformed_url_raises_value_error(self):\\n        \\\"\\\"\\\"Test that malformed URLs raise ValueError.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(ValueError, match=\\\"Invalid URL\\\"):\\n            validate_url_for_ssrf(\\\"not a valid url\\\", warn_only=False)\\n\\n    def test_missing_hostname_blocked(self):\\n        \\\"\\\"\\\"Test that URLs without hostname are blocked.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError, match=\\\"valid hostname\\\"):\\n            validate_url_for_ssrf(\\\"http://\\\", warn_only=False)\\n\\n    @pytest.mark.parametrize(\\n        \\\"url\\\",\\n        [\\n            \\\"http://[::1]\\\",  # IPv6 loopback\\n            \\\"http://[::1]:8080/admin\\\",\\n            \\\"http://[fc00::1]\\\",  # IPv6 ULA\\n            \\\"http://[fe80::1]\\\",  # IPv6 link-local\\n        ],\\n    )\\n    def test_ipv6_blocking(self, url):\\n        \\\"\\\"\\\"Test that private IPv6 addresses are blocked.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError, match=\\\"blocked\\\"):\\n            validate_url_for_ssrf(url, warn_only=False)\\n\\n    def test_ipv6_public_allowed(self):\\n        \\\"\\\"\\\"Test that public IPv6 addresses are allowed.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True):\\n            # Should not raise\\n            validate_url_for_ssrf(\\\"http://[2001:4860:4860::8888]\\\", warn_only=False)\\n\\n\\nclass TestIntegrationScenarios:\\n    \\\"\\\"\\\"Test realistic integration scenarios.\\\"\\\"\\\"\\n\\n    def test_aws_metadata_blocked(self):\\n        \\\"\\\"\\\"Test that AWS metadata endpoint is blocked.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError):\\n            validate_url_for_ssrf(\\\"http://169.254.169.254/latest/meta-data/iam/security-credentials/\\\", warn_only=False)\\n\\n    def test_internal_admin_panel_blocked(self):\\n        \\\"\\\"\\\"Test that internal admin panels are blocked.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError):\\n            validate_url_for_ssrf(\\\"http://192.168.1.1/admin\\\", warn_only=False)\\n\\n    def test_legitimate_api_allowed(self):\\n        \\\"\\\"\\\"Test that legitimate external APIs are allowed.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"104.16.132.229\\\"]  # Public IP\\n\\n            # Should all pass - mocked as public IPs\\n            validate_url_for_ssrf(\\\"https://api.openai.com/v1/chat/completions\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"https://api.github.com/repos/langflow-ai/langflow\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"https://www.googleapis.com/auth/cloud-platform\\\", warn_only=False)\\n\\n    def test_docker_internal_networking_requires_allowlist(self):\\n        \\\"\\\"\\\"Test that Docker internal networking requires allowlist configuration.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"172.18.0.2\\\"]  # Docker bridge network IP\\n\\n            # Without allowlist, should be blocked\\n            with pytest.raises(SSRFProtectionError):\\n                validate_url_for_ssrf(\\\"http://database:5432\\\", warn_only=False)\\n\\n        # With allowlist, should be allowed\\n        with (\\n            mock_ssrf_settings(enabled=True, allowed_hosts=[\\\"database\\\", \\\"*.internal.local\\\"]),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"172.18.0.2\\\"]  # Docker bridge network IP\\n\\n            validate_url_for_ssrf(\\\"http://database:5432\\\", warn_only=False)\\n            validate_url_for_ssrf(\\\"http://api.internal.local\\\", warn_only=False)\\n\\n\\nclass TestDatabaseURLValidation:\\n    \\\"\\\"\\\"Tests for validate_database_url_for_ssrf (tenant-controlled DB URIs).\\\"\\\"\\\"\\n\\n    def test_protection_disabled_allows_all(self):\\n        \\\"\\\"\\\"With SSRF off and file access unrestricted, sqlite/local URIs are allowed (OSS default).\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=False, restrict_files=False):\\n            validate_database_url_for_ssrf(\\\"sqlite:////etc/passwd\\\")\\n            validate_database_url_for_ssrf(\\\"postgresql://127.0.0.1:5432/db\\\")\\n\\n    def test_sqlite_allowed_by_default_with_ssrf_on(self):\\n        \\\"\\\"\\\"SQLite must keep working by default (SSRF on, file access not restricted).\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True, restrict_files=False):\\n            validate_database_url_for_ssrf(\\\"sqlite:///./local.db\\\")\\n            validate_database_url_for_ssrf(\\\"sqlite:///:memory:\\\")\\n\\n    @pytest.mark.parametrize(\\n        \\\"uri\\\",\\n        [\\n            \\\"sqlite:////etc/passwd\\\",\\n            \\\"sqlite:///./local.db\\\",\\n            \\\"sqlite+aiosqlite:////var/lib/secret.db\\\",\\n            \\\"duckdb:///data.duckdb\\\",\\n        ],\\n    )\\n    def test_local_file_dialects_blocked_when_restricted(self, uri):\\n        \\\"\\\"\\\"Local-file dialects are rejected when file access is restricted (multi-tenant).\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True, restrict_files=True),\\n            pytest.raises(SSRFProtectionError, match=\\\"local filesystem\\\"),\\n        ):\\n            validate_database_url_for_ssrf(uri)\\n\\n    @pytest.mark.parametrize(\\n        \\\"uri\\\",\\n        [\\n            \\\"postgresql://127.0.0.1:5432/db\\\",\\n            \\\"postgresql://localhost/db\\\",\\n            \\\"mysql://10.0.0.5:3306/db\\\",\\n            \\\"postgresql+psycopg2://user:pass@192.168.1.10/db\\\",  # pragma: allowlist secret\\n        ],\\n    )\\n    def test_internal_hosts_blocked(self, uri):\\n        \\\"\\\"\\\"Network DB URIs pointing at internal/loopback hosts are blocked (SSRF).\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError):\\n            validate_database_url_for_ssrf(uri)\\n\\n    def test_public_host_allowed(self):\\n        \\\"\\\"\\\"A network DB URI to a public host is allowed.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"93.184.216.34\\\"]  # public IP\\n            validate_database_url_for_ssrf(\\\"postgresql://db.example.com:5432/app\\\")\\n\\n    @pytest.mark.parametrize(\\n        \\\"query\\\",\\n        [\\n            \\\"host=127.0.0.1\\\",\\n            \\\"h%6fst=127.0.0.1\\\",\\n            \\\"host=1.1.1.1&host=127.0.0.1\\\",\\n            \\\"hostaddr=127.0.0.1\\\",\\n            \\\"port=15432\\\",\\n            \\\"unix_socket=%2Fvar%2Frun%2Fdatabase.sock\\\",\\n            \\\"odbc_connect=SERVER%3D127.0.0.1\\\",\\n            \\\"dsn=127.0.0.1%3A15432%2Fapp\\\",\\n        ],\\n    )\\n    def test_connection_target_query_overrides_blocked(self, query):\\n        \\\"\\\"\\\"DBAPI query options cannot replace the network target that passed validation.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", return_value=[\\\"93.184.216.34\\\"]),\\n            pytest.raises(SSRFProtectionError, match=\\\"connection target\\\"),\\n        ):\\n            validate_database_url_for_ssrf(f\\\"postgresql://db.example.com:5432/app?{query}\\\")\\n\\n    def test_non_target_query_options_allowed(self):\\n        \\\"\\\"\\\"Connection options that cannot redirect the target remain supported.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", return_value=[\\\"93.184.216.34\\\"]),\\n        ):\\n            validate_database_url_for_ssrf(\\\"postgresql://db.example.com:5432/app?sslmode=require\\\")\\n\\n    @pytest.mark.parametrize(\\\"target_key\\\", [\\\"SERVER\\\", \\\"Address\\\", \\\"Addr\\\", \\\"Network+Address\\\", \\\"Data+Source\\\"])\\n    def test_odbc_connection_target_query_aliases_blocked(self, target_key):\\n        \\\"\\\"\\\"ODBC aliases cannot supersede the server from the validated authority.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", return_value=[\\\"93.184.216.34\\\"]),\\n            pytest.raises(SSRFProtectionError, match=\\\"connection target\\\"),\\n        ):\\n            validate_database_url_for_ssrf(\\n                f\\\"mssql+pyodbc://db.example.com/app?driver=ODBC+Driver+18&{target_key}=127.0.0.1\\\"\\n            )\\n\\n    @pytest.mark.parametrize(\\n        (\\\"scheme\\\", \\\"query_key\\\"),\\n        [\\n            (\\\"mssql+pyodbc\\\", \\\"trace%3Bextra\\\"),\\n            (\\\"mssql+aioodbc\\\", \\\"trace%3Dextra\\\"),\\n            (\\\"mssql\\\", \\\"trace%0Aextra\\\"),\\n            (\\\"mysql+pyodbc\\\", \\\"trace%00extra\\\"),\\n        ],\\n    )\\n    def test_odbc_connection_string_delimiters_and_controls_blocked(self, scheme, query_key):\\n        \\\"\\\"\\\"Unsafe ODBC key characters are rejected before SQLAlchemy serializes them.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", return_value=[\\\"93.184.216.34\\\"]),\\n            pytest.raises(SSRFProtectionError, match=\\\"unsupported ODBC query key\\\"),\\n        ):\\n            validate_database_url_for_ssrf(f\\\"{scheme}://db.example.com/app?driver=ODBC+Driver+18&{query_key}=enabled\\\")\\n\\n    def test_odbc_delimiter_key_matches_sqlalchemy_serialization(self):\\n        \\\"\\\"\\\"Regression mirrors how SQLAlchemy turns an arbitrary key into a new ODBC attribute.\\\"\\\"\\\"\\n        uri = \\\"mssql+pyodbc://db.example.com/app?driver=ODBC+Driver+18&trace%3BServer=alternate.example.com=enabled\\\"\\n\\n        assert \\\";Server=alternate.example.com=\\\" in _sqlalchemy_odbc_connect_string(uri)\\n\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", return_value=[\\\"93.184.216.34\\\"]),\\n            pytest.raises(SSRFProtectionError, match=\\\"unsupported ODBC query key\\\"),\\n        ):\\n            validate_database_url_for_ssrf(uri)\\n\\n    def test_unknown_odbc_driver_attribute_blocked(self):\\n        \\\"\\\"\\\"Driver-defined attributes are denied unless explicitly classified as safe.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            pytest.raises(SSRFProtectionError, match=\\\"unsupported ODBC query key\\\"),\\n        ):\\n            validate_database_url_for_ssrf(\\n                \\\"mssql+pyodbc://db.example.com/app?driver=ODBC+Driver+18&VendorOption=enabled\\\"\\n            )\\n\\n    def test_unknown_odbc_driver_attribute_allowed_when_protections_disabled(self):\\n        \\\"\\\"\\\"The explicit OSS opt-out preserves vendor-specific ODBC attributes.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=False, restrict_files=False):\\n            validate_database_url_for_ssrf(\\n                \\\"mssql+pyodbc://db.example.com/app?driver=ODBC+Driver+18&VendorOption=enabled\\\"\\n            )\\n\\n    def test_odbc_filedsn_target_override_blocked(self):\\n        \\\"\\\"\\\"FILEDSN is serialized as a target source and cannot bypass authority validation.\\\"\\\"\\\"\\n        uri = \\\"mssql+pyodbc://db.example.com/app?driver=ODBC+Driver+18&FILEDSN=%2Ftmp%2Fconnection.dsn\\\"\\n        assert \\\";FILEDSN=/tmp/connection.dsn\\\" in _sqlalchemy_odbc_connect_string(uri)\\n\\n        with (\\n            mock_ssrf_settings(enabled=True, restrict_files=False),\\n            pytest.raises(SSRFProtectionError, match=\\\"connection target\\\"),\\n        ):\\n            validate_database_url_for_ssrf(uri)\\n\\n    def test_odbc_failover_partner_target_override_blocked(self):\\n        \\\"\\\"\\\"Failover_Partner cannot supply an alternate server target.\\\"\\\"\\\"\\n        uri = \\\"mssql+pyodbc://db.example.com/app?driver=ODBC+Driver+18&Failover_Partner=alternate.example.com\\\"\\n        assert \\\";Failover_Partner=alternate.example.com\\\" in _sqlalchemy_odbc_connect_string(uri)\\n\\n        with (\\n            mock_ssrf_settings(enabled=True, restrict_files=False),\\n            pytest.raises(SSRFProtectionError, match=\\\"connection target\\\"),\\n        ):\\n            validate_database_url_for_ssrf(uri)\\n\\n    @pytest.mark.parametrize(\\n        (\\\"query_key\\\", \\\"query_value\\\"),\\n        [\\n            (\\\"SAVEFILE\\\", \\\"/tmp/connection.dsn\\\"),\\n            (\\\"ClientCertificate\\\", \\\"file:/tmp/client.pem\\\"),\\n            (\\\"ClientKey\\\", \\\"file:/tmp/client.key\\\"),\\n            (\\\"QueryLogFile\\\", \\\"/tmp/query.log\\\"),\\n            (\\\"ServerCertificate\\\", \\\"/tmp/server.pem\\\"),\\n            (\\\"StatsLogFile\\\", \\\"/tmp/stats.log\\\"),\\n        ],\\n    )\\n    def test_odbc_local_file_options_blocked_when_restricted(self, query_key, query_value):\\n        \\\"\\\"\\\"ODBC client-file options are blocked even when network SSRF validation is disabled.\\\"\\\"\\\"\\n        query = urlencode({\\\"driver\\\": \\\"ODBC Driver 18\\\", query_key: query_value})\\n        uri = f\\\"mssql+pyodbc://db.example.com/app?{query}\\\"\\n        assert f\\\";{query_key}={query_value}\\\" in _sqlalchemy_odbc_connect_string(uri)\\n\\n        with (\\n            mock_ssrf_settings(enabled=False, restrict_files=True),\\n            pytest.raises(SSRFProtectionError, match=\\\"local filesystem\\\"),\\n        ):\\n            validate_database_url_for_ssrf(uri)\\n\\n    @pytest.mark.parametrize(\\\"certificate\\\", [\\\"sha1:0123456789abcdef\\\", \\\"subject:Langflow Client\\\"])\\n    def test_odbc_certificate_store_selectors_allowed_when_local_files_restricted(self, certificate):\\n        \\\"\\\"\\\"Non-file ClientCertificate forms do not access the local filesystem.\\\"\\\"\\\"\\n        query = urlencode({\\\"driver\\\": \\\"ODBC Driver 18\\\", \\\"ClientCertificate\\\": certificate})\\n        with mock_ssrf_settings(enabled=False, restrict_files=True):\\n            validate_database_url_for_ssrf(f\\\"mssql+pyodbc://db.example.com/app?{query}\\\")\\n\\n    def test_safe_odbc_query_options_allowed(self):\\n        \\\"\\\"\\\"Common ODBC options with safe key names remain supported.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", return_value=[\\\"93.184.216.34\\\"]),\\n        ):\\n            validate_database_url_for_ssrf(\\n                \\\"mssql+pyodbc://db.example.com/app?driver=ODBC+Driver+18\\\"\\n                \\\"&TrustServerCertificate=yes&Application+Name=Langflow\\\"\\n            )\\n\\n    def test_missing_host_blocked(self):\\n        \\\"\\\"\\\"A non-file dialect with no host cannot be validated -> blocked (fail closed).\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError, match=\\\"network host\\\"):\\n            validate_database_url_for_ssrf(\\\"postgresql:///db\\\")\\n\\n\\nclass TestGitRepositoryURLValidation:\\n    \\\"\\\"\\\"Tests for validate_git_repository_url (tenant-controlled git clone URLs).\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        \\\"url\\\",\\n        [\\n            'ext::sh -c \\\"touch /tmp/pwned\\\"',  # remote-helper RCE\\n            \\\"ext::git-upload-pack\\\",\\n            \\\"fd::17/foo\\\",\\n            \\\"::bar\\\",  # default remote helper\\n        ],\\n    )\\n    def test_remote_helper_transports_always_blocked(self, url):\\n        \\\"\\\"\\\"ext::/fd:: remote helpers (RCE) are blocked regardless of toggles.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=False, restrict_files=False),\\n            pytest.raises(SSRFProtectionError, match=\\\"remote-helper\\\"),\\n        ):\\n            validate_git_repository_url(url)\\n\\n    def test_option_injection_always_blocked(self):\\n        \\\"\\\"\\\"A leading '-' is parsed by git as an option => always blocked.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=False, restrict_files=False),\\n            pytest.raises(SSRFProtectionError, match=\\\"option injection\\\"),\\n        ):\\n            validate_git_repository_url(\\\"-upload-pack=evil\\\")\\n\\n    @pytest.mark.parametrize(\\n        \\\"url\\\",\\n        [\\\"file:///etc/passwd\\\", \\\"/etc/passwd\\\", \\\"./local/repo\\\", \\\"~/repo\\\", \\\"../escape\\\"],\\n    )\\n    def test_local_paths_blocked_when_ssrf_on(self, url):\\n        \\\"\\\"\\\"file:// and bare local paths read arbitrary server files -> blocked with SSRF on.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError, match=\\\"local-filesystem\\\"):\\n            validate_git_repository_url(url)\\n\\n    def test_local_paths_allowed_when_all_off(self):\\n        \\\"\\\"\\\"With SSRF off and file access unrestricted, local clones are allowed (single-tenant).\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=False, restrict_files=False):\\n            validate_git_repository_url(\\\"/srv/repos/myrepo\\\")\\n            validate_git_repository_url(\\\"file:///srv/repos/myrepo\\\")\\n\\n    def test_local_paths_blocked_when_file_restricted(self):\\n        \\\"\\\"\\\"Local clones are blocked when local-file access is restricted, even with SSRF off.\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=False, restrict_files=True),\\n            pytest.raises(SSRFProtectionError, match=\\\"local-filesystem\\\"),\\n        ):\\n            validate_git_repository_url(\\\"/etc/passwd\\\")\\n\\n    @pytest.mark.parametrize(\\n        \\\"url\\\",\\n        [\\n            \\\"http://169.254.169.254/latest/meta-data/\\\",\\n            \\\"http://127.0.0.1/x\\\",\\n            \\\"https://10.0.0.5/repo.git\\\",\\n            \\\"git@127.0.0.1:user/repo.git\\\",  # scp-like to internal host\\n        ],\\n    )\\n    def test_internal_hosts_blocked(self, url):\\n        \\\"\\\"\\\"Network clone URLs pointing at internal/metadata hosts are blocked.\\\"\\\"\\\"\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError):\\n            validate_git_repository_url(url)\\n\\n    def test_disallowed_scheme_blocked(self):\\n        with mock_ssrf_settings(enabled=True), pytest.raises(SSRFProtectionError, match=\\\"scheme\\\"):\\n            validate_git_repository_url(\\\"gopher://x/y\\\")\\n\\n    def test_public_https_allowed(self):\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"140.82.112.3\\\"]  # public IP\\n            validate_git_repository_url(\\\"https://github.com/user/repo.git\\\")\\n\\n    def test_public_scp_like_allowed(self):\\n        with (\\n            mock_ssrf_settings(enabled=True),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"140.82.112.3\\\"]\\n            validate_git_repository_url(\\\"git@github.com:user/repo.git\\\")\\n\\n    def test_empty_url_rejected(self):\\n        with mock_ssrf_settings(enabled=True), pytest.raises(ValueError, match=\\\"non-empty\\\"):\\n            validate_git_repository_url(\\\"   \\\")\\n\\n    def test_allowlist_bypass(self):\\n        \\\"\\\"\\\"An allowlisted internal host is permitted (operator opt-in).\\\"\\\"\\\"\\n        with (\\n            mock_ssrf_settings(enabled=True, allowed_hosts=[\\\"database\\\"]),\\n            patch(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\") as mock_resolve,\\n        ):\\n            mock_resolve.return_value = [\\\"172.18.0.2\\\"]\\n            validate_git_repository_url(\\\"https://database/user/repo.git\\\")\\n\\n\\nclass TestConnectorURLValidation:\\n    \\\"\\\"\\\"Tests for validate_connector_url_for_ssrf.\\\"\\\"\\\"\\n\\n    def test_noop_when_connector_validation_explicitly_disabled(self):\\n        \\\"\\\"\\\"With the connector flag off, even a metadata URL is a no-op.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"false\\\"}),\\n            mock_ssrf_settings(enabled=True),\\n        ):\\n            validate_connector_url_for_ssrf(\\\"http://169.254.169.254/latest/meta-data/\\\")\\n\\n    def test_blocks_metadata_by_default(self):\\n        \\\"\\\"\\\"With global SSRF on, a metadata URL is blocked by default.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {}, clear=True),\\n            mock_ssrf_settings(enabled=True),\\n            pytest.raises(SSRFProtectionError),\\n        ):\\n            validate_connector_url_for_ssrf(\\\"http://169.254.169.254/\\\")\\n\\n    def test_blocks_metadata_when_env_enabled(self):\\n        \\\"\\\"\\\"An explicit true env var also blocks metadata URLs.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\"}),\\n            mock_ssrf_settings(enabled=True),\\n            pytest.raises(SSRFProtectionError),\\n        ):\\n            validate_connector_url_for_ssrf(\\\"http://169.254.169.254/\\\")\\n\\n    @pytest.mark.parametrize(\\n        \\\"url\\\",\\n        [\\\"host:19530\\\", \\\"localhost:19530\\\", \\\"10.0.0.5:5432\\\", \\\"my-milvus\\\", \\\"grpc://h:443\\\"],\\n    )\\n    def test_scheme_less_host_gives_clear_error(self, url):\\n        \\\"\\\"\\\"A bare host[:port] / non-http scheme yields a connector-specific message.\\n\\n        Without this, urlparse maps these to a missing/garbage scheme and the shared validator\\n        would surface a confusing \\\"Invalid URL scheme ''\\\" instead.\\n        \\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\"}),\\n            mock_ssrf_settings(enabled=True),\\n            pytest.raises(SSRFProtectionError, match=r\\\"http\\\\(s\\\\) URL with a host\\\"),\\n        ):\\n            validate_connector_url_for_ssrf(url)\\n\\n    def test_scheme_less_noop_when_global_ssrf_off(self):\\n        \\\"\\\"\\\"When global SSRF protection is off, the wrapper stays a no-op even for a bare host.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\": \\\"true\\\"}),\\n            mock_ssrf_settings(enabled=False),\\n        ):\\n            validate_connector_url_for_ssrf(\\\"host:19530\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_ssrf_requests.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8951e9b1de108f79f5cd8c57c6f26bf7817ccb9189998ee7b88b2c911c6ff3c1\",\"content\":\"\\\"\\\"\\\"Unit tests for the SSRF-protected ``requests`` helper (``ssrf_safe_get``).\\\"\\\"\\\"\\n\\nimport ipaddress\\nimport os\\nimport socket\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom lfx.utils.ssrf_requests import ssrf_safe_get\\n\\n\\ndef _resolve_public(host, *_args, **_kwargs):\\n    \\\"\\\"\\\"socket.getaddrinfo stub: hostnames resolve to a public IP, literal IPs to themselves.\\\"\\\"\\\"\\n    try:\\n        ipaddress.ip_address(host)\\n    except ValueError:\\n        ip = \\\"93.184.216.34\\\"  # hostname -> public IP\\n    else:\\n        ip = host  # literal IP -> itself\\n    family = socket.AF_INET6 if \\\":\\\" in ip else socket.AF_INET\\n    return [(family, socket.SOCK_STREAM, 6, \\\"\\\", (ip, 0))]\\n\\n\\ndef _response(status_code=200, *, location=None, body=b\\\"ok\\\"):\\n    \\\"\\\"\\\"Build a minimal mock ``requests.Response``.\\\"\\\"\\\"\\n    response = Mock()\\n    response.status_code = status_code\\n    response.headers = {\\\"Location\\\": location} if location else {}\\n    response.content = body\\n    response.raise_for_status = Mock()\\n    return response\\n\\n\\nclass TestSSRFSafeGet:\\n    def test_direct_internal_ip_is_blocked(self):\\n        \\\"\\\"\\\"A literal internal IP is blocked before any request is made.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n            pytest.raises(SSRFProtectionError),\\n        ):\\n            ssrf_safe_get(\\\"http://127.0.0.1:8080/secret\\\", timeout=5)\\n        mock_get.assert_not_called()\\n\\n    def test_backslash_authority_parser_confusion_is_blocked(self):\\n        \\\"\\\"\\\"A URL interpreted differently by stdlib and Requests is blocked before transport.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n            pytest.raises(SSRFProtectionError, match=\\\"backslash\\\"),\\n        ):\\n            ssrf_safe_get(\\\"http://127.0.0.1\\\\\\\\@1.1.1.1/\\\", timeout=5)\\n        mock_get.assert_not_called()\\n\\n    @pytest.mark.parametrize(\\n        \\\"url\\\",\\n        [\\n            \\\"http://feed.example.com/folder\\\\\\\\item\\\",\\n            \\\"http://feed.example.com/rss?filter=folder\\\\\\\\item\\\",\\n        ],\\n    )\\n    def test_backslash_outside_authority_is_allowed(self, url):\\n        \\\"\\\"\\\"Backslashes outside the authority retain Requests' existing quoting behavior.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", return_value=_response()) as mock_get,\\n        ):\\n            ssrf_safe_get(url, timeout=5)\\n        mock_get.assert_called_once()\\n\\n    def test_cloud_metadata_endpoint_is_blocked(self):\\n        \\\"\\\"\\\"The cloud metadata endpoint is blocked before any request is made.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"requests.get\\\") as mock_get,\\n            pytest.raises(SSRFProtectionError),\\n        ):\\n            ssrf_safe_get(\\\"http://169.254.169.254/latest/meta-data/\\\", timeout=5)\\n        mock_get.assert_not_called()\\n\\n    def test_public_url_returns_response(self):\\n        \\\"\\\"\\\"A public URL passes validation and returns the response.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", return_value=_response(200, body=b\\\"feed\\\")) as mock_get,\\n        ):\\n            response = ssrf_safe_get(\\\"http://feed.example.com/rss\\\", timeout=5)\\n        assert response.status_code == 200\\n        assert mock_get.call_count == 1\\n        # Auto-redirects must be disabled so each hop can be validated.\\n        assert mock_get.call_args.kwargs[\\\"allow_redirects\\\"] is False\\n\\n    def test_redirect_to_internal_is_blocked(self):\\n        \\\"\\\"\\\"A public URL that redirects to an internal address is blocked at the redirect hop.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\n                \\\"requests.get\\\",\\n                return_value=_response(302, location=\\\"http://169.254.169.254/latest/meta-data/\\\"),\\n            ) as mock_get,\\n            pytest.raises(SSRFProtectionError),\\n        ):\\n            ssrf_safe_get(\\\"http://public-redirector.example.com/go\\\", timeout=5)\\n        # Only the first (public) hop was requested; the internal redirect was never followed.\\n        assert mock_get.call_count == 1\\n\\n    def test_public_redirect_chain_is_followed(self):\\n        \\\"\\\"\\\"A chain of public redirects is followed to the final response.\\\"\\\"\\\"\\n        responses = [\\n            _response(302, location=\\\"http://hop2.example.com/b\\\"),\\n            _response(307, location=\\\"http://hop3.example.com/c\\\"),\\n            _response(200, body=b\\\"final\\\"),\\n        ]\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", side_effect=responses) as mock_get,\\n        ):\\n            response = ssrf_safe_get(\\\"http://hop1.example.com/a\\\", timeout=5)\\n        assert response.status_code == 200\\n        assert response.content == b\\\"final\\\"\\n        assert mock_get.call_count == 3\\n\\n    def test_relative_redirect_resolved_against_current_url(self):\\n        \\\"\\\"\\\"A relative redirect Location resolves against the current URL and is followed.\\\"\\\"\\\"\\n        responses = [_response(302, location=\\\"/next\\\"), _response(200, body=b\\\"final\\\")]\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", side_effect=responses) as mock_get,\\n        ):\\n            response = ssrf_safe_get(\\\"http://feed.example.com/a\\\", timeout=5)\\n        assert response.status_code == 200\\n        assert mock_get.call_args_list[1].args[0] == \\\"http://feed.example.com/next\\\"\\n\\n    def test_scheme_change_redirect_is_blocked(self):\\n        \\\"\\\"\\\"A redirect that switches to a non-http(s) scheme is blocked.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", return_value=_response(302, location=\\\"file:///etc/passwd\\\")),\\n            pytest.raises(SSRFProtectionError),\\n        ):\\n            ssrf_safe_get(\\\"http://feed.example.com/a\\\", timeout=5)\\n\\n    def test_too_many_redirects_raises(self):\\n        \\\"\\\"\\\"A redirect loop is bounded and raises instead of looping forever.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\n                \\\"requests.get\\\",\\n                return_value=_response(302, location=\\\"http://loop.example.com/again\\\"),\\n            ) as mock_get,\\n            pytest.raises(SSRFProtectionError, match=\\\"Exceeded the maximum\\\"),\\n        ):\\n            ssrf_safe_get(\\\"http://loop.example.com/start\\\", timeout=5, max_redirects=3)\\n        assert mock_get.call_count == 4  # max_redirects + 1 attempts\\n\\n    def test_protection_disabled_allows_internal(self):\\n        \\\"\\\"\\\"With SSRF protection disabled, no validation is applied (user opted out).\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"false\\\"}),\\n            patch(\\\"requests.get\\\", return_value=_response(200, body=b\\\"internal\\\")) as mock_get,\\n        ):\\n            response = ssrf_safe_get(\\\"http://127.0.0.1:8080/secret\\\", timeout=5)\\n        assert response.status_code == 200\\n        assert mock_get.call_count == 1\\n\\n    def test_cross_host_redirect_strips_credential_headers(self):\\n        \\\"\\\"\\\"Credential-bearing headers are dropped when a redirect crosses to a different host.\\\"\\\"\\\"\\n        responses = [_response(302, location=\\\"http://other.example.com/b\\\"), _response(200, body=b\\\"final\\\")]\\n        headers = {\\n            \\\"Authorization\\\": \\\"Bearer secret-token\\\",\\n            \\\"cookie\\\": \\\"session=abc\\\",  # lowercase: stripping must be case-insensitive\\n            \\\"Proxy-Authorization\\\": \\\"Basic xyz\\\",\\n            \\\"User-Agent\\\": \\\"langflow-test\\\",\\n        }\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", side_effect=responses) as mock_get,\\n        ):\\n            ssrf_safe_get(\\\"http://feed.example.com/a\\\", timeout=5, headers=headers)\\n        # First hop (intended host) keeps all headers; second hop (cross-host) drops the secrets.\\n        assert mock_get.call_args_list[0].kwargs[\\\"headers\\\"] == headers\\n        assert mock_get.call_args_list[1].kwargs[\\\"headers\\\"] == {\\\"User-Agent\\\": \\\"langflow-test\\\"}\\n        # The caller's dict must not be mutated.\\n        assert \\\"Authorization\\\" in headers\\n\\n    def test_same_host_redirect_keeps_headers(self):\\n        \\\"\\\"\\\"Headers (including credentials) are preserved across a same-host redirect.\\\"\\\"\\\"\\n        responses = [_response(302, location=\\\"http://feed.example.com/next\\\"), _response(200, body=b\\\"final\\\")]\\n        headers = {\\\"Authorization\\\": \\\"Bearer secret-token\\\", \\\"User-Agent\\\": \\\"langflow-test\\\"}\\n        with (\\n            patch.dict(os.environ, {\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\": \\\"true\\\"}),\\n            patch(\\\"socket.getaddrinfo\\\", side_effect=_resolve_public),\\n            patch(\\\"requests.get\\\", side_effect=responses) as mock_get,\\n        ):\\n            ssrf_safe_get(\\\"http://feed.example.com/a\\\", timeout=5, headers=headers)\\n        assert mock_get.call_args_list[1].kwargs[\\\"headers\\\"] == headers\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_url_redaction.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cff0bfe0fdad4d8453ee0dc7e186fa92294e3ffd7aee1cdd029f219f86fcfe10\",\"content\":\"\\\"\\\"\\\"A URL on its way into a message must not carry what authenticates to it.\\\"\\\"\\\"\\n\\nfrom lfx.utils.url_redaction import redact_urls_in_text, sanitize_url_for_display\\n\\nCREDENTIAL_URL = \\\"https://user:hunter2@serving.internal/mcp?api_key=secret\\\"\\n\\n\\nclass TestSanitizeUrlForDisplay:\\n    def test_should_drop_userinfo_and_query(self):\\n        assert sanitize_url_for_display(CREDENTIAL_URL) == \\\"https://serving.internal/mcp\\\"\\n\\n    def test_should_keep_a_non_default_port(self):\\n        \\\"\\\"\\\"A target named without its port is a different target.\\\"\\\"\\\"\\n        assert sanitize_url_for_display(\\\"http://user:pw@host.internal:9411/mcp?k=v\\\") == \\\"http://host.internal:9411/mcp\\\"\\n\\n    def test_should_leave_a_value_that_is_not_a_url(self):\\n        assert sanitize_url_for_display(\\\"billing-mcp\\\") == \\\"billing-mcp\\\"\\n\\n    def test_should_leave_a_url_without_a_host(self):\\n        assert sanitize_url_for_display(\\\"file:///tmp/x\\\") == \\\"file:///tmp/x\\\"\\n\\n\\nclass TestRedactUrlsInText:\\n    def test_should_redact_a_url_embedded_in_a_sentence(self):\\n        text = f\\\"Client error '401 Unauthorized' for url '{CREDENTIAL_URL}'\\\"\\n\\n        redacted = redact_urls_in_text(text)\\n\\n        assert \\\"hunter2\\\" not in redacted\\n        assert \\\"secret\\\" not in redacted\\n        assert \\\"serving.internal\\\" in redacted\\n\\n    def test_should_redact_every_url_in_a_multiline_traceback(self):\\n        text = (\\n            \\\"Traceback (most recent call last):\\\\n\\\"\\n            f\\\"  httpx.HTTPStatusError: Client error for url '{CREDENTIAL_URL}'\\\\n\\\"\\n            \\\"  during handling of\\\\n\\\"\\n            \\\"  httpx.ConnectError: failed to reach http://admin:pw@other.internal:8080/x?token=t\\\\n\\\"\\n        )\\n\\n        redacted = redact_urls_in_text(text)\\n\\n        assert \\\"hunter2\\\" not in redacted\\n        assert \\\"secret\\\" not in redacted\\n        assert \\\"pw@\\\" not in redacted\\n        assert \\\"token=t\\\" not in redacted\\n\\n    def test_should_leave_text_without_urls_alone(self):\\n        text = \\\"unhandled errors in a TaskGroup (1 sub-exception)\\\"\\n\\n        assert redact_urls_in_text(text) == text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_util_strings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"622c455515b68afe57a2dce956caed048d957b08367f292e03dd8ef834ec83ff\",\"content\":\"\\\"\\\"\\\"Tests for lfx.utils.util_strings helpers.\\\"\\\"\\\"\\n\\nfrom lfx.utils.util_strings import escape_like_pattern\\n\\n\\ndef test_escape_like_pattern_escapes_wildcards_and_escape_char():\\n    # % and _ are LIKE wildcards; backslash is the escape char and must be doubled first.\\n    assert escape_like_pattern(\\\"a%b_c\\\") == r\\\"a\\\\%b\\\\_c\\\"\\n    assert escape_like_pattern(\\\"100%\\\") == r\\\"100\\\\%\\\"\\n    assert escape_like_pattern(\\\"a_b\\\") == r\\\"a\\\\_b\\\"\\n    # Backslash doubled before the wildcards are escaped (order matters).\\n    assert escape_like_pattern(\\\"a\\\\\\\\b\\\") == \\\"a\\\\\\\\\\\\\\\\b\\\"\\n    assert escape_like_pattern(\\\"\\\\\\\\%\\\") == \\\"\\\\\\\\\\\\\\\\\\\\\\\\%\\\"\\n\\n\\ndef test_escape_like_pattern_leaves_plain_text_unchanged():\\n    assert escape_like_pattern(\\\"plain text 123\\\") == \\\"plain text 123\\\"\\n    assert escape_like_pattern(\\\"\\\") == \\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/utils/test_validate_cloud.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"73362c98616a1a0db7981df351c0c8e65ee08a5c4c07388954e4336833fa1f41\",\"content\":\"\\\"\\\"\\\"Unit tests for the validate_cloud module.\\\"\\\"\\\"\\n\\nimport os\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.utils.validate_cloud import raise_error_if_astra_cloud_disable_component\\n\\n\\nclass TestRaiseErrorIfAstraCloudDisableComponent:\\n    \\\"\\\"\\\"Test suite for the raise_error_if_astra_cloud_disable_component function.\\\"\\\"\\\"\\n\\n    def test_raises_error_when_env_var_is_true(self):\\n        \\\"\\\"\\\"Test that ValueError is raised when ASTRA_CLOUD_DISABLE_COMPONENT is 'true'.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=\\\"Component disabled in cloud\\\"),\\n        ):\\n            raise_error_if_astra_cloud_disable_component(\\\"Component disabled in cloud\\\")\\n\\n    def test_raises_error_when_env_var_is_true_uppercase(self):\\n        \\\"\\\"\\\"Test that ValueError is raised when ASTRA_CLOUD_DISABLE_COMPONENT is 'TRUE'.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"TRUE\\\"}),\\n            pytest.raises(ValueError, match=\\\"Test error message\\\"),\\n        ):\\n            raise_error_if_astra_cloud_disable_component(\\\"Test error message\\\")\\n\\n    def test_raises_error_when_env_var_is_true_with_whitespace(self):\\n        \\\"\\\"\\\"Test that ValueError is raised when ASTRA_CLOUD_DISABLE_COMPONENT is 'true' with whitespace.\\\"\\\"\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"  true  \\\"}),\\n            pytest.raises(ValueError, match=\\\"Whitespace test\\\"),\\n        ):\\n            raise_error_if_astra_cloud_disable_component(\\\"Whitespace test\\\")\\n\\n    def test_no_error_when_env_var_is_false(self):\\n        \\\"\\\"\\\"Test that no error is raised when ASTRA_CLOUD_DISABLE_COMPONENT is 'false'.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"false\\\"}):\\n            # Should not raise any exception\\n            raise_error_if_astra_cloud_disable_component(\\\"This should not be raised\\\")\\n\\n    def test_no_error_when_env_var_is_not_set(self):\\n        \\\"\\\"\\\"Test that no error is raised when ASTRA_CLOUD_DISABLE_COMPONENT is not set.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {}, clear=True):\\n            # Should not raise any exception\\n            raise_error_if_astra_cloud_disable_component(\\\"This should not be raised\\\")\\n\\n    def test_no_error_when_env_var_is_empty_string(self):\\n        \\\"\\\"\\\"Test that no error is raised when ASTRA_CLOUD_DISABLE_COMPONENT is empty.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"\\\"}):\\n            # Should not raise any exception\\n            raise_error_if_astra_cloud_disable_component(\\\"This should not be raised\\\")\\n\\n    def test_no_error_when_env_var_has_invalid_value(self):\\n        \\\"\\\"\\\"Test that no error is raised when ASTRA_CLOUD_DISABLE_COMPONENT has an invalid value.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"invalid\\\"}):\\n            # Should not raise any exception\\n            raise_error_if_astra_cloud_disable_component(\\\"This should not be raised\\\")\\n\\n    def test_no_error_when_env_var_is_1(self):\\n        \\\"\\\"\\\"Test that no error is raised when ASTRA_CLOUD_DISABLE_COMPONENT is '1'.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"1\\\"}):\\n            # Should not raise any exception (only \\\"true\\\" string should trigger)\\n            raise_error_if_astra_cloud_disable_component(\\\"This should not be raised\\\")\\n\\n    def test_custom_error_message(self):\\n        \\\"\\\"\\\"Test that the custom error message is properly raised.\\\"\\\"\\\"\\n        custom_msg = \\\"Custom error: This component cannot be used in Astra Cloud environment\\\"\\n        with (\\n            patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"true\\\"}),\\n            pytest.raises(ValueError, match=custom_msg),\\n        ):\\n            raise_error_if_astra_cloud_disable_component(custom_msg)\\n\\n    def test_error_message_with_special_characters(self):\\n        \\\"\\\"\\\"Test that error messages with special characters are handled correctly.\\\"\\\"\\\"\\n        special_msg = \\\"Error: Component [LocalDB] cannot be used! Contact support@example.com\\\"\\n        with patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": \\\"true\\\"}):\\n            with pytest.raises(ValueError, match=\\\"Error: Component\\\") as exc_info:\\n                raise_error_if_astra_cloud_disable_component(special_msg)\\n            assert str(exc_info.value) == special_msg\\n\\n    @pytest.mark.parametrize(\\n        (\\\"env_value\\\", \\\"should_raise\\\"),\\n        [\\n            (\\\"true\\\", True),\\n            (\\\"TRUE\\\", True),\\n            (\\\"True\\\", True),\\n            (\\\"TrUe\\\", True),\\n            (\\\"  true  \\\", True),\\n            (\\\"\\\\ttrue\\\\n\\\", True),\\n            (\\\"false\\\", False),\\n            (\\\"FALSE\\\", False),\\n            (\\\"False\\\", False),\\n            (\\\"0\\\", False),\\n            (\\\"1\\\", False),\\n            (\\\"yes\\\", False),\\n            (\\\"no\\\", False),\\n            (\\\"\\\", False),\\n            (\\\"random\\\", False),\\n        ],\\n    )\\n    def test_various_env_var_values(self, env_value: str, *, should_raise: bool):\\n        \\\"\\\"\\\"Test the function with various environment variable values.\\\"\\\"\\\"\\n        with patch.dict(os.environ, {\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\": env_value}):\\n            if should_raise:\\n                with pytest.raises(ValueError, match=\\\"Test message\\\"):\\n                    raise_error_if_astra_cloud_disable_component(\\\"Test message\\\")\\n            else:\\n                # Should not raise\\n                raise_error_if_astra_cloud_disable_component(\\\"Test message\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"pyproject.toml\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d2d044de25f84d319338de30299437ee882650e2a998af50f617bfbb5964becf\",\"content\":\"[build-system]\\nrequires = [\\\"hatchling\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[project]\\nname = \\\"llamafactory\\\"\\ndynamic = [\\\"version\\\"]\\ndescription = \\\"Unified Efficient Fine-Tuning of 100+ LLMs\\\"\\nreadme = \\\"README.md\\\"\\nlicense = \\\"Apache-2.0\\\"\\nrequires-python = \\\">=3.11.0\\\"\\nauthors = [\\n    { name = \\\"hiyouga\\\", email = \\\"hiyouga@buaa.edu.cn\\\" }\\n]\\nkeywords = [\\n    \\\"AI\\\",\\n    \\\"LLM\\\",\\n    \\\"GPT\\\",\\n    \\\"ChatGPT\\\",\\n    \\\"Llama\\\",\\n    \\\"Transformer\\\",\\n    \\\"DeepSeek\\\",\\n    \\\"Pytorch\\\"\\n]\\nclassifiers = [\\n    \\\"Development Status :: 4 - Beta\\\",\\n    \\\"Intended Audience :: Developers\\\",\\n    \\\"Intended Audience :: Education\\\",\\n    \\\"Intended Audience :: Science/Research\\\",\\n    \\\"License :: OSI Approved :: Apache Software License\\\",\\n    \\\"Operating System :: OS Independent\\\",\\n    \\\"Programming Language :: Python :: 3\\\",\\n    \\\"Programming Language :: Python :: 3.11\\\",\\n    \\\"Programming Language :: Python :: 3.12\\\",\\n    \\\"Programming Language :: Python :: 3.13\\\",\\n    \\\"Topic :: Scientific/Engineering :: Artificial Intelligence\\\"\\n]\\ndependencies = [\\n    # core deps\\n    \\\"torch>=2.4.0\\\",\\n    \\\"torchvision>=0.19.0\\\",\\n    \\\"torchaudio>=2.4.0\\\",\\n    \\\"transformers>=4.55.0,<=5.8.0,!=4.57.0,!=5.6.0\\\",\\n    \\\"datasets>=2.16.0,<=4.0.0\\\",\\n    \\\"accelerate>=1.3.0,<=1.11.0\\\",\\n    \\\"peft>=0.18.0,<=0.18.1\\\",\\n    \\\"trl>=0.18.0,<=0.24.0\\\",\\n    \\\"torchdata>=0.10.0,<=0.11.0\\\",\\n    # gui\\n    \\\"gradio>=4.38.0,<=5.50.0\\\",\\n    \\\"matplotlib>=3.7.0\\\",\\n    \\\"tyro<0.9.0\\\",\\n    # ops\\n    \\\"einops\\\",\\n    \\\"numpy\\\",\\n    \\\"pandas\\\",\\n    \\\"scipy\\\",\\n    # model and tokenizer\\n    \\\"sentencepiece\\\",\\n    \\\"tiktoken\\\",\\n    \\\"modelscope\\\",\\n    \\\"hf-transfer\\\",\\n    \\\"safetensors\\\",\\n    # python\\n    \\\"av>=10.0.0,<=16.0.0\\\",\\n    \\\"fire\\\",\\n    \\\"omegaconf\\\",\\n    \\\"packaging\\\",\\n    \\\"protobuf\\\",\\n    \\\"pyyaml\\\",\\n    \\\"pydantic\\\",\\n    # api\\n    \\\"uvicorn\\\",\\n    \\\"fastapi\\\",\\n    \\\"sse-starlette\\\",\\n]\\n\\n[project.scripts]\\nllamafactory-cli = \\\"llamafactory.cli:main\\\"\\nlmf = \\\"llamafactory.cli:main\\\"\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/hiyouga/LLaMA-Factory\\\"\\nRepository = \\\"https://github.com/hiyouga/LLaMA-Factory\\\"\\n\\n[tool.hatch.build.targets.wheel]\\npackages = [\\\"src/llamafactory\\\"]\\n\\n[tool.hatch.version]\\npath = \\\"src/llamafactory/extras/env.py\\\"\\npattern = \\\"VERSION = \\\\\\\"(?P<version>[^\\\\\\\"]+)\\\\\\\"\\\"\\n\\n[tool.ruff]\\ntarget-version = \\\"py311\\\"\\nline-length = 119\\nindent-width = 4\\n\\n[tool.ruff.lint]\\nignore = [\\n    \\\"C408\\\",  # collection\\n    \\\"C901\\\",  # complex\\n    \\\"E501\\\",  # line too long\\n    \\\"E731\\\",  # lambda function\\n    \\\"E741\\\",  # ambiguous var name\\n    \\\"UP007\\\", # no upgrade union\\n    \\\"UP045\\\", # no upgrade optional\\n    \\\"D100\\\",  # no doc public module\\n    \\\"D101\\\",  # no doc public class\\n    \\\"D102\\\",  # no doc public method\\n    \\\"D103\\\",  # no doc public function\\n    \\\"D104\\\",  # no doc public package\\n    \\\"D105\\\",  # no doc magic method\\n    \\\"D107\\\",  # no doc __init__\\n]\\nselect = [\\n    \\\"C\\\",      # complexity\\n    \\\"E\\\",      # error\\n    \\\"F\\\",      # pyflakes\\n    \\\"I\\\",      # isort\\n    \\\"W\\\",      # warning\\n    \\\"UP\\\",     # pyupgrade\\n    \\\"D\\\",      # pydocstyle\\n    \\\"PT009\\\",  # pytest assert\\n    \\\"RUF022\\\", # sort __all__\\n]\\n\\n[tool.ruff.lint.isort]\\nlines-after-imports = 2\\nknown-first-party = [\\\"llamafactory\\\"]\\nknown-third-party = [\\n    \\\"accelerate\\\",\\n    \\\"datasets\\\",\\n    \\\"gradio\\\",\\n    \\\"numpy\\\",\\n    \\\"peft\\\",\\n    \\\"torch\\\",\\n    \\\"transformers\\\",\\n    \\\"trl\\\",\\n]\\n\\n[tool.ruff.lint.pydocstyle]\\nconvention = \\\"google\\\"\\n\\n[tool.ruff.format]\\nquote-style = \\\"double\\\"\\nindent-style = \\\"space\\\"\\ndocstring-code-format = true\\nskip-magic-trailing-comma = false\\nline-ending = \\\"auto\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/api.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0b71f05f83c8f33a5ee63be1587df5829196ce312929e838a927b75640197a3a\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\n\\nimport uvicorn\\n\\nfrom llamafactory.api.app import create_app\\nfrom llamafactory.chat import ChatModel\\n\\n\\ndef main():\\n    chat_model = ChatModel()\\n    app = create_app(chat_model)\\n    api_host = os.getenv(\\\"API_HOST\\\", \\\"0.0.0.0\\\")\\n    api_port = int(os.getenv(\\\"API_PORT\\\", \\\"8000\\\"))\\n    print(f\\\"Visit http://localhost:{api_port}/docs for API document.\\\")\\n    uvicorn.run(app, host=api_host, port=api_port)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ac3cedbab920eb4ff39a0aa78ebc614a55d7afac85278396ebbc124f857b3ea6\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nr\\\"\\\"\\\"Efficient fine-tuning of large language models.\\n\\nLevel:\\n  api, webui > chat, eval, train > data, model > hparams > extras\\n\\nDisable version checking: DISABLE_VERSION_CHECK=1\\nEnable VRAM recording: RECORD_VRAM=1\\nForce using torchrun: FORCE_TORCHRUN=1\\nSet logging verbosity: LLAMAFACTORY_VERBOSITY=WARN\\nUse modelscope: USE_MODELSCOPE_HUB=1\\nUse openmind: USE_OPENMIND_HUB=1\\n\\\"\\\"\\\"\\n\\nfrom .extras.env import VERSION\\n\\n\\n__version__ = VERSION\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/api/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/api/app.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"99369f350ca92c3efd87625505fc17bd185b6eafbd6c28b9551126a28197f6a3\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport asyncio\\nimport os\\nfrom contextlib import asynccontextmanager\\nfrom functools import partial\\nfrom typing import Annotated\\n\\nfrom ..chat import ChatModel\\nfrom ..extras.constants import EngineName\\nfrom ..extras.misc import torch_gc\\nfrom ..extras.packages import is_fastapi_available, is_starlette_available, is_uvicorn_available\\nfrom .chat import (\\n    create_chat_completion_response,\\n    create_score_evaluation_response,\\n    create_stream_chat_completion_response,\\n)\\nfrom .protocol import (\\n    ChatCompletionRequest,\\n    ChatCompletionResponse,\\n    ModelCard,\\n    ModelList,\\n    ScoreEvaluationRequest,\\n    ScoreEvaluationResponse,\\n)\\n\\n\\nif is_fastapi_available():\\n    from fastapi import Depends, FastAPI, HTTPException, status\\n    from fastapi.middleware.cors import CORSMiddleware\\n    from fastapi.security.http import HTTPAuthorizationCredentials, HTTPBearer\\n\\n\\nif is_starlette_available():\\n    from sse_starlette import EventSourceResponse\\n\\n\\nif is_uvicorn_available():\\n    import uvicorn\\n\\n\\nasync def sweeper() -> None:\\n    while True:\\n        torch_gc()\\n        await asyncio.sleep(300)\\n\\n\\n@asynccontextmanager\\nasync def lifespan(app: \\\"FastAPI\\\", chat_model: \\\"ChatModel\\\"):  # collects GPU memory\\n    if chat_model.engine.name == EngineName.HF:\\n        asyncio.create_task(sweeper())\\n\\n    yield\\n    torch_gc()\\n\\n\\ndef create_app(chat_model: \\\"ChatModel\\\") -> \\\"FastAPI\\\":\\n    root_path = os.getenv(\\\"FASTAPI_ROOT_PATH\\\", \\\"\\\")\\n    app = FastAPI(lifespan=partial(lifespan, chat_model=chat_model), root_path=root_path)\\n    app.add_middleware(\\n        CORSMiddleware,\\n        allow_origins=[\\\"*\\\"],\\n        allow_credentials=True,\\n        allow_methods=[\\\"*\\\"],\\n        allow_headers=[\\\"*\\\"],\\n    )\\n    api_key = os.getenv(\\\"API_KEY\\\")\\n    security = HTTPBearer(auto_error=False)\\n\\n    async def verify_api_key(auth: Annotated[HTTPAuthorizationCredentials | None, Depends(security)]):\\n        if api_key and (auth is None or auth.credentials != api_key):\\n            raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=\\\"Invalid API key.\\\")\\n\\n    @app.get(\\n        \\\"/v1/models\\\",\\n        response_model=ModelList,\\n        status_code=status.HTTP_200_OK,\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def list_models():\\n        model_card = ModelCard(id=os.getenv(\\\"API_MODEL_NAME\\\", \\\"gpt-3.5-turbo\\\"))\\n        return ModelList(data=[model_card])\\n\\n    @app.post(\\n        \\\"/v1/chat/completions\\\",\\n        response_model=ChatCompletionResponse,\\n        status_code=status.HTTP_200_OK,\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def create_chat_completion(request: ChatCompletionRequest):\\n        if not chat_model.engine.can_generate:\\n            raise HTTPException(status_code=status.HTTP_405_METHOD_NOT_ALLOWED, detail=\\\"Not allowed\\\")\\n\\n        if request.stream:\\n            generate = create_stream_chat_completion_response(request, chat_model)\\n            return EventSourceResponse(generate, media_type=\\\"text/event-stream\\\", sep=\\\"\\\\n\\\")\\n        else:\\n            return await create_chat_completion_response(request, chat_model)\\n\\n    @app.post(\\n        \\\"/v1/score/evaluation\\\",\\n        response_model=ScoreEvaluationResponse,\\n        status_code=status.HTTP_200_OK,\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def create_score_evaluation(request: ScoreEvaluationRequest):\\n        if chat_model.engine.can_generate:\\n            raise HTTPException(status_code=status.HTTP_405_METHOD_NOT_ALLOWED, detail=\\\"Not allowed\\\")\\n\\n        return await create_score_evaluation_response(request, chat_model)\\n\\n    return app\\n\\n\\ndef run_api() -> None:\\n    chat_model = ChatModel()\\n    app = create_app(chat_model)\\n    api_host = os.getenv(\\\"API_HOST\\\", \\\"0.0.0.0\\\")\\n    api_port = int(os.getenv(\\\"API_PORT\\\", \\\"8000\\\"))\\n    print(f\\\"Visit http://localhost:{api_port}/docs for API document.\\\")\\n    uvicorn.run(app, host=api_host, port=api_port)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/api/chat.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5405184e016ec364d6d900ee3b427d972199a957a27f73df394d7384d12f351f\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport base64\\nimport io\\nimport json\\nimport os\\nimport re\\nimport uuid\\nfrom collections.abc import AsyncGenerator\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom ..data import Role as DataRole\\nfrom ..extras import logging\\nfrom ..extras.constants import AUDIO_PLACEHOLDER, IMAGE_PLACEHOLDER, VIDEO_PLACEHOLDER\\nfrom ..extras.misc import is_env_enabled\\nfrom ..extras.packages import is_fastapi_available, is_pillow_available, is_requests_available\\nfrom .common import check_lfi_path, check_ssrf_url, dictify, jsonify\\nfrom .protocol import (\\n    ChatCompletionMessage,\\n    ChatCompletionResponse,\\n    ChatCompletionResponseChoice,\\n    ChatCompletionResponseUsage,\\n    ChatCompletionStreamResponse,\\n    ChatCompletionStreamResponseChoice,\\n    Finish,\\n    Function,\\n    FunctionCall,\\n    Role,\\n    ScoreEvaluationResponse,\\n)\\n\\n\\nif is_fastapi_available():\\n    from fastapi import HTTPException, status\\n\\n\\nif is_pillow_available():\\n    from PIL import Image\\n\\n\\nif is_requests_available():\\n    import requests\\n\\n\\nif TYPE_CHECKING:\\n    from ..chat import ChatModel\\n    from ..data.mm_plugin import AudioInput, ImageInput, VideoInput\\n    from .protocol import ChatCompletionRequest, ScoreEvaluationRequest\\n\\n\\nlogger = logging.get_logger(__name__)\\nROLE_MAPPING = {\\n    Role.USER: DataRole.USER.value,\\n    Role.ASSISTANT: DataRole.ASSISTANT.value,\\n    Role.SYSTEM: DataRole.SYSTEM.value,\\n    Role.FUNCTION: DataRole.FUNCTION.value,\\n    Role.TOOL: DataRole.OBSERVATION.value,\\n}\\n\\n\\ndef _process_request(\\n    request: \\\"ChatCompletionRequest\\\",\\n) -> tuple[\\n    list[dict[str, str]],\\n    Optional[str],\\n    Optional[str],\\n    Optional[list[\\\"ImageInput\\\"]],\\n    Optional[list[\\\"VideoInput\\\"]],\\n    Optional[list[\\\"AudioInput\\\"]],\\n]:\\n    if is_env_enabled(\\\"API_VERBOSE\\\", \\\"1\\\"):\\n        logger.info_rank0(f\\\"==== request ====\\\\n{json.dumps(dictify(request), indent=2, ensure_ascii=False)}\\\")\\n\\n    if len(request.messages) == 0:\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Invalid length\\\")\\n\\n    if request.messages[0].role == Role.SYSTEM:\\n        content = request.messages.pop(0).content\\n        if isinstance(content, list):\\n            system = content[0].text if content else \\\"\\\"\\n        else:\\n            system = content\\n    else:\\n        system = None\\n\\n    if len(request.messages) % 2 == 0:\\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Only supports u/a/u/a/u...\\\")\\n\\n    input_messages = []\\n    images, videos, audios = [], [], []\\n    for i, message in enumerate(request.messages):\\n        if i % 2 == 0 and message.role not in [Role.USER, Role.TOOL]:\\n            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Invalid role\\\")\\n        elif i % 2 == 1 and message.role not in [Role.ASSISTANT, Role.FUNCTION]:\\n            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=\\\"Invalid role\\\")\\n\\n        if message.role == Role.ASSISTANT and isinstance(message.tool_calls, list) and len(message.tool_calls):\\n            tool_calls = [\\n                {\\\"name\\\": tool_call.function.name, \\\"arguments\\\": tool_call.function.arguments}\\n                for tool_call in message.tool_calls\\n            ]\\n            content = json.dumps(tool_calls, ensure_ascii=False)\\n            input_messages.append({\\\"role\\\": ROLE_MAPPING[Role.FUNCTION], \\\"content\\\": content})\\n        elif isinstance(message.content, list):\\n            text_content = \\\"\\\"\\n            for input_item in message.content:\\n                if input_item.type == \\\"text\\\":\\n                    text_content += input_item.text\\n                elif input_item.type == \\\"image_url\\\":\\n                    text_content += IMAGE_PLACEHOLDER\\n                    image_url = input_item.image_url.url\\n                    if re.match(r\\\"^data:image\\\\/(png|jpg|jpeg|gif|bmp);base64,(.+)$\\\", image_url):  # base64 image\\n                        image_stream = io.BytesIO(base64.b64decode(image_url.split(\\\",\\\", maxsplit=1)[1]))\\n                    elif os.path.isfile(image_url):  # local file\\n                        check_lfi_path(image_url)\\n                        image_stream = open(image_url, \\\"rb\\\")\\n                    else:  # web uri\\n                        check_ssrf_url(image_url)\\n                        image_stream = requests.get(image_url, stream=Tru";
